package main

import (
	"unicode"
	"unicode/utf8"
)

// Chars holds either an ASCII byte slice or a rune slice
type Chars struct {
	bytes   []byte
	runes   []rune
	inBytes bool
}

func isASCIIBytes(b []byte) bool {
	for _, c := range b {
		if c >= utf8.RuneSelf {
			return false
		}
	}
	return true
}

func ToChars(b []byte) Chars {
	if isASCIIBytes(b) {
		return Chars{bytes: b, inBytes: true}
	}
	runes := make([]rune, 0, len(b))
	for i := 0; i < len(b); {
		r, sz := utf8.DecodeRune(b[i:])
		i += sz
		runes = append(runes, r)
	}
	return Chars{runes: runes}
}

func RunesToChars(r []rune) Chars {
	return Chars{runes: r}
}

func (c *Chars) IsBytes() bool { return c.inBytes }

func (c *Chars) Bytes() []byte { return c.bytes }

func (c *Chars) Length() int {
	if c.inBytes {
		return len(c.bytes)
	}
	return len(c.runes)
}

func (c *Chars) Get(i int) rune {
	if c.inBytes {
		return rune(c.bytes[i])
	}
	return c.runes[i]
}

func (c *Chars) ToString() string {
	if c.inBytes {
		return string(c.bytes)
	}
	return string(c.runes)
}

func (c *Chars) ToRunes() []rune {
	if c.inBytes {
		r := make([]rune, len(c.bytes))
		for i, b := range c.bytes {
			r[i] = rune(b)
		}
		return r
	}
	return c.runes
}

func (c *Chars) CopyRunes(dest []rune, from int) {
	if c.inBytes {
		for i := range dest {
			dest[i] = rune(c.bytes[from+i])
		}
		return
	}
	copy(dest, c.runes[from:])
}

func (c *Chars) LeadingWhitespaces() int {
	n := 0
	l := c.Length()
	for i := 0; i < l; i++ {
		if !unicode.IsSpace(c.Get(i)) {
			break
		}
		n++
	}
	return n
}

func (c *Chars) TrailingWhitespaces() int {
	n := 0
	for i := c.Length() - 1; i >= 0; i-- {
		if !unicode.IsSpace(c.Get(i)) {
			break
		}
		n++
	}
	return n
}

func (c *Chars) TrimLength() int {
	l := c.Length()
	var i int
	for i = l - 1; i >= 0; i-- {
		if !unicode.IsSpace(c.Get(i)) {
			break
		}
	}
	if i < 0 {
		return 0
	}
	var j int
	for j = 0; j < l; j++ {
		if !unicode.IsSpace(c.Get(j)) {
			break
		}
	}
	return i - j + 1
}

func (c *Chars) TrimSuffixLength() int {
	return c.Length() - c.TrailingWhitespaces()
}
EOF"}

