{"command":"cd /workspace && cat > algo.go <<'EOF'
package main

import (
	"bytes"
	"strings"
	"unicode"
)

type charClass int

const (
	charWhite charClass = iota
	charNonWord
	charDelimiter
	charLower
	charUpper
	charLetter
	charNumber
)

const (
	scoreMatch        = 16
	scoreGapStart     = -3
	scoreGapExtension = -1

	bonusBoundary    = scoreMatch / 2
	bonusNonWord     = scoreMatch / 2
	bonusCamel123    = bonusBoundary + scoreGapExtension
	bonusConsecutive = -(scoreGapStart + scoreGapExtension)

	bonusFirstCharMultiplier = 2
)

var (
	bonusBoundaryWhite     int16 = bonusBoundary + 2
	bonusBoundaryDelimiter int16 = bonusBoundary + 1
	initialCharClass             = charWhite
	delimiterChars               = "/,:;|"
	asciiCharClasses       [unicode.MaxASCII + 1]charClass
	bonusMatrix            [charNumber + 1][charNumber + 1]int16
)

const whiteChars = " \t\n\v\f\r\x85\xA0"

const slab16Size = 100 * 1024
const slab32Size = 2048

func init() {
	algoInit("default")
}

func algoInit(scheme string) bool {
	switch scheme {
	case "default":
		bonusBoundaryWhite = bonusBoundary + 2
		bonusBoundaryDelimiter = bonusBoundary + 1
		delimiterChars = "/,:;|"
		initialCharClass = charWhite
	case "path":
		bonusBoundaryWhite = bonusBoundary
		bonusBoundaryDelimiter = bonusBoundary + 1
		delimiterChars = "/"
		initialCharClass = charDelimiter
	case "history":
		bonusBoundaryWhite = bonusBoundary
		bonusBoundaryDelimiter = bonusBoundary
		delimiterChars = "/,:;|"
		initialCharClass = charWhite
	default:
		return false
	}
	for i := 0; i <= unicode.MaxASCII; i++ {
		char := rune(i)
		c := charNonWord
		if char >= 'a' && char <= 'z' {
			c = charLower
		} else if char >= 'A' && char <= 'Z' {
			c = charUpper
		} else if char >= '0' && char <= '9' {
			c = charNumber
		} else if strings.ContainsRune(whiteChars, char) {
			c = charWhite
		} else if strings.ContainsRune(delimiterChars, char) {
			c = charDelimiter
		}
		asciiCharClasses[i] = c
	}
	for i := 0; i < int(charNumber+1); i++ {
		for j := 0; j < int(charNumber+1); j++ {
			bonusMatrix[i][j] = bonusFor(charClass(i), charClass(j))
		}
	}
	return true
}

func bonusFor(prevClass charClass, class charClass) int16 {
	if class > charNonWord {
		switch prevClass {
		case charWhite:
			return bonusBoundaryWhite
		case charDelimiter:
			return bonusBoundaryDelimiter
		case charNonWord:
			return bonusBoundary
		}
	}
	if prevClass == charLower && class == charUpper ||
		prevClass != charNumber && class == charNumber {
		return bonusCamel123
	}
	switch class {
	case charNonWord, charDelimiter:
		return bonusNonWord
	case charWhite:
		return bonusBoundaryWhite
	}
	return 0
}

func charClassOfNonASCII(char rune) charClass {
	if unicode.IsLower(char) {
		return charLower
	} else if unicode.IsUpper(char) {
		return charUpper
	} else if unicode.IsNumber(char) {
		return charNumber
	} else if unicode.IsLetter(char) {
		return charLetter
	} else if unicode.IsSpace(char) {
		return charWhite
	} else if strings.ContainsRune(delimiterChars, char) {
		return charDelimiter
	}
	return charNonWord
}

func charClassOf(char rune) charClass {
	if char <= unicode.MaxASCII {
		return asciiCharClasses[char]
	}
	return charClassOfNonASCII(char)
}

func bonusAt(input *Chars, idx int) int16 {
	if idx == 0 {
		return bonusMatrix[initialCharClass][charClassOf(input.Get(0))]
	}
	return bonusMatrix[charClassOf(input.Get(idx-1))][charClassOf(input.Get(idx))]
}

func normalizeRune(r rune) rune {
	if r < 0x00C0 || r > 0xFF61 {
		return r
	}
	if n, ok := normTable[r]; ok {
		return n
	}
	return r
}

func normalizeRunes(runes []rune) []rune {
	ret := make([]rune, len(runes))
	for i, r := range runes {
		ret[i] = normalizeRune(r)
	}
	return ret
}

type AlgoResult struct {
	Start int
	End   int
	Score int
}

type AlgoFunc func(caseSensitive bool, normalize bool, forward bool, input *Chars, pattern []rune, withPos bool) (AlgoResult, *[]int)

func posArray(withPos bool, n int) *[]int {
	if withPos {
		pos := make([]int, 0, n)
		return &pos
	}
	return nil
}

func indexAt(index int, max int, forward bool) int {
	if forward {
		return index
	}
	return max - index - 1
}

func trySkip(input *Chars, caseSensitive bool, b byte, from int) int {
	byteArray := input.Bytes()[from:]
	idx := bytes.IndexByte(byteArray, b)
	if idx == 0 {
		return from
	}
	if !caseSensitive && b >= 'a' && b <= 'z' {
		if idx > 0 {
			byteArray = byteArray[:idx]
		}
		uidx := bytes.IndexByte(byteArray, b-32)
		if uidx >= 0 {
			idx = uidx
		}
	}
	if idx < 0 {
		return -1
	}
	return from + idx
}

func isASCIIRunes(runes []rune) bool {
	for _, r := range runes {
		if r >= 0x80 {
			return false
		}
	}
	return true
}

func asciiFuzzyIndex(input *Chars, pattern []rune, caseSensitive bool) (int, int) {
	if !input.IsBytes() {
		return 0, input.Length()
	}
	if !isASCIIRunes(pattern) {
		return -1, -1
	}
	firstIdx, idx, lastIdx := 0, 0, 0
	var b byte
	for pidx := 0; pidx < len(pattern); pidx++ {
		b = byte(pattern[pidx])
		idx = trySkip(input, caseSensitive, b, idx)
		if idx < 0 {
			return -1, -1
		}
		if pidx == 0 && idx > 0 {
			firstIdx = idx - 1
		}
		lastIdx = idx
		idx++
	}
	bu := b
	if !caseSensitive && b >= 'a' && b <= 'z' {
		bu = b - 32
	}
	scope := input.Bytes()[lastIdx:]
	for offset := len(scope) - 1; offset > 0; offset-- {
		if scope[offset] == b || scope[offset] == bu {
			return firstIdx, lastIdx + offset + 1
		}
	}
	return firstIdx, lastIdx + 1
}

func max16(a, b int16) int16 {
	if a > b {
		return a
	}
	return b
}

func lowerRune(char rune) rune {
	if char >= 'A' && char <= 'Z' {
		return char + 32
	} else if char > unicode.MaxASCII {
		return unicode.To(unicode.LowerCase, char)
	}
	return char
}

func FuzzyMatchV2(caseSensitive bool, normalize bool, forward bool, input *Chars, pattern []rune, withPos bool) (AlgoResult, *[]int) {
	M := len(pattern)
	if M == 0 {
		return AlgoResult{0, 0, 0}, posArray(withPos, M)
	}
	N := input.Length()
	if M > N {
		return AlgoResult{-1, -1, 0}, nil
	}
	if N*M > slab16Size {
		return FuzzyMatchV1(caseSensitive, normalize, forward, input, pattern, withPos)
	}

	minIdx, maxIdx := asciiFuzzyIndex(input, pattern, caseSensitive)
	if minIdx < 0 {
		return AlgoResult{-1, -1, 0}, nil
	}
	N = maxIdx - minIdx

	H0 := make([]int16, N)
	C0 := make([]int16, N)
	B := make([]int16, N)
	F := make([]int32, M)
	T := make([]rune, N)
	input.CopyRunes(T, minIdx)

	maxScore, maxScorePos := int16(0), 0
	pidx, lastIdx := 0, 0
	pchar0, pchar, prevH0, prevClass, inGap := pattern[0], pattern[0], int16(0), initialCharClass, false
	for off, char := range T {
		var class charClass
		if char <= unicode.MaxASCII {
			class = asciiCharClasses[char]
			if !caseSensitive && class == charUpper {
				char += 32
				T[off] = char
			}
		} else {
			class = charClassOfNonASCII(char)
			if !caseSensitive && class == charUpper {
				char = unicode.To(unicode.LowerCase, char)
			}
			if normalize {
				char = normalizeRune(char)
			}
			T[off] = char
		}

		bonus := bonusMatrix[prevClass][class]
		B[off] = bonus
		prevClass = class

		if char == pchar {
			if pidx < M {
				F[pidx] = int32(off)
				pidx++
				pchar = pattern[min(pidx, M-1)]
			}
			lastIdx = off
		}

		if char == pchar0 {
			score := int16(scoreMatch) + bonus*bonusFirstCharMultiplier
			H0[off] = score
			C0[off] = 1
			if M == 1 && (forward && score > maxScore || !forward && score >= maxScore) {
				maxScore, maxScorePos = score, off
				if forward && bonus >= bonusBoundary {
					break
				}
			}
			inGap = false
		} else {
			if inGap {
				H0[off] = max16(prevH0+scoreGapExtension, 0)
			} else {
				H0[off] = max16(prevH0+scoreGapStart, 0)
			}
			C0[off] = 0
			inGap = true
		}
		prevH0 = H0[off]
	}
	if pidx != M {
		return AlgoResult{-1, -1, 0}, nil
	}
	if M == 1 {
		result := AlgoResult{minIdx + maxScorePos, minIdx + maxScorePos + 1, int(maxScore)}
		if !withPos {
			return result, nil
		}
		pos := []int{minIdx + maxScorePos}
		return result, &pos
	}

	f0 := int(F[0])
	width := lastIdx - f0 + 1
	H := make([]int16, width*M)
	copy(H, H0[f0:lastIdx+1])
	C := make([]int16, width*M)
	copy(C, C0[f0:lastIdx+1])

	Fsub := F[1:]
	Psub := pattern[1:][:len(Fsub)]
	for off, f := range Fsub {
		f := int(f)
		pchar := Psub[off]
		pidx := off + 1
		row := pidx * width
		inGap := false
		Tsub := T[f : lastIdx+1]
		Bsub := B[f:][:len(Tsub)]
		Csub := C[row+f-f0:][:len(Tsub)]
		Cdiag := C[row+f-f0-1-width:][:len(Tsub)]
		Hsub := H[row+f-f0:][:len(Tsub)]
		Hdiag := H[row+f-f0-1-width:][:len(Tsub)]
		Hleft := H[row+f-f0-1:][:len(Tsub)]
		Hleft[0] = 0
		for off, char := range Tsub {
			col := off + f
			var s1, s2, consecutive int16

			if inGap {
				s2 = Hleft[off] + scoreGapExtension
			} else {
				s2 = Hleft[off] + scoreGapStart
			}

			if pchar == char {
				s1 = Hdiag[off] + scoreMatch
				b := Bsub[off]
				consecutive = Cdiag[off] + 1
				if consecutive > 1 {
					fb := B[col-int(consecutive)+1]
					if b >= bonusBoundary && b > fb {
						consecutive = 1
					} else {
						b = max16(b, max16(bonusConsecutive, fb))
					}
				}
				if s1+b < s2 {
					s1 += Bsub[off]
					consecutive = 0
				} else {
					s1 += b
				}
			}
			Csub[off] = consecutive

			inGap = s1 < s2
			score := max16(max16(s1, s2), 0)
			if pidx == M-1 && (forward && score > maxScore || !forward && score >= maxScore) {
				maxScore, maxScorePos = score, col
			}
			Hsub[off] = score
		}
	}

	pos := posArray(withPos, M)
	j := f0
	if withPos {
		i := M - 1
		j = maxScorePos
		preferMatch := true
		for {
			I := i * width
			j0 := j - f0
			s := H[I+j0]

			var s1, s2 int16
			if i > 0 && j >= int(F[i]) {
				s1 = H[I-width+j0-1]
			}
			if j > int(F[i]) {
				s2 = H[I+j0-1]
			}

			if s > s1 && (s > s2 || s == s2 && preferMatch) {
				*pos = append(*pos, j+minIdx)
				if i == 0 {
					break
				}
				i--
			}
			preferMatch = C[I+j0] > 1 || I+width+j0+1 < len(C) && C[I+width+j0+1] > 0
