}

func calculateScore(caseSensitive bool, normalize bool, text *Chars, pattern []rune, sidx int, eidx int, withPos bool) (int, *[]int) {
	pidx, score, inGap, consecutive, firstBonus := 0, 0, false, 0, int16(0)
	pos := posArray(withPos, len(pattern))
	prevClass := initialCharClass
	if sidx > 0 {
		prevClass = charClassOf(text.Get(sidx - 1))
	}
	for idx := sidx; idx < eidx; idx++ {
		char := text.Get(idx)
		class := charClassOf(char)
		if !caseSensitive {
			char = lowerRune(char)
		}
		if normalize {
			char = normalizeRune(char)
		}
		if char == pattern[pidx] {
			if withPos {
				*pos = append(*pos, idx)
			}
			score += scoreMatch
			bonus := bonusMatrix[prevClass][class]
			if consecutive == 0 {
				firstBonus = bonus
			} else {
				if bonus >= bonusBoundary && bonus > firstBonus {
					firstBonus = bonus
				}
				bonus = max16(max16(bonus, firstBonus), bonusConsecutive)
			}
			if pidx == 0 {
				score += int(bonus * bonusFirstCharMultiplier)
			} else {
				score += int(bonus)
			}
			inGap = false
			consecutive++
			pidx++
		} else {
			if inGap {
				score += scoreGapExtension
			} else {
				score += scoreGapStart
			}
			inGap = true
			consecutive = 0
			firstBonus = 0
		}
		prevClass = class
	}
	return score, pos
}

func FuzzyMatchV1(caseSensitive bool, normalize bool, forward bool, text *Chars, pattern []rune, withPos bool) (AlgoResult, *[]int) {
	if len(pattern) == 0 {
		return AlgoResult{0, 0, 0}, nil
	}
	idx, _ := asciiFuzzyIndex(text, pattern, caseSensitive)
	if idx < 0 {
		return AlgoResult{-1, -1, 0}, nil
	}

	pidx := 0
	sidx := -1
	eidx := -1

	lenRunes := text.Length()
	lenPattern := len(pattern)

	for index := 0; index < lenRunes; index++ {
		char := text.Get(indexAt(index, lenRunes, forward))
		if !caseSensitive {
			char = lowerRune(char)
		}
		if normalize {
			char = normalizeRune(char)
		}
		pchar := pattern[indexAt(pidx, lenPattern, forward)]
		if char == pchar {
			if sidx < 0 {
				sidx = index
			}
			if pidx++; pidx == lenPattern {
				eidx = index + 1
				break
			}
		}
	}

	if sidx >= 0 && eidx >= 0 {
		pidx--
		for index := eidx - 1; index >= sidx; index-- {
			tidx := indexAt(index, lenRunes, forward)
			char := text.Get(tidx)
			if !caseSensitive {
				char = lowerRune(char)
			}
			if normalize {
				char = normalizeRune(char)
			}
			pidx_ := indexAt(pidx, lenPattern, forward)
			pchar := pattern[pidx_]
			if char == pchar {
				if pidx--; pidx < 0 {
					sidx = index
					break
				}
			}
		}

		if !forward {
			sidx, eidx = lenRunes-eidx, lenRunes-sidx
		}

		score, pos := calculateScore(caseSensitive, normalize, text, pattern, sidx, eidx, withPos)
		return AlgoResult{sidx, eidx, score}, pos
	}
	return AlgoResult{-1, -1, 0}, nil
}

func ExactMatchNaive(caseSensitive bool, normalize bool, forward bool, text *Chars, pattern []rune, withPos bool) (AlgoResult, *[]int) {
	return exactMatchNaive(caseSensitive, normalize, forward, false, text, pattern, withPos)
}

func ExactMatchBoundary(caseSensitive bool, normalize bool, forward bool, text *Chars, pattern []rune, withPos bool) (AlgoResult, *[]int) {
	return exactMatchNaive(caseSensitive, normalize, forward, true, text, pattern, withPos)
}

func exactMatchNaive(caseSensitive bool, normalize bool, forward bool, boundaryCheck bool, text *Chars, pattern []rune, withPos bool) (AlgoResult, *[]int) {
	if len(pattern) == 0 {
		return AlgoResult{0, 0, 0}, nil
	}

	lenRunes := text.Length()
	lenPattern := len(pattern)

	if lenRunes < lenPattern {
		return AlgoResult{-1, -1, 0}, nil
	}

	idx, _ := asciiFuzzyIndex(text, pattern, caseSensitive)
	if idx < 0 {
		return AlgoResult{-1, -1, 0}, nil
	}

	pidx := 0
	bestPos, bonus, bbonus, bestBonus := -1, int16(0), int16(0), int16(-1)
	for index := 0; index < lenRunes; index++ {
		index_ := indexAt(index, lenRunes, forward)
		char := text.Get(index_)
		if !caseSensitive {
			char = lowerRune(char)
		}
		if normalize {
			char = normalizeRune(char)
		}
		pidx_ := indexAt(pidx, lenPattern, forward)
		pchar := pattern[pidx_]
		ok := pchar == char
		if ok {
			if pidx_ == 0 {
				bonus = bonusAt(text, index_)
			}
			if boundaryCheck {
				if forward && pidx_ == 0 {
					bbonus = bonus
				} else if !forward && pidx_ == lenPattern-1 {
					if index_ < lenRunes-1 {
						bbonus = bonusAt(text, index_+1)
					} else {
						bbonus = bonusBoundaryWhite
					}
				}
				ok = bbonus >= bonusBoundary
				if ok && pidx_ == 0 {
					ok = index_ == 0 || charClassOf(text.Get(index_-1)) <= charDelimiter
				}
				if ok && pidx_ == lenPattern-1 {
					ok = index_ == lenRunes-1 || charClassOf(text.Get(index_+1)) <= charDelimiter
				}
			}
		}
		if ok {
			pidx++
			if pidx == lenPattern {
				if bonus > bestBonus {
					bestPos, bestBonus = index, bonus
				}
				if bonus >= bonusBoundary {
					break
				}
				index -= pidx - 1
				pidx, bonus = 0, 0
			}
		} else {
			index -= pidx
			pidx, bonus = 0, 0
		}
	}
	if bestPos >= 0 {
		var sidx, eidx int
		if forward {
			sidx = bestPos - lenPattern + 1
			eidx = bestPos + 1
		} else {
			sidx = lenRunes - (bestPos + 1)
			eidx = lenRunes - (bestPos - lenPattern + 1)
		}
		var score int
		if boundaryCheck {
			score = int(bestBonus)
			_ = score
			score, _ = calculateScore(caseSensitive, normalize, text, pattern, sidx, eidx, false)
			if sidx > 0 && text.Get(sidx-1) == '_' {
				score -= 4 // placeholder, verify
			}
			if eidx < lenRunes && text.Get(eidx) == '_' {
				score -= 4
			}
		} else {
			score, _ = calculateScore(caseSensitive, normalize, text, pattern, sidx, eidx, false)
		}
		return AlgoResult{sidx, eidx, score}, nil
	}
	return AlgoResult{-1, -1, 0}, nil
}

func PrefixMatch(caseSensitive bool, normalize bool, forward bool, text *Chars, pattern []rune, withPos bool) (AlgoResult, *[]int) {
	if len(pattern) == 0 {
		return AlgoResult{0, 0, 0}, nil
	}
	trimmedLen := 0
	if !unicode.IsSpace(pattern[0]) {
		trimmedLen = text.LeadingWhitespaces()
	}
	if text.Length()-trimmedLen < len(pattern) {
		return AlgoResult{-1, -1, 0}, nil
	}
	for index, r := range pattern {
		char := text.Get(trimmedLen + index)
		if !caseSensitive {
			char = unicode.ToLower(char)
		}
		if normalize {
			char = normalizeRune(char)
		}
		if char != r {
			return AlgoResult{-1, -1, 0}, nil
		}
	}
	lenPattern := len(pattern)
	score, _ := calculateScore(caseSensitive, normalize, text, pattern, trimmedLen, trimmedLen+lenPattern, false)
	return AlgoResult{trimmedLen, trimmedLen + lenPattern, score}, nil
}

func SuffixMatch(caseSensitive bool, normalize bool, forward bool, text *Chars, pattern []rune, withPos bool) (AlgoResult, *[]int) {
	lenRunes := text.Length()
	trimmedLen := lenRunes
	if len(pattern) == 0 || !unicode.IsSpace(pattern[len(pattern)-1]) {
		trimmedLen -= text.TrailingWhitespaces()
	}
	if len(pattern) == 0 {
		return AlgoResult{trimmedLen, trimmedLen, 0}, nil
	}
	diff := trimmedLen - len(pattern)
	if diff < 0 {
		return AlgoResult{-1, -1, 0}, nil
	}
	for index, r := range pattern {
		char := text.Get(index + diff)
		if !caseSensitive {
			char = unicode.ToLower(char)
		}
		if normalize {
			char = normalizeRune(char)
		}
		if char != r {
			return AlgoResult{-1, -1, 0}, nil
		}
	}
	lenPattern := len(pattern)
	sidx := trimmedLen - lenPattern
	eidx := trimmedLen
	score, _ := calculateScore(caseSensitive, normalize, text, pattern, sidx, eidx, false)
	return AlgoResult{sidx, eidx, score}, nil
}

func EqualMatch(caseSensitive bool, normalize bool, forward bool, text *Chars, pattern []rune, withPos bool) (AlgoResult, *[]int) {
	lenPattern := len(pattern)
	if lenPattern == 0 {
		return AlgoResult{-1, -1, 0}, nil
	}
	trimmedLen := 0
	if !unicode.IsSpace(pattern[0]) {
		trimmedLen = text.LeadingWhitespaces()
	}
	trimmedEndLen := 0
	if !unicode.IsSpace(pattern[lenPattern-1]) {
		trimmedEndLen = text.TrailingWhitespaces()
	}
	if text.Length()-trimmedLen-trimmedEndLen != lenPattern {
		return AlgoResult{-1, -1, 0}, nil
	}
	match := true
	if normalize {
		runes := text.ToRunes()
		for idx, pchar := range pattern {
			char := runes[trimmedLen+idx]
			if !caseSensitive {
				char = unicode.To(unicode.LowerCase, char)
			}
			if normalizeRune(pchar) != normalizeRune(char) {
				match = false
				break
			}
		}
	} else {
		runes := text.ToRunes()
		runesStr := string(runes[trimmedLen : len(runes)-trimmedEndLen])
		if !caseSensitive {
			runesStr = strings.ToLower(runesStr)
		}
		match = runesStr == string(pattern)
	}
	if match {
		return AlgoResult{trimmedLen, trimmedLen + lenPattern, (scoreMatch+int(bonusBoundaryWhite))*lenPattern +
			(bonusFirstCharMultiplier-1)*int(bonusBoundaryWhite)}, nil
	}
	return AlgoResult{-1, -1, 0}, nil
}
EOF

