package main

import (
	"errors"
	"regexp"
	"strconv"
	"strings"
	"unicode"
	"unicode/utf8"
)

const rangeEllipsis = 0

type Range struct {
	begin int
	end   int
}

type Token struct {
	text         *Chars
	prefixLength int32
}

type Delimiter struct {
	regex *regexp.Regexp
	str   *string
}

func (d Delimiter) IsAwk() bool {
	return d.regex == nil && d.str == nil
}

func newRange(begin int, end int) Range {
	if begin == 1 && end != 1 {
		begin = rangeEllipsis
	}
	if end == -1 {
		end = rangeEllipsis
	}
	return Range{begin, end}
}

func ParseRange(str *string) (Range, bool) {
	if (*str) == ".." {
		return newRange(rangeEllipsis, rangeEllipsis), true
	} else if strings.HasPrefix(*str, "..") {
		end, err := strconv.Atoi((*str)[2:])
		if err != nil || end == 0 {
			return Range{}, false
		}
		return newRange(rangeEllipsis, end), true
	} else if strings.HasSuffix(*str, "..") {
		begin, err := strconv.Atoi((*str)[:len(*str)-2])
		if err != nil || begin == 0 {
			return Range{}, false
		}
		return newRange(begin, rangeEllipsis), true
	} else if strings.Contains(*str, "..") {
		ns := strings.Split(*str, "..")
		if len(ns) != 2 {
			return Range{}, false
		}
		begin, err1 := strconv.Atoi(ns[0])
		end, err2 := strconv.Atoi(ns[1])
		if err1 != nil || err2 != nil || begin == 0 || end == 0 || begin < 0 && end > 0 {
			return Range{}, false
		}
		return newRange(begin, end), true
	}
	n, err := strconv.Atoi(*str)
	if err != nil || n == 0 {
		return Range{}, false
	}
	return newRange(n, n), true
}

var nthRegex = regexp.MustCompile(`^[0-9,\-.]+$`)

func splitNth(str string) ([]Range, error) {
	if !nthRegex.MatchString(str) {
		return nil, errors.New("invalid format: " + str)
	}
	tokens := strings.Split(str, ",")
	ranges := make([]Range, len(tokens))
	for idx, s := range tokens {
		r, ok := ParseRange(&s)
		if !ok {
			return nil, errors.New("invalid format: " + str)
		}
		ranges[idx] = r
	}
	return ranges, nil
}

func delimiterRegexp(str string) Delimiter {
	str = strings.ReplaceAll(str, "\\t", "\t")
	if regexp.QuoteMeta(str) == str {
		return Delimiter{str: &str}
	}
	rx, e := regexp.Compile(str)
	if e != nil {
		return Delimiter{str: &str}
	}
	return Delimiter{regex: rx}
}

func isWhitespaceByte(b byte) bool {
	return b == 9 || b == 32
}

func awkTokenizer(input string) ([]string, int) {
	ret := []string{}
	prefixLength := 0
	const (
		awkNil = iota
		awkBlack
		awkWhite
	)
	state := awkNil
	begin := 0
	end := 0
	for idx := 0; idx < len(input); idx++ {
		r := input[idx]
		white := isWhitespaceByte(r)
		switch state {
		case awkNil:
			if white {
				prefixLength++
			} else {
				state, begin, end = awkBlack, idx, idx+1
			}
		case awkBlack:
			end = idx + 1
			if white {
				state = awkWhite
			}
		case awkWhite:
			if white {
				end = idx + 1
			} else {
				ret = append(ret, input[begin:end])
				state, begin, end = awkBlack, idx, idx+1
			}
		}
	}
	if begin < end {
		ret = append(ret, input[begin:end])
	}
	return ret, prefixLength
}

func withPrefixLengths(tokens []string, begin int) []Token {
	ret := make([]Token, len(tokens))
	prefixLength := begin
	for idx := range tokens {
		chars := ToChars([]byte(tokens[idx]))
		ret[idx] = Token{&chars, int32(prefixLength)}
		prefixLength += chars.Length()
	}
	return ret
}

func Tokenize(text string, delimiter Delimiter) []Token {
	if delimiter.str == nil && delimiter.regex == nil {
		tokens, prefixLength := awkTokenizer(text)
		return withPrefixLengths(tokens, prefixLength)
	}
	if delimiter.str != nil {
		return withPrefixLengths(strings.SplitAfter(text, *delimiter.str), 0)
	}
	var tokens []string
	locs := delimiter.regex.FindAllStringIndex(text, -1)
	begin := 0
	for _, loc := range locs {
		tokens = append(tokens, text[begin:loc[1]])
		begin = loc[1]
	}
	if begin < len(text) {
		tokens = append(tokens, text[begin:])
	}
	return withPrefixLengths(tokens, 0)
}

func StripLastDelimiter(str string, delimiter Delimiter) string {
	if delimiter.str != nil {
		str = strings.TrimSuffix(str, *delimiter.str)
	} else if delimiter.regex != nil {
		locs := delimiter.regex.FindAllStringIndex(str, -1)
		if len(locs) > 0 {
			lastLoc := locs[len(locs)-1]
			if lastLoc[1] == len(str) {
				str = str[:lastLoc[0]]
			}
		}
	}
	return strings.TrimRightFunc(str, unicode.IsSpace)
}

func joinTokens(tokens []Token) string {
	var sb strings.Builder
	for _, token := range tokens {
		sb.WriteString(token.text.ToString())
	}
	return sb.String()
}

func Transform(tokens []Token, withNth []Range) []Token {
	transTokens := make([]Token, len(withNth))
	numTokens := len(tokens)
	for idx, r := range withNth {
		parts := []*Chars{}
		minIdx := 0
		if r.begin == r.end {
			idx := r.begin
			if idx == rangeEllipsis {
				chars := ToChars([]byte(joinTokens(tokens)))
				parts = append(parts, &chars)
			} else {
				if idx < 0 {
					idx += numTokens + 1
				}
				if idx >= 1 && idx <= numTokens {
					minIdx = idx - 1
					parts = append(parts, tokens[idx-1].text)
				}
			}
		} else {
			var begin, end int
			if r.begin == rangeEllipsis {
				begin, end = 1, r.end
				if end < 0 {
					end += numTokens + 1
				}
			} else if r.end == rangeEllipsis {
				begin, end = r.begin, numTokens
				if begin < 0 {
					begin += numTokens + 1
				}
			} else {
				begin, end = r.begin, r.end
				if begin < 0 {
					begin += numTokens + 1
				}
				if end < 0 {
					end += numTokens + 1
				}
			}
			minIdx = max(0, begin-1)
			for idx := begin; idx <= end; idx++ {
				if idx >= 1 && idx <= numTokens {
					parts = append(parts, tokens[idx-1].text)
				}
			}
		}
		var merged Chars
		switch len(parts) {
		case 0:
			merged = ToChars([]byte{})
		case 1:
			merged = *parts[0]
		default:
			var sb strings.Builder
			for _, part := range parts {
				sb.WriteString(part.ToString())
			}
			merged = ToChars([]byte(sb.String()))
		}
		var prefixLength int32
		if minIdx < numTokens {
			prefixLength = tokens[minIdx].prefixLength
		}
		transTokens[idx] = Token{&merged, prefixLength}
	}
	return transTokens
}

// Template for --with-nth / --accept-nth
type nthTemplatePart struct {
	literal string
	ranges  []Range
	isIndex bool
	isExpr  bool
}

type NthTemplate struct {
	parts  []nthTemplatePart
	simple []Range // non-nil if not a template
}

var templatePlaceholderRegex = regexp.MustCompile(`\\?\{[^{}]*\}`)

func parseNthTemplate(str string) (*NthTemplate, error) {
	if nthRegex.MatchString(str) {
		ranges, err := splitNth(str)
		if err != nil {
			return nil, err
		}
		return &NthTemplate{simple: ranges}, nil
	}
	tmpl := &NthTemplate{}
	found := false
	last := 0
	for _, loc := range templatePlaceholderRegex.FindAllStringIndex(str, -1) {
		match := str[loc[0]:loc[1]]
		if match[0] == '\\' {
			continue
		}
		inner := match[1 : len(match)-1]
		var part nthTemplatePart
		if inner == "n" {
			part = nthTemplatePart{isIndex: true, isExpr: true}
		} else {
			if !nthRegex.MatchString(inner) {
				continue
			}
			ranges, err := splitNth(inner)
			if err != nil {
				continue
			}
			part = nthTemplatePart{ranges: ranges, isExpr: true}
		}
		if loc[0] > last {
			tmpl.parts = append(tmpl.parts, nthTemplatePart{literal: str[last:loc[0]]})
		}
		tmpl.parts = append(tmpl.parts, part)
		last = loc[1]
		found = true
	}
	if !found {
		return nil, errors.New("template should include at least 1 placeholder: " + str)
	}
	if last < len(str) {
		tmpl.parts = append(tmpl.parts, nthTemplatePart{literal: str[last:]})
	}
	return tmpl, nil
}

func (t *NthTemplate) applyTemplate(tokens []Token, index int32, delimiter Delimiter) string {
	var sb strings.Builder
	for _, part := range t.parts {
		if !part.isExpr {
			sb.WriteString(part.literal)
		} else if part.isIndex {
			sb.WriteString(strconv.Itoa(int(index)))
		} else {
			trans := Transform(tokens, part.ranges)
			sb.WriteString(StripLastDelimiter(joinTokens(trans), delimiter))
		}
	}
	return sb.String()
}

func runeLen(s string) int {
	return utf8.RuneCountInString(s)
}
EOF"}

