			}
			return -1
		}
	}
	return -1
}

func isCtrlSeqStart(c uint8) bool {
	switch c {
	case '\\', '[', '(', ')':
		return true
	}
	return false
}

// nextAnsiEscapeSequence returns the ANSI escape sequence and is equivalent to
// calling FindStringIndex() on the regex
func nextAnsiEscapeSequence(s string) (int, int) {
	for i := 0; i < len(s); i++ {
		switch s[i] {
		case '\x0e', '\x0f':
			return i, i + 1
		case '\x1b':
			if i+2 < len(s) && isCtrlSeqStart(s[i+1]) {
				if j := matchControlSequence(s[i+2:]); j != -1 {
					return i, i + 2 + j
				}
			}
			// OSC
			if i+5 < len(s) && s[i+1] == ']' {
				j := 2
				for ; i+j < len(s) && s[i+j] >= '0' && s[i+j] <= '9'; j++ {
				}
				if j > 2 && i+j+1 < len(s) && (s[i+j] == ';' || s[i+j] == ':') && isPrint(s[i+j+1]) {
					if k := matchOperatingSystemCommand(s[i:], j+2); k != -1 {
						return i, i + k
					}
				}
			}
			if i+1 < len(s) {
				// two-character sequence
				_, sz := utf8.DecodeRuneInString(s[i+1:])
				return i, i + 1 + sz
			}
		case '\x08':
			if i > 0 {
				// .\x08
				_, sz := utf8.DecodeLastRuneInString(s[:i])
				return i - sz, i + 1
			}
		}
	}
	return -1, -1
}

func extractColor(str string, state *ansiState, proc func(string, *ansiState) bool) (string, *[]ansiOffset, *ansiState) {
	var offsets []ansiOffset
	var output strings.Builder

	if state != nil {
		offsets = append(offsets, ansiOffset{[2]int32{0, 0}, *state})
	}

	prevIdx := 0
	runeCount := 0
	for idx := 0; idx < len(str); {
		start, end := nextAnsiEscapeSequence(str[idx:])
		if start == -1 {
			break
		}
		start += idx
		idx += end

		prev := str[prevIdx:start]
		runeCount += utf8.RuneCountInString(prev)
		output.WriteString(prev)

		code := str[start:idx]
		newState := interpretCode(code, state)
		if !newState.equals(state) {
			if state != nil {
				(&offsets[len(offsets)-1]).offset[1] = int32(runeCount)
			}
			if newState.colored() {
				state = newState
				offsets = append(offsets, ansiOffset{[2]int32{int32(runeCount), int32(runeCount)}, *state})
			} else {
				state = nil
			}
			if proc != nil && !proc(prev, state) {
				return "", nil, nil
			}
		}
		prevIdx = idx
	}

	var rest string
	var trimmed string
	if prevIdx == 0 {
		rest = str
		trimmed = str
	} else {
		rest = str[prevIdx:]
		output.WriteString(rest)
		trimmed = output.String()
	}
	if proc != nil {
		proc(rest, state)
	}
	if len(offsets) > 0 {
		if len(rest) > 0 && state != nil {
			runeCount += utf8.RuneCountInString(rest)
			(&offsets[len(offsets)-1]).offset[1] = int32(runeCount)
		}
		// drop zero-length offsets
		filtered := offsets[:0]
		for _, o := range offsets {
			if o.offset[1] > o.offset[0] {
				filtered = append(filtered, o)
			}
		}
		offsets = filtered
	}
	if len(offsets) == 0 {
		return trimmed, nil, state
	}
	return trimmed, &offsets, state
}

func parseAnsiCode(s string) (int, string) {
	var remaining string
	var i int
	// Find the first separator
	for i = 0; i < len(s); i++ {
		if s[i] == ';' || s[i] == ':' {
			remaining = s[i+1:]
			s = s[:i]
			break
		}
	}
	if len(s) > 0 {
		code, err := strconv.Atoi(s)
		if err == nil {
			return code, remaining
		}
		return -1, remaining
	}
	return -1, remaining
}

func interpretCode(ansiCode string, prevState *ansiState) ansiState {
	var state ansiState
	if prevState == nil {
		state = ansiState{-1, -1, -1, 0, -1, nil}
	} else {
		state = ansiState{prevState.fg, prevState.bg, prevState.ul, prevState.attr, prevState.lbg, prevState.url}
	}
	if ansiCode[0] != '\x1b' || ansiCode[1] != '[' || ansiCode[len(ansiCode)-1] != 'm' {
		if prevState != nil && (strings.HasSuffix(ansiCode, "0K") || strings.HasSuffix(ansiCode, "[K")) {
			state.lbg = prevState.bg
		} else if ansiCode[0] == '\x1b' && len(ansiCode) > 4 && ansiCode[1] == ']' && ansiCode[2] == '8' && (ansiCode[3] == ';' || ansiCode[3] == ':') {
			stLen := 2
			if strings.HasSuffix(ansiCode, "\x07") {
				stLen = 1
			}
			// OSC 8 ; params ; uri ST
			body := ansiCode[4 : len(ansiCode)-stLen]
			if idx := strings.IndexAny(body, ";:"); idx >= 0 {
				params := body[:idx]
				uri := body[idx+1:]
				if len(uri) > 0 {
					state.url = &url{uri: uri, params: params}
				} else {
					state.url = nil
				}
			}
		}
		return state
	}

	if len(ansiCode) <= 3 {
		state.fg = -1
		state.bg = -1
		state.ul = -1
		state.attr = 0
		return state
	}
	ansiCode = ansiCode[2 : len(ansiCode)-1]

	state256 := 0
	ptr := &state.fg
	count := 0

	for len(ansiCode) != 0 {
		var num int
		if num, ansiCode = parseAnsiCode(ansiCode); num != -1 {
			count++
			switch state256 {
			case 0:
				switch num {
				case 38:
					ptr = &state.fg
					state256++
				case 48:
					ptr = &state.bg
					state256++
				case 58:
					ptr = &state.ul
					state256++
				case 39:
					state.fg = -1
				case 49:
					state.bg = -1
				case 59:
					state.ul = -1
				case 1:
					state.attr = state.attr | tAttrBold
				case 2:
					state.attr = state.attr | tAttrDim
				case 3:
					state.attr = state.attr | tAttrItalic
				case 4:
					state.attr = state.attr | tAttrUnderline
				case 5:
					state.attr = state.attr | tAttrBlink
				case 7:
					state.attr = state.attr | tAttrReverse
				case 9:
					state.attr = state.attr | tAttrStrikeThrough
				case 22:
					state.attr = state.attr &^ tAttrBold
					state.attr = state.attr &^ tAttrDim
				case 23:
					state.attr = state.attr &^ tAttrItalic
				case 24:
					state.attr = state.attr &^ tAttrUnderline
				case 25:
					state.attr = state.attr &^ tAttrBlink
				case 27:
					state.attr = state.attr &^ tAttrReverse
				case 29:
					state.attr = state.attr &^ tAttrStrikeThrough
				case 0:
					state.fg = -1
					state.bg = -1
					state.ul = -1
					state.attr = 0
					state256 = 0
				default:
					if num >= 30 && num <= 37 {
						state.fg = tColor(num - 30)
					} else if num >= 40 && num <= 47 {
						state.bg = tColor(num - 40)
					} else if num >= 90 && num <= 97 {
						state.fg = tColor(num - 90 + 8)
					} else if num >= 100 && num <= 107 {
						state.bg = tColor(num - 100 + 8)
					}
				}
			case 1:
				switch num {
				case 2:
					state256 = 10 // MAGIC
				case 5:
					state256++
				default:
					state256 = 0
				}
			case 2:
				*ptr = tColor(num)
				state256 = 0
			case 10:
				*ptr = tColor(1<<24) | tColor(num<<16)
				state256++
			case 11:
				*ptr = *ptr | tColor(num<<8)
				state256++
			case 12:
				*ptr = *ptr | tColor(num)
				state256 = 0
			}
		}
	}

	if count == 0 {
		state.fg = -1
		state.bg = -1
		state.ul = -1
		state.attr = 0
	}
	return state
}
EOF

