			trimmed, _, _ := extractColor(string(*item.origText), nil, nil)
			return trimmed
		}
		return string(*item.origText)
	}
	return item.text.ToString()
}

type Result struct {
	item   *Item
	points [4]uint16
}

func asUint16(val int) uint16 {
	if val > math.MaxUint16 {
		return math.MaxUint16
	} else if val < 0 {
		return 0
	}
	return uint16(val)
}

func buildResult(item *Item, offsets []Offset, score int) Result {
	if len(offsets) > 1 {
		sort.Slice(offsets, func(i, j int) bool {
			a, b := offsets[i], offsets[j]
			return a[0] < b[0] || a[0] == b[0] && a[1] <= b[1]
		})
	}

	minBegin := math.MaxUint16
	minEnd := math.MaxUint16
	maxEnd := 0
	validOffsetFound := false
	for _, offset := range offsets {
		b, e := int(offset[0]), int(offset[1])
		if b < e {
			minBegin = min(b, minBegin)
			minEnd = min(e, minEnd)
			maxEnd = max(e, maxEnd)
			validOffsetFound = true
		}
	}

	result := Result{item: item}
	numChars := item.text.Length()
	for idx, criterion := range sortCriteria {
		val := uint16(math.MaxUint16)
		if validOffsetFound {
			switch criterion {
			case byScore:
				val = math.MaxUint16 - asUint16(score)
			case byChunk:
				b := minBegin
				e := maxEnd
				for ; b >= 1; b-- {
					if unicode.IsSpace(item.text.Get(b - 1)) {
						break
					}
				}
				for ; e < numChars; e++ {
					if unicode.IsSpace(item.text.Get(e)) {
						break
					}
				}
				val = asUint16(e - b)
			case byLength:
				val = asUint16(item.text.TrimLength())
			case byPathname:
				lastDelim := -1
				s := item.text.ToRunes()
				for i := len(s) - 1; i >= 0; i-- {
					if s[i] == '/' {
						lastDelim = i
						break
					}
				}
				if lastDelim <= minBegin {
					val = asUint16(minBegin - lastDelim)
				}
			case byBegin, byEnd:
				whitePrefixLen := 0
				for idx := 0; idx < numChars; idx++ {
					r := item.text.Get(idx)
					whitePrefixLen = idx
					if idx == minBegin || !unicode.IsSpace(r) {
						break
					}
				}
				if criterion == byBegin {
					val = asUint16(minBegin - whitePrefixLen)
				} else {
					val = asUint16(item.text.TrimSuffixLength() - maxEnd)
				}
			}
		}
		result.points[3-idx] = val
	}
	return result
}

func compareRanks(irank Result, jrank Result, tac bool) bool {
	for idx := 3; idx >= 0; idx-- {
		left := irank.points[idx]
		right := jrank.points[idx]
		if left < right {
			return true
		} else if left > right {
			return false
		}
	}
	return (irank.item.Index() <= jrank.item.Index()) != tac
}

func sortResults(results []Result, tac bool) {
	sort.SliceStable(results, func(i, j int) bool {
		return compareRanks(results[i], results[j], tac)
	})
}
