var executeRegexp *regexp.Regexp
var actionNameRegexp *regexp.Regexp

func init() {
	names := make([]string, len(argActionNames))
	for i, n := range argActionNames {
		names[i] = regexp.QuoteMeta(n)
	}
	executeRegexp = regexp.MustCompile(`(?si)[:+](` + strings.Join(names, "|") + `)`)
	actionNameRegexp = regexp.MustCompile(`(?i)^[a-z-]+`)
}

func maskActionContents(action string) string {
	masked := ""
Loop:
	for len(action) > 0 {
		loc := executeRegexp.FindStringIndex(action)
		if loc == nil {
			masked += action
			break
		}
		masked += action[:loc[1]]
		action = action[loc[1]:]
		if len(action) == 0 {
			break
		}
		cs := string(action[0])
		var ce string
		switch action[0] {
		case ':':
			masked += strings.Repeat(" ", len(action))
			break Loop
		case '(':
			ce = ")"
		case '{':
			ce = "}"
		case '[':
			ce = "]"
		case '<':
			ce = ">"
		case '~', '!', '@', '#', '$', '%', '^', '&', '*', ';', '/', '|':
			ce = cs
		default:
			continue
		}
		cs = regexp.QuoteMeta(cs)
		ce = regexp.QuoteMeta(ce)

		loc = regexp.MustCompile(fmt.Sprintf(`(?s)^%s.*?(%s[+,]|%s$)`, cs, ce, ce)).FindStringIndex(action)
		if loc == nil {
			masked += action
			break
		}
		lastChar := action[loc[1]-1]
		if lastChar == '+' || lastChar == ',' {
			loc[1]--
		}
		masked += strings.Repeat(" ", loc[1])
		action = action[loc[1]:]
	}
	masked = strings.ReplaceAll(masked, "::", string([]rune{escapedColon, ':'}))
	masked = strings.ReplaceAll(masked, ",:", string([]rune{escapedComma, ':'}))
	masked = strings.ReplaceAll(masked, "+:", string([]rune{escapedPlus, ':'}))
	return masked
}

func isExecuteAction(str string) string {
	matches := executeRegexp.FindAllStringSubmatch(":"+str, -1)
	if matches == nil || len(matches) != 1 || len(matches[0][0]) != len(matches[0][1])+1 {
		return ""
	}
	prefix := matches[0][1]
	return prefix
}

func argActionType(name string) string {
	switch name {
	case "execute-multi":
		return "execute-multi"
	}
	return name
}

type keymapT struct {
	order []Event
	m     map[Event][]*action
}

func newKeymap() *keymapT {
	return &keymapT{m: make(map[Event][]*action)}
}

func (k *keymapT) set(e Event, acts []*action) {
	e = e.Comparable()
	if _, ok := k.m[e]; !ok {
		k.order = append(k.order, e)
	}
	k.m[e] = acts
}

func (k *keymapT) get(e Event) ([]*action, bool) {
	a, ok := k.m[e.Comparable()]
	return a, ok
}

func parseActionList(masked string, original string, prevActions []*action, putAllowed bool, keyName string) ([]*action, error) {
	maskedSpecs := strings.Split(masked, "+")
	actions := []*action{}
	prevSpec := ""
	prevIdx := 0
	for specIndex, maskedSpec := range maskedSpecs {
		spec := original[prevIdx : prevIdx+len(maskedSpec)]
		prevIdx += len(maskedSpec) + 1
		spec = prevSpec + spec
		specLower := strings.ToLower(spec)
		if t, ok := simpleActions[specLower]; ok {
			actions = append(actions, &action{t: t})
			continue
		}
		switch specLower {
		case "put":
			if putAllowed {
				actions = append(actions, &action{t: "put"})
			} else {
				return nil, errors.New("unable to put non-printable character")
			}
			continue
		}
		t := isExecuteAction(specLower)
		if t == "" {
			if specIndex == 0 && specLower == "" {
				actions = append(prevActions, actions...)
			} else {
				return nil, errors.New("unknown action: " + spec)
			}
			continue
		}
		offset := len(t)
		var actionArg string
		if offset >= len(spec) {
			return nil, errors.New("unknown action: " + spec)
		}
		if spec[offset] == ':' {
			if specIndex == len(maskedSpecs)-1 {
				actionArg = spec[offset+1:]
			} else {
				prevSpec = spec + "+"
				continue
			}
		} else {
			actionArg = spec[offset+1 : len(spec)-1]
		}
