	return &keymapT{m: make(map[Event][]*action)}
}

func (k *keymapT) set(e Event, acts []*action) {
	e = e.Comparable()
	if _, ok := k.m[e]; !ok {
		k.order = append(k.order, e)
	}
	k.m[e] = acts
}

func (k *keymapT) get(e Event) ([]*action, bool) {
	a, ok := k.m[e.Comparable()]
	return a, ok
}

