func parseTmuxOptions(arg string, index int) (*tmuxOptions, error) {
	var err error
	opts := tmuxOptions{}
	tokens := splitRegexp(arg, ",")
	errorToReturn := errors.New("invalid tmux option: " + arg + " (expected: [center|top|bottom|left|right][,SIZE[%]][,SIZE[%][,border-native]])")
	if len(tokens) == 0 || len(tokens) > 4 {
		return nil, errorToReturn
	}
	for i, token := range tokens {
		if token == "border-native" {
			tokens = append(tokens[:i], tokens[i+1:]...)
			opts.border = true
			break
		}
	}
	opts.width = sizeSpec{50, true}
	opts.height = sizeSpec{50, true}
	opts.index = index
	switch tokens[0] {
	case "top", "up":
		opts.position = posUp
		opts.width = sizeSpec{100, true}
	case "bottom", "down":
		opts.position = posDown
		opts.width = sizeSpec{100, true}
	case "left":
		opts.position = posLeft
		opts.height = sizeSpec{100, true}
	case "right":
		opts.position = posRight
		opts.height = sizeSpec{100, true}
	case "center":
	default:
		tokens = append([]string{"center"}, tokens...)
	}
	if len(tokens) > 1 {
		if opts.width, err = parseSize(tokens[1], 100, "size"); err != nil {
			return nil, errorToReturn
		}
		if len(tokens) < 3 {
			switch tokens[0] {
			case "top", "up", "bottom", "down":
				opts.height = opts.width
				opts.width = sizeSpec{100, true}
			case "left", "right":
				opts.height = sizeSpec{100, true}
			default:
				opts.height = opts.width
			}
		}
	}
	if len(tokens) > 2 {
		if opts.height, err = parseSize(tokens[2], 100, "size"); err != nil {
			return nil, errorToReturn
		}
	}
	return &opts, nil
}

func splitRegexp(s string, sep string) []string {
	return strings.Split(s, sep)
}

func parseListenAddress(address string) (listenAddress, error) {
	if strings.HasSuffix(address, ".sock") {
		return listenAddress{"", 0, address}, nil
	}
	parts := strings.SplitN(address, ":", 3)
	if len(parts) == 1 {
		parts = []string{"localhost", parts[0]}
	}
	if len(parts) != 2 {
		return listenAddress{}, fmt.Errorf("invalid listen address: %s", address)
	}
	portStr := parts[len(parts)-1]
	port, err := strconv.Atoi(portStr)
	if err != nil || port < 0 || port > 65535 {
		return listenAddress{}, fmt.Errorf("invalid listen port: %s", portStr)
	}
	if len(parts[0]) == 0 {
		parts[0] = "localhost"
	}
	return listenAddress{parts[0], port, ""}, nil
}

func parseWalkerOpts(str string) (walkerOpts, error) {
	opts := walkerOpts{}
	for _, str := range strings.Split(strings.ToLower(str), ",") {
		switch str {
		case "file":
			opts.file = true
		case "dir":
			opts.dir = true
		case "hidden":
			opts.hidden = true
		case "follow":
			opts.follow = true
		case "":
		default:
			return opts, errors.New("invalid walker option: " + str)
		}
	}
	if !opts.file && !opts.dir {
		return opts, errors.New("at least one of 'file' or 'dir' should be specified")
	}
	return opts, nil
}

func parsePreviewWindowImpl(opts *previewOpts, input string) error {
	var err error
	tokenRegex := regexp.MustCompile(`[:,]*(<([1-9][0-9]*)\(([^)<]+)\)|[^,:]+)`)
	sizeRegex := regexp.MustCompile("^[0-9]+%?$")
	offsetRegex := regexp.MustCompile(`^(\+{(-?[0-9]+|n)}|\+[0-9]+)?([+-][0-9]+)*(-?/[1-9][0-9]*)?$`)
	headerRegex := regexp.MustCompile("^~(0|[1-9][0-9]*)$")
	tokens := tokenRegex.FindAllStringSubmatch(input, -1)
	var alternative string
	for _, match := range tokens {
		if len(match[2]) > 0 {
			if opts.threshold, err = atoi(match[2]); err != nil {
				return err
			}
			alternative = match[3]
			continue
		}
		token := match[1]
		switch token {
		case "":
		case "default":
			*opts = defaultPreviewOpts(opts.command)
		case "hidden":
			opts.hidden = true
		case "nohidden":
			opts.hidden = false
		case "wrap":
			opts.wrap = true
		case "nowrap":
			opts.wrap = false
		case "cycle":
			opts.cycle = true
		case "nocycle":
			opts.cycle = false
		case "up", "top":
			opts.position = posUp
		case "down", "bottom":
			opts.position = posDown
		case "left":
			opts.position = posLeft
		case "right":
			opts.position = posRight
		case "rounded", "border", "border-rounded":
			opts.border = BorderRounded
		case "sharp", "border-sharp":
			opts.border = BorderSharp
		case "border-bold":
			opts.border = BorderBold
		case "border-block":
			opts.border = BorderBlock
		case "border-thinblock":
			opts.border = BorderThinBlock
		case "border-double":
			opts.border = BorderDouble
		case "noborder", "border-none":
			opts.border = BorderNone
		case "border-horizontal":
			opts.border = BorderHorizontal
		case "border-vertical":
			opts.border = BorderVertical
		case "border-up", "border-top":
			opts.border = BorderTop
		case "border-down", "border-bottom":
			opts.border = BorderBottom
		case "border-left":
			opts.border = BorderLeft
		case "border-right":
			opts.border = BorderRight
		case "border-line":
			opts.border = BorderLine
		case "follow":
			opts.follow = true
		case "nofollow":
			opts.follow = false
		case "info":
			opts.info = true
		case "noinfo":
			opts.info = false
		default:
			if headerRegex.MatchString(token) {
				if opts.headerLines, err = atoi(token[1:]); err != nil {
					return err
				}
			} else if sizeRegex.MatchString(token) {
				if opts.size, err = parseSize(token, 99, "window size"); err != nil {
					return err
				}
			} else if offsetRegex.MatchString(token) {
				opts.scroll = token
			} else {
				return errors.New("invalid preview window option: " + token)
			}
		}
	}
	if len(alternative) > 0 {
		alternativeOpts := *opts
		opts.alternative = &alternativeOpts
		opts.alternative.hidden = false
		opts.alternative.alternative = nil
		err = parsePreviewWindowImpl(opts.alternative, alternative)
	}
	return err
}

func parseMarkerMultiLine(str string) (*[3]string, error) {
	if str == "" {
		return &[3]string{}, nil
	}
	gr := []string{}
	for _, r := range splitGraphemes(str) {
		gr = append(gr, r)
	}
	result := [3]string{}
	w := 0
	for _, g := range gr {
		w += stringWidth(g)
	}
	expected := 0
	if len(gr) == 3 {
		expected = 1
	} else if len(gr) == 6 {
		expected = 2
	}
	if expected == 0 || w != expected*3 && w != len(gr) {
		return nil, fmt.Errorf("invalid total marker width: %d (expected: 0, 3 or 6)", w)
	}
	if len(gr) == 3 {
		result = [3]string{gr[0], gr[1], gr[2]}
	} else {
		result = [3]string{gr[0] + gr[1], gr[2] + gr[3], gr[4] + gr[5]}
	}
	return &result, nil
}

func validateSign(sign string, signOptName string, maxWidth int) error {
