				opts.GapLine = &value
			} else if match, value := optString(arg, "--ellipsis="); match {
				value = firstLine(value)
				opts.Ellipsis = &value
			} else if match, value := optString(arg, "--wrap-sign="); match {
				opts.WrapSign = &value
			} else if match, value := optString(arg, "--freeze-left="); match {
				if opts.FreezeLeft, err = atoi(value); err != nil {
					return errors.New("number of fields required")
				}
				if opts.FreezeLeft < 0 {
					return errors.New("number of fields to freeze must be a non-negative integer")
				}
			} else if match, value := optString(arg, "--freeze-right="); match {
				if opts.FreezeRight, err = atoi(value); err != nil {
					return errors.New("number of fields required")
				}
				if opts.FreezeRight < 0 {
					return errors.New("number of fields to freeze must be a non-negative integer")
				}
