				opts.TtyDefault = value
			} else {
				return errors.New("unknown option: " + arg)
			}
		}
	}
	*index += len(allArgs)

	if opts.HeaderLines < 0 {
		return errors.New("header lines must be a non-negative integer")
	}
	if opts.HscrollOff < 0 {
		return errors.New("hscroll offset must be a non-negative integer")
	}
	if opts.ScrollOff < 0 {
		return errors.New("scroll offset must be a non-negative integer")
	}
	if opts.Tabstop < 1 {
		return errors.New("tab stop must be a positive integer")
	}
	if len(opts.JumpLabels) == 0 {
		return errors.New("empty jump labels")
	}
	if validateJumpLabels {
		for _, r := range opts.JumpLabels {
			if r > unicode.MaxASCII {
				return errors.New("non-ascii jump labels are not allowed")
			}
		}
	}
	return nil
}

func parseWalkerRoots(i *int, allArgs []string, opts *Options) error {
	roots := []string{}
	for *i+1 < len(allArgs) {
		next := allArgs[*i+1]
		if st, err := os.Stat(next); err == nil && st.IsDir() {
			roots = append(roots, next)
			*i++
		} else {
			break
		}
	}
	if len(roots) == 0 {
		return errors.New("no directory specified")
	}
	opts.WalkerRoot = roots
	return nil
}

func filterNonEmpty(input []string) []string {
	output := make([]string, 0, len(input))
	for _, str := range input {
		if len(str) > 0 {
			output = append(output, str)
		}
	}
	return output
}

func firstLine(s string) string {
	return strings.SplitN(s, "\n", 2)[0]
}

func strLines(str string) []string {
	return strings.Split(strings.TrimSuffix(str, "\n"), "\n")
}

func optString(arg string, prefixes ...string) (bool, string) {
	for _, prefix := range prefixes {
		if strings.HasPrefix(arg, prefix) {
			return true, arg[len(prefix):]
		}
	}
	return false, ""
}

const maxMulti = 0x7fffffff

func addExpect(opts *Options, str string) error {
	chords, err := parseKeyChordsImpl(str, "key names required")
	if err != nil {
		return err
	}
	for _, c := range chords {
		opts.Expect[c.event] = c.name
	}
	return nil
}

func parseToggleSort(keymap *keymapT, str string) error {
	chords, err := parseKeyChordsImpl(str, "key name required")
	if err != nil {
		return err
	}
	if len(chords) != 1 {
		return errors.New("multiple keys specified")
	}
	keymap.set(chords[0].event, []*action{{t: "toggle-sort"}})
	return nil
}

func applyPreset(opts *Options, preset string) error {
	opts.ListBorderShape = BorderUndefined
	opts.InputBorderShape = BorderUndefined
	opts.HeaderBorderShape = BorderUndefined
	opts.HeaderLinesShape = BorderUndefined
	opts.FooterBorderShape = BorderUndefined
	switch preset {
	case "default":
		opts.ListBorderShape = BorderUndefined
		opts.InputBorderShape = BorderUndefined
		opts.HeaderBorderShape = BorderUndefined
		opts.HeaderLinesShape = BorderUndefined
		opts.FooterBorderShape = BorderUndefined
		opts.Preview.border = BorderRounded
		opts.Pointer = nil
		opts.Marker = nil
		opts.Gutter = nil
		opts.Separator = nil
		opts.Scrollbar = nil
		opts.CursorLine = false
		opts.ThemeSpecs = append(opts.ThemeSpecs, "\x00preset-default")
	case "minimal":
		opts.ListBorderShape = BorderUndefined
		opts.InputBorderShape = BorderUndefined
		opts.HeaderBorderShape = BorderUndefined
		opts.HeaderLinesShape = BorderUndefined
		opts.FooterBorderShape = BorderUndefined
		opts.Preview.border = BorderLine
		opts.Preview.info = false
		opts.CursorLine = false
		opts.ThemeSpecs = append(opts.ThemeSpecs, "\x00preset-minimal")
		empty := ""
		opts.Separator = &empty
		opts.Scrollbar = &empty
		opts.Pointer = nil
		opts.Marker = nil
		opts.Gutter = nil
		space := " "
		opts.Gutter = &space
	default:
		tokens := strings.SplitN(preset, ":", 2)
		if tokens[0] != "full" {
			return errors.New("unsupported style preset: " + preset)
		}
		opts.ListBorderShape = BorderRounded
		opts.InputBorderShape = BorderRounded
		opts.HeaderBorderShape = BorderRounded
		opts.HeaderLinesShape = BorderRounded
		opts.FooterBorderShape = BorderRounded
		if len(tokens) > 1 {
			shape, err := parseBorder(tokens[1], false)
			if err != nil {
				return err
			}
			opts.ListBorderShape = shape
			opts.InputBorderShape = shape
			opts.HeaderBorderShape = shape
			opts.HeaderLinesShape = shape
			opts.FooterBorderShape = shape
		}
		opts.Preview.border = opts.ListBorderShape
		opts.Preview.info = true
		opts.CursorLine = true
		opts.ThemeSpecs = append(opts.ThemeSpecs, "\x00preset-full")
		opts.Separator = nil
		opts.Scrollbar = nil
		opts.Pointer = nil
		opts.Marker = nil
		opts.Gutter = nil
	}
	return nil
}
