func parseOptions(index *int, opts *Options, allArgs []string) error {
	var err error
	var historyMax int
	if opts.History == nil {
		historyMax = 1000
	} else {
		historyMax = opts.History.maxSize
	}
	setHistory := func(path string) error {
		h, e := NewHistory(path, historyMax)
		if e != nil {
			return e
		}
		opts.History = h
		return nil
	}
	setHistoryMax := func(max int) {
		historyMax = max
		if opts.History != nil {
			opts.History.maxSize = historyMax
		}
	}
	validateJumpLabels := false
	clearExitingOpts := func() {
		opts.Bash = false
		opts.Zsh = false
		opts.Fish = false
		opts.Help = false
		opts.Version = false
		opts.Man = false
	}
	for i := 0; i < len(allArgs); i++ {
		arg := allArgs[i]
		index := *index + i
		switch arg {
		case "--bash":
			clearExitingOpts()
			opts.Bash = true
		case "--zsh":
			clearExitingOpts()
			opts.Zsh = true
		case "--fish":
			clearExitingOpts()
			opts.Fish = true
		case "-h", "--help":
			clearExitingOpts()
			opts.Help = true
		case "--version":
			clearExitingOpts()
			opts.Version = true
		case "--man":
			clearExitingOpts()
			opts.Man = true
		case "--tmux":
			given, str := optionalNextString(allArgs, &i)
			if given {
				if opts.Tmux, err = parseTmuxOptions(str, index); err != nil {
					return err
				}
			} else {
				opts.Tmux = &tmuxOptions{sizeSpec{50, true}, sizeSpec{50, true}, posCenter, index, false}
			}
		case "--no-tmux":
			opts.Tmux = nil
		case "--tty-default":
			if opts.TtyDefault, err = nextString(allArgs, &i, "tty device name required"); err != nil {
				return err
			}
		case "--no-tty-default":
			opts.TtyDefault = ""
		case "-x", "--extended":
			opts.Extended = true
		case "-e", "--exact":
			opts.Fuzzy = false
		case "--extended-exact":
			opts.Extended = true
			opts.Fuzzy = false
		case "+x", "--no-extended":
			opts.Extended = false
		case "+e", "--no-exact":
			opts.Fuzzy = true
		case "-q", "--query":
			if opts.Query, err = nextString(allArgs, &i, "query string required"); err != nil {
				return err
			}
		case "-f", "--filter":
			filter, err := nextString(allArgs, &i, "query string required")
			if err != nil {
				return err
			}
			opts.Filter = &filter
		case "--literal":
			opts.Normalize = false
		case "--no-literal":
			opts.Normalize = true
		case "--algo":
			str, err := nextString(allArgs, &i, "algorithm required (v1|v2)")
			if err != nil {
				return err
			}
			if opts.FuzzyAlgo, err = parseAlgo(str); err != nil {
				return err
			}
		case "--scheme":
			str, err := nextString(allArgs, &i, "scoring scheme required (default|path|history)")
			if err != nil {
				return err
			}
			if opts.Scheme, _, err = parseScheme(str); err != nil {
				return err
			}
		case "--expect":
			str, err := nextString(allArgs, &i, "key names required")
			if err != nil {
				return err
			}
			if err = addExpect(opts, str); err != nil {
				return err
			}
		case "--no-expect":
			opts.Expect = make(map[Event]string)
		case "--enabled", "--no-phony":
			opts.Phony = false
		case "--disabled", "--phony":
			opts.Phony = true
		case "--no-input":
			opts.Inputless = true
		case "--tiebreak":
			str, err := nextString(allArgs, &i, "sort criterion required")
			if err != nil {
				return err
			}
			if opts.Criteria, err = parseTiebreak(str); err != nil {
				return err
			}
		case "--bind":
			str, err := nextString(allArgs, &i, "bind expression required")
			if err != nil {
				return err
			}
			if err := parseKeymap(opts.Keymap, str); err != nil {
				return err
			}
		case "--color":
			_, spec := optionalNextString(allArgs, &i)
			if spec == "" {
				opts.ThemeSpecs = append(opts.ThemeSpecs, "")
			} else {
				if err := validateColorSpec(spec); err != nil {
					return err
				}
				opts.ThemeSpecs = append(opts.ThemeSpecs, spec)
			}
		case "--toggle-sort":
			str, err := nextString(allArgs, &i, "key name required")
			if err != nil {
				return err
			}
			if err := parseToggleSort(opts.Keymap, str); err != nil {
				return err
			}
		case "-d", "--delimiter":
			str, err := nextString(allArgs, &i, "delimiter required")
			if err != nil {
				return err
			}
			opts.Delimiter = delimiterRegexp(str)
		case "-n", "--nth":
			str, err := nextString(allArgs, &i, "nth expression required")
			if err != nil {
				return err
			}
			if opts.Nth, err = splitNth(str); err != nil {
				return err
			}
		case "--with-nth":
			str, err := nextString(allArgs, &i, "nth expression required")
			if err != nil {
				return err
			}
			if opts.WithNth, err = parseNthTemplate(str); err != nil {
				return err
			}
		case "--accept-nth":
			str, err := nextString(allArgs, &i, "nth expression required")
			if err != nil {
				return err
			}
			if opts.AcceptNth, err = parseNthTemplate(str); err != nil {
				return err
			}
		case "-s", "--sort":
			if opts.Sort, err = optionalNumeric(allArgs, &i, 1); err != nil {
				return err
			}
		case "+s", "--no-sort":
			opts.Sort = 0
		case "--track":
			opts.Track = trackEnabled
		case "--no-track":
			opts.Track = trackDisabled
		case "--tac":
			opts.Tac = true
		case "--no-tac":
			opts.Tac = false
		case "--tail":
			str, err := nextString(allArgs, &i, "number of items to keep required")
			if err != nil {
				return err
			}
			if opts.Tail, err = atoi(str); err != nil {
				return errors.New("number of items to keep required")
			}
			if opts.Tail <= 0 {
				return errors.New("number of items to keep must be a positive integer")
			}
		case "--no-tail":
			opts.Tail = 0
		case "-i", "--ignore-case":
			opts.Case = CaseIgnore
		case "+i", "--no-ignore-case":
