package main

import (
	"unicode/utf8"
)

var ambiguousWide = false

func inTable(r rune, table [][2]rune) bool {
	lo, hi := 0, len(table)-1
	for lo <= hi {
		mid := (lo + hi) / 2
		if r < table[mid][0] {
			hi = mid - 1
		} else if r > table[mid][1] {
			lo = mid + 1
		} else {
			return true
		}
	}
	return false
}

func runeWidth(r rune) int {
	if r < 0x20 {
		return 0
	}
	if r < 0x7F {
		return 1
	}
	if r < 0xA0 {
		return 0
	}
	if inTable(r, zeroWidthTable) {
		return 0
	}
	if inTable(r, wideTable) {
		return 2
	}
	if ambiguousWide && inTable(r, ambiguousTable) {
		return 2
	}
	return 1
}

func isZeroWidth(r rune) bool {
	return r >= 0xA0 && inTable(r, zeroWidthTable) || r == 0x200D || (r >= 0xFE00 && r <= 0xFE0F)
}

// splitGraphemes splits a string into simplified grapheme clusters
func splitGraphemes(s string) []string {
	var out []string
	i := 0
	for i < len(s) {
		r, sz := utf8.DecodeRuneInString(s[i:])
		j := i + sz
		if r == '\r' && j < len(s) && s[j] == '\n' {
			j++
		} else {
			for j < len(s) {
				r2, sz2 := utf8.DecodeRuneInString(s[j:])
				if r2 == 0x200D {
					// ZWJ joins the next rune too
					j += sz2
					if j < len(s) {
						_, sz3 := utf8.DecodeRuneInString(s[j:])
						j += sz3
					}
					continue
				}
				if isZeroWidth(r2) && r2 >= 0x300 {
					j += sz2
					continue
				}
				break
			}
		}
		out = append(out, s[i:j])
		i = j
	}
	return out
}

func graphemeWidth(g string) int {
	w := 0
	first := true
	for _, r := range g {
		if first {
			w = runeWidth(r)
			first = false
		} else if r == 0xFE0F && w == 1 {
			w = 2
		}
	}
	return w
}

func stringWidth(s string) int {
	w := 0
	for _, g := range splitGraphemes(s) {
		w += graphemeWidth(g)
	}
	return w
}
EOF"}

