package main

import (
	"errors"
	"regexp"
	"strconv"
	"strings"
)

type tColor int32

const (
	colUndefined tColor = -2
	colDefault   tColor = -1
)

const (
	colBlack tColor = iota
	colRed
	colGreen
	colYellow
	colBlue
	colMagenta
	colCyan
	colWhite
)

func (c tColor) is24() bool {
	return c > 0 && (c&(1<<24)) > 0
}

type tAttr int32

const (
	tAttrBold          tAttr = 1 << 0
	tAttrDim           tAttr = 1 << 1
	tAttrItalic        tAttr = 1 << 2
	tAttrUnderline     tAttr = 1 << 3
	tAttrBlink         tAttr = 1 << 4
	tAttrBlink2        tAttr = 1 << 5
	tAttrReverse       tAttr = 1 << 6
	tAttrStrikeThrough tAttr = 1 << 7
	tAttrUndefined     tAttr = 1 << 9
	tAttrRegular       tAttr = 1 << 10
	tAttrStrip         tAttr = 1 << 11
	tAttrUnderlineDouble tAttr = 1 << 12
	tAttrUnderlineCurly  tAttr = 1 << 13
	tAttrUnderlineDotted tAttr = 1 << 14
	tAttrUnderlineDashed tAttr = 1 << 15
)

const tAttrNone tAttr = 0

func (a tAttr) Merge(b tAttr) tAttr {
	if b&tAttrRegular > 0 {
		return (b &^ tAttrRegular) | (a & tAttrStrip)
	}
	return (a &^ tAttrRegular) | b
}

type ColorAttr struct {
	Color tColor
	Attr  tAttr
