package main

import (
	"errors"
)

var errInvalidCommandLine = errors.New("invalid command line string")

func isShellSpace(r rune) bool {
	switch r {
	case ' ', '\t', '\r', '\n':
		return true
	}
	return false
}

// parseShellWords splits a string into words like a POSIX shell (without expansion)
func parseShellWords(line string) ([]string, error) {
	args := []string{}
	buf := ""
	var escaped, doubleQuoted, singleQuoted bool
	got := false
	runes := []rune(line)
loop:
	for i := 0; i < len(runes); i++ {
		r := runes[i]
		if escaped {
			if r == 't' {
				r = '\t'
			}
			if r == 'n' {
				r = '\n'
			}
			buf += string(r)
			escaped = false
			got = true
			continue
		}
		if r == '\\' {
			if singleQuoted {
				buf += string(r)
			} else {
				escaped = true
			}
			continue
		}
		if isShellSpace(r) {
			if singleQuoted || doubleQuoted {
				buf += string(r)
			} else if got {
				args = append(args, buf)
				buf = ""
				got = false
			}
			continue
		}
		switch r {
		case '"':
			if !singleQuoted {
				doubleQuoted = !doubleQuoted
				got = true
				continue
			}
		case '\'':
			if !doubleQuoted {
				singleQuoted = !singleQuoted
				got = true
				continue
			}
		case ';', '&', '|', '<', '>':
			if !(escaped || singleQuoted || doubleQuoted) {
				break loop
			}
		case '#':
			if !(singleQuoted || doubleQuoted) && !got && buf == "" {
				// comment till end of line
				for i < len(runes) && runes[i] != '\n' {
					i++
				}
				continue
			}
		}
		got = true
		buf += string(r)
	}
	if got {
		args = append(args, buf)
	}
	if escaped || singleQuoted || doubleQuoted {
		return nil, errInvalidCommandLine
	}
	return args, nil
}
EOF"}

