package main

import (
	_ "embed"
	"fmt"
	"os"
	"os/exec"
	"strings"
)

const version = "0.68.0"
const revision = "89eaa04a"

//go:embed assets/help.txt
var helpText string

//go:embed assets/bash.txt
var bashScript string

//go:embed assets/zsh.txt
var zshScript string

//go:embed assets/fish.txt
var fishScript string

//go:embed assets/fzf.1
var manPage string

const (
	exitOk        = 0
	exitNoMatch   = 1
	exitError     = 2
	exitBecome    = 126
	exitInterrupt = 130
)

func errorExit(msg string) {
	os.Stderr.WriteString(msg + "\n")
	os.Exit(exitError)
}

func parseAllOptions(args []string) (*Options, error) {
	opts := defaultOptions()
	index := 0
	if path := os.Getenv("FZF_DEFAULT_OPTS_FILE"); len(path) > 0 {
		bytes, err := os.ReadFile(path)
		if err != nil {
			return nil, fmt.Errorf("$FZF_DEFAULT_OPTS_FILE: %s", err.Error())
		}
		words, err := parseShellWords(string(bytes))
		if err != nil {
			return nil, fmt.Errorf("$FZF_DEFAULT_OPTS_FILE: %s", err.Error())
		}
		if len(words) > 0 {
			if err := parseOptions(&index, opts, words); err != nil {
				return nil, fmt.Errorf("$FZF_DEFAULT_OPTS_FILE: %s", err.Error())
			}
		}
	}
	words, err := parseShellWords(os.Getenv("FZF_DEFAULT_OPTS"))
	if err != nil {
		return nil, fmt.Errorf("$FZF_DEFAULT_OPTS: %s", err.Error())
	}
	if len(words) > 0 {
		if err := parseOptions(&index, opts, words); err != nil {
			return nil, fmt.Errorf("$FZF_DEFAULT_OPTS: %s", err.Error())
		}
	}
	if err := parseOptions(&index, opts, args); err != nil {
		return nil, err
	}
	if err := postProcessOptions(opts); err != nil {
		return nil, err
	}
	return opts, nil
}

func postProcessOptions(opts *Options) error {
	if opts.Height.auto {
		for idx, s := range []sizeSpec{opts.Margin[0], opts.Margin[2]} {
			_ = idx
			if s.percent {
				return fmt.Errorf("adaptive height is not compatible with top/bottom percent margin")
			}
		}
		for _, s := range []sizeSpec{opts.Padding[0], opts.Padding[2]} {
			if s.percent {
				return fmt.Errorf("adaptive height is not compatible with top/bottom percent padding")
			}
		}
	}
	if opts.Pointer != nil {
		if err := validateSign(*opts.Pointer, "pointer", 2); err != nil {
			return err
		}
	}
	if opts.Marker != nil {
		if err := validateSign(*opts.Marker, "marker", 2); err != nil {
			return err
		}
	}
	if opts.Scrollbar != nil {
		runes := splitGraphemes(*opts.Scrollbar)
		if len(runes) > 2 {
			return fmt.Errorf("--scrollbar should be given one or two characters")
		}
		for _, r := range runes {
			if stringWidth(r) != 1 {
				return fmt.Errorf("scrollbar display width should be 1")
			}
		}
	}
	// scheme
	scheme := opts.Scheme
	if scheme == "" {
		scheme = "default"
	}
	if opts.Criteria == nil {
		_, crit, _ := parseScheme(scheme)
		opts.Criteria = crit
	}
	return nil
}

func main() {
	opts, err := parseAllOptions(os.Args[1:])
	if err != nil {
		errorExit(err.Error())
	}
	if opts.Bash {
		fmt.Print(bashScript)
		os.Exit(exitOk)
	}
	if opts.Zsh {
		fmt.Print(zshScript)
		os.Exit(exitOk)
	}
	if opts.Fish {
		fmt.Print(fishScript)
		os.Exit(exitOk)
	}
	if opts.Help {
		fmt.Print(helpText)
		os.Exit(exitOk)
	}
	if opts.Version {
		fmt.Printf("%s (%s)\n", version, revision)
		os.Exit(exitOk)
	}
	if opts.Man {
		file, err := os.CreateTemp("", "fzf-temp-*")
		if err != nil {
			errorExit(err.Error())
		}
		defer os.Remove(file.Name())
		file.WriteString(manPage)
		file.Close()
		cmd := exec.Command("man", file.Name())
		cmd.Stdin = os.Stdin
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		if err := cmd.Run(); err != nil {
			os.Remove(file.Name())
			if ee, ok := err.(*exec.ExitError); ok {
				os.Exit(ee.ExitCode())
			}
			errorExit(err.Error())
		}
		os.Remove(file.Name())
		os.Exit(exitOk)
	}
	os.Exit(run(opts))
}

func outputSeparator(opts *Options) string {
	if opts.PrintZero {
		return "\x00"
	}
	return "\n"
}

var _ = strings.TrimSpace
EOF"}

