	scheme := opts.Scheme
	if scheme == "" {
		scheme = "default"
	}
	if opts.Criteria == nil {
		_, crit, _ := parseScheme(scheme)
		opts.Criteria = crit
	}
	return nil
}

func main() {
	opts, err := parseAllOptions(os.Args[1:])
	if err != nil {
