	}
	if opts.Version {
		fmt.Printf("%s (%s)\n", version, revision)
		os.Exit(exitOk)
	}
	if opts.Man {
		file, err := os.CreateTemp("", "fzf-temp-*")
		if err != nil {
			errorExit(err.Error())
		}
		defer os.Remove(file.Name())
		file.WriteString(manPage)
		file.Close()
		cmd := exec.Command("man", file.Name())
		cmd.Stdin = os.Stdin
		cmd.Stdout = os.Stdout
		cmd.Stderr = os.Stderr
		if err := cmd.Run(); err != nil {
			os.Remove(file.Name())
			if ee, ok := err.(*exec.ExitError); ok {
				os.Exit(ee.ExitCode())
			}
			errorExit(err.Error())
		}
		os.Remove(file.Name())
		os.Exit(exitOk)
	}
	os.Exit(run(opts))
}

func outputSeparator(opts *Options) string {
	if opts.PrintZero {
		return "\x00"
	}
	return "\n"
}

