	}
	return items, builder
}

func run(opts *Options) int {
	scheme := opts.Scheme
	if scheme == "" {
		scheme = "default"
		if isTerminal(os.Stdin) && opts.Filter == nil {
			// handled by terminal
		}
		if isTerminal(os.Stdin) && os.Getenv("FZF_DEFAULT_COMMAND") == "" && !hasStartReload(opts) {
			scheme = "path"
			if opts.Criteria == nil || sameCriteria(opts.Criteria, []criterion{byScore, byLength}) && !opts.criteriaGiven() {
				opts.Criteria = []criterion{byScore, byPathname, byLength}
			}
		}
	}
	algoInit(scheme)
	sortCriteria = opts.Criteria
	ambiguousWide = opts.Ambidouble

	if opts.Filter != nil {
		return runFilter(opts)
	}
	return runInteractive(opts)
}

func sameCriteria(a, b []criterion) bool {
	if len(a) != len(b) {
		return false
	}
	for i := range a {
		if a[i] != b[i] {
			return false
		}
	}
	return true
}

func (opts *Options) criteriaGiven() bool {
	return opts.tiebreakGiven
}

func hasStartReload(opts *Options) bool {
	if acts, ok := opts.Keymap.get(Start.AsEvent()); ok {
		for _, a := range acts {
			if strings.HasPrefix(a.t, "reload") || strings.HasPrefix(a.t, "transform") || strings.HasPrefix(a.t, "bg-transform") {
				return true
			}
		}
	}
	return false
}

func runFilter(opts *Options) int {
	items, _ := readAllItems(opts)
	out := bufio.NewWriterSize(os.Stdout, 64*1024)
	defer out.Flush()
	sep := outputSeparator(opts)
	if opts.PrintQuery {
		out.WriteString(*opts.Filter + sep)
	}
	pattern := buildPatternFor(opts, []rune(*opts.Filter), 0)
	results := matchItems(pattern, items, opts.Sort > 0, opts.Tac)
	var buf bytes.Buffer
	for _, r := range results {
		buf.Reset()
		out.WriteString(opts.acceptNthOutput(r.item) + sep)
	}
	if len(results) > 0 {
		return exitOk
	}
	return exitNoMatch
}
