				for k < len(data) && (data[k] >= '0' && data[k] <= '9' || data[k] == ';') {
					k++
				}
				if k < len(data) && data[k] == 'R' {
					var row, col int
					fmt.Sscanf(string(data[j:k]), "%d;%d", &row, &col)
					rest := append([]byte{}, data[:i]...)
					rest = append(rest, data[k+1:]...)
					s.pending = append(s.pending, rest...)
					return row - 1, col - 1, true
				}
			}
		case <-deadline:
			s.pending = append(s.pending, data...)
			return 0, 0, false
		}
	}
}

func (s *Screen) init(fullscreen bool, heightFn func(termH int) int) error {
	orig, err := makeRaw(s.in.Fd())
	if err != nil {
		return err
	}
	s.orig = orig
	s.fullscreen = fullscreen
	s.updateTermSize()
	s.startReader()
	if fullscreen {
		s.write("\x1b[?1049h")
		s.top = 0
		s.width = s.termW
		s.height = s.termH
		s.write("\x1b[?25l\x1b[H\x1b[2J")
	} else {
		s.height = heightFn(s.termH)
		s.width = s.termW
		row, col, ok := s.queryCursor()
		if !ok {
			row, col = 0, 0
		}
		s.startX = col
		if col > 0 {
			// move to the next line
			s.write("\r\n")
			row++
		}
		// make space
		if row+s.height > s.termH {
			scroll := row + s.height - s.termH
			s.write("\x1b[" + strconv.Itoa(s.termH) + ";1H")
			for i := 0; i < scroll; i++ {
				s.write("\n")
			}
			row -= scroll
			if row < 0 {
				row = 0
			}
		}
		s.top = row
		s.write("\x1b[?25l")
	}
	if s.mouse {
		s.write("\x1b[?1000h\x1b[?1002h\x1b[?1006h")
	}
	s.write("\x1b[?2004h")
	s.flushOut()
	s.allocBuffers()
	return nil
}

func (s *Screen) allocBuffers() {
	s.cells = make([][]cell, s.height)
	s.prev = make([][]cell, s.height)
	for i := 0; i < s.height; i++ {
		s.cells[i] = make([]cell, s.width)
		s.prev[i] = make([]cell, s.width)
		for j := 0; j < s.width; j++ {
			s.cells[i][j] = blankCell
			s.prev[i][j] = cell{"", -1, colDefault, colDefault, 0}
		}
	}
}

func (s *Screen) resize(heightFn func(termH int) int) {
	s.updateTermSize()
	s.width = s.termW
	if s.fullscreen {
		s.height = s.termH
		s.write("\x1b[H\x1b[2J")
	} else {
		newH := heightFn(s.termH)
		// clear old region
		s.write("\x1b[" + strconv.Itoa(s.top+1) + ";1H\x1b[J")
		if s.top+newH > s.termH {
			scroll := s.top + newH - s.termH
			s.write("\x1b[" + strconv.Itoa(s.termH) + ";1H")
			for i := 0; i < scroll; i++ {
				s.write("\n")
			}
			s.top -= scroll
			if s.top < 0 {
				s.top = 0
			}
		}
		s.height = newH
	}
	s.allocBuffers()
}

func (s *Screen) clearCells() {
	for i := 0; i < s.height; i++ {
		row := s.cells[i]
		for j := range row {
			row[j] = blankCell
		}
	}
}

func (s *Screen) invalidate() {
	for i := 0; i < s.height; i++ {
		for j := 0; j < s.width; j++ {
			s.prev[i][j] = cell{"", -1, colDefault, colDefault, 0}
		}
	}
}

func colorSGR(c tColor, fg bool) string {
	base := 30
	if !fg {
		base = 40
	}
	if c < 0 {
		return strconv.Itoa(base + 9)
	}
	if c.is24() {
		r := (int(c) >> 16) & 0xff
		g := (int(c) >> 8) & 0xff
		b := int(c) & 0xff
		return fmt.Sprintf("%d;2;%d;%d;%d", base+8, r, g, b)
	}
	if c < 8 {
		return strconv.Itoa(base + int(c))
	}
	if c < 16 {
		return strconv.Itoa(base + 60 + int(c) - 8)
	}
	return fmt.Sprintf("%d;5;%d", base+8, int(c))
}

func sgrFor(c cell) string {
	seq := "\x1b[0"
	if c.attr&tAttrBold > 0 {
		seq += ";1"
	}
	if c.attr&tAttrDim > 0 {
		seq += ";2"
	}
	if c.attr&tAttrItalic > 0 {
		seq += ";3"
	}
	if c.attr&tAttrUnderline > 0 {
		seq += ";4"
	}
	if c.attr&tAttrUnderlineDouble > 0 {
		seq += ";4:2"
	}
	if c.attr&tAttrUnderlineCurly > 0 {
		seq += ";4:3"
	}
	if c.attr&tAttrUnderlineDotted > 0 {
		seq += ";4:4"
	}
	if c.attr&tAttrUnderlineDashed > 0 {
		seq += ";4:5"
	}
	if c.attr&tAttrBlink > 0 {
		seq += ";5"
	}
	if c.attr&tAttrReverse > 0 {
		seq += ";7"
	}
	if c.attr&tAttrStrikeThrough > 0 {
		seq += ";9"
	}
	if c.fg != colDefault && c.fg >= 0 {
		seq += ";" + colorSGR(c.fg, true)
	}
	if c.bg != colDefault && c.bg >= 0 {
		seq += ";" + colorSGR(c.bg, false)
	}
	return seq + "m"
}

func sameStyle(a, b cell) bool {
	return a.fg == b.fg && a.bg == b.bg && a.attr == b.attr
}

func (s *Screen) flush() {
	curStyle := cell{"", -1, -3, -3, -1}
	cy, cx := -1, -1
	for y := 0; y < s.height; y++ {
		row := s.cells[y]
		prow := s.prev[y]
		for x := 0; x < s.width; x++ {
			c := row[x]
			if c.width == 0 {
				continue
			}
			if c == prow[x] && !(c.width == 2 && x+1 < s.width && prow[x+1] != row[x+1]) {
				continue
			}
			if cy != y || cx != x {
				s.write("\x1b[" + strconv.Itoa(s.top+y+1) + ";" + strconv.Itoa(x+1) + "H")
			}
			if !sameStyle(c, curStyle) {
				s.write(sgrFor(c))
				curStyle = c
			}
			if c.width == 2 && x+1 >= s.width {
				s.write(" ")
				cx = x + 1
			} else {
				s.write(c.str)
				cx = x + c.width
			}
			cy = y
		}
		copy(prow, row)
	}
	s.write("\x1b[0m")
	if s.showCursor {
		s.write("\x1b[" + strconv.Itoa(s.top+s.cursorY+1) + ";" + strconv.Itoa(s.cursorX+1) + "H\x1b[?25h")
	} else {
		s.write("\x1b[?25l")
	}
	s.flushOut()
}

func (s *Screen) setCell(y, x int, str string, w int, fg, bg tColor, attr tAttr) {
	if y < 0 || y >= s.height || x < 0 || x >= s.width {
		return
	}
	row := s.cells[y]
	// clean up wide char overlaps
	if row[x].width == 0 && x > 0 && row[x-1].width == 2 {
		row[x-1] = cell{" ", 1, row[x-1].fg, row[x-1].bg, row[x-1].attr}
	}
	if row[x].width == 2 && x+1 < s.width {
		row[x+1] = cell{" ", 1, row[x].fg, row[x].bg, row[x].attr}
	}
	row[x] = cell{str, w, fg, bg, attr}
	if w == 2 {
		if x+1 < s.width {
			if row[x+1].width == 2 && x+2 < s.width {
				row[x+2] = cell{" ", 1, row[x+1].fg, row[x+1].bg, row[x+1].attr}
			}
			row[x+1] = cell{"", 0, fg, bg, attr}
		} else {
			row[x] = cell{" ", 1, fg, bg, attr}
		}
	}
}

func (s *Screen) close(clear bool) {
	if s.mouse {
		s.write("\x1b[?1000l\x1b[?1002l\x1b[?1006l")
	}
	s.write("\x1b[?2004l")
	s.write("\x1b[0m")
	if s.fullscreen {
		if clear {
			s.write("\x1b[?1049l")
		}
	} else {
		if clear {
			s.write("\x1b[" + strconv.Itoa(s.top+1) + ";1H\x1b[J")
			if s.startX > 0 {
				// move back to the original position
				s.write("\x1b[A\x1b[" + strconv.Itoa(s.startX+1) + "G")
			}
		} else {
			s.write("\x1b[" + strconv.Itoa(s.top+s.height) + ";1H\r\n")
		}
	}
	s.write("\x1b[?25h")
	s.flushOut()
	if s.orig != nil {
		setTermios(s.in.Fd(), s.orig)
	}
}

// pause/resume for execute
func (s *Screen) pause(clear bool) {
	if s.mouse {
		s.write("\x1b[?1000l\x1b[?1002l\x1b[?1006l")
	}
	s.write("\x1b[?2004l\x1b[0m")
	if clear {
		if s.fullscreen {
			s.write("\x1b[?1049l")
		} else {
			s.write("\x1b[" + strconv.Itoa(s.top+1) + ";1H\x1b[J")
		}
	}
	s.write("\x1b[?25h")
	s.flushOut()
	if s.orig != nil {
		setTermios(s.in.Fd(), s.orig)
	}
}

func (s *Screen) resume(clear bool, heightFn func(int) int) {
	makeRaw(s.in.Fd())
	if clear {
		if s.fullscreen {
			s.write("\x1b[?1049h\x1b[H\x1b[2J")
		} else {
			row, _, ok := s.queryCursor()
			if ok {
				s.top = row
			}
			s.height = heightFn(s.termH)
			if s.top+s.height > s.termH {
				scroll := s.top + s.height - s.termH
				s.write("\x1b[" + strconv.Itoa(s.termH) + ";1H")
				for i := 0; i < scroll; i++ {
					s.write("\n")
				}
				s.top -= scroll
				if s.top < 0 {
					s.top = 0
				}
			}
		}
	}
	if s.mouse {
		s.write("\x1b[?1000h\x1b[?1002h\x1b[?1006h")
	}
	s.write("\x1b[?2004h")
	s.flushOut()
	s.allocBuffers()
}

