		Up:       {ShiftUp, AltUp, AltShiftUp, CtrlUp, CtrlShiftUp, CtrlAltUp, CtrlAltShiftUp},
		Down:     {ShiftDown, AltDown, AltShiftDown, CtrlDown, CtrlShiftDown, CtrlAltDown, CtrlAltShiftDown},
		Left:     {ShiftLeft, AltLeft, AltShiftLeft, CtrlLeft, CtrlShiftLeft, CtrlAltLeft, CtrlAltShiftLeft},
		Right:    {ShiftRight, AltRight, AltShiftRight, CtrlRight, CtrlShiftRight, CtrlAltRight, CtrlAltShiftRight},
		Home:     {ShiftHome, AltHome, AltShiftHome, CtrlHome, CtrlShiftHome, CtrlAltHome, CtrlAltShiftHome},
		End:      {ShiftEnd, AltEnd, AltShiftEnd, CtrlEnd, CtrlShiftEnd, CtrlAltEnd, CtrlAltShiftEnd},
		Delete:   {ShiftDelete, AltDelete, AltShiftDelete, CtrlDelete, CtrlShiftDelete, CtrlAltDelete, CtrlAltShiftDelete},
		PageUp:   {ShiftPageUp, AltPageUp, AltShiftPageUp, CtrlPageUp, CtrlShiftPageUp, CtrlAltPageUp, CtrlAltShiftPageUp},
		PageDown: {ShiftPageDown, AltPageDown, AltShiftPageDown, CtrlPageDown, CtrlShiftPageDown, CtrlAltPageDown, CtrlAltShiftPageDown},
	}
	st, ok := table[base]
	if !ok {
		return base
	}
	switch mod {
	case 2:
		return st.shift
	case 3:
		return st.alt
	case 4:
		return st.altShift
	case 5:
		return st.ctrl
	case 6:
		return st.ctrlShift
	case 7:
		return st.ctrlAlt
	case 8:
		return st.ctrlAltShift
	}
	return base
}

func parseEscape(data []byte) (Event, int, bool) {
	if len(data) == 1 {
		return Esc.AsEvent(), 1, true
	}
	c := data[1]
	if c == '[' || c == 'O' {
		if len(data) == 2 {
			if c == '[' {
				return AltKeyEvent('['), 2, true
			}
			return AltKeyEvent('O'), 2, true
		}
		if c == 'O' {
			switch data[2] {
			case 'A':
				return Up.AsEvent(), 3, false
			case 'B':
				return Down.AsEvent(), 3, false
			case 'C':
				return Right.AsEvent(), 3, false
			case 'D':
				return Left.AsEvent(), 3, false
			case 'H':
				return Home.AsEvent(), 3, false
			case 'F':
				return End.AsEvent(), 3, false
			case 'P':
				return F1.AsEvent(), 3, false
			case 'Q':
				return F2.AsEvent(), 3, false
			case 'R':
				return F3.AsEvent(), 3, false
			case 'S':
				return F4.AsEvent(), 3, false
			}
			return AltKeyEvent('O'), 2, false
		}
		// CSI
		if data[2] == '<' {
			// SGR mouse
			end := -1
			for i := 3; i < len(data); i++ {
				if data[i] == 'M' || data[i] == 'm' {
					end = i
					break
				}
				if !(data[i] >= '0' && data[i] <= '9' || data[i] == ';') {
					return Event{Type: Invalid}, i, false
				}
			}
			if end < 0 {
				return Event{Type: Invalid}, 0, true
			}
			parts := strings.Split(string(data[3:end]), ";")
			if len(parts) != 3 {
				return Event{Type: Invalid}, end + 1, false
			}
			b, _ := strconv.Atoi(parts[0])
			x, _ := strconv.Atoi(parts[1])
			y, _ := strconv.Atoi(parts[2])
			down := data[end] == 'M'
			return mouseEvent(b, x-1, y-1, down), end + 1, false
		}
		// find final byte
		end := -1
		for i := 2; i < len(data); i++ {
			if data[i] >= 0x40 && data[i] <= 0x7e {
				end = i
				break
			}
		}
		if end < 0 {
			return Event{Type: Invalid}, 0, true
		}
		params := string(data[2:end])
		final := data[end]
		n := end + 1
		mod := 1
		var nums []int
		for _, p := range strings.Split(params, ";") {
			v, _ := strconv.Atoi(p)
			nums = append(nums, v)
		}
		if len(nums) >= 2 {
			mod = nums[1]
		}
		switch final {
		case 'A':
			return modifiedKey(mod, Up).AsEvent(), n, false
		case 'B':
			return modifiedKey(mod, Down).AsEvent(), n, false
		case 'C':
			return modifiedKey(mod, Right).AsEvent(), n, false
		case 'D':
			return modifiedKey(mod, Left).AsEvent(), n, false
		case 'H':
			return modifiedKey(mod, Home).AsEvent(), n, false
		case 'F':
			return modifiedKey(mod, End).AsEvent(), n, false
		case 'Z':
			return ShiftTab.AsEvent(), n, false
		case 'P':
			return F1.AsEvent(), n, false
		case 'Q':
			return F2.AsEvent(), n, false
		case 'R':
			return F3.AsEvent(), n, false
		case 'S':
			return F4.AsEvent(), n, false
		case '~':
			if len(nums) == 0 {
				return Event{Type: Invalid}, n, false
			}
			switch nums[0] {
			case 1, 7:
				return modifiedKey(mod, Home).AsEvent(), n, false
			case 4, 8:
				return modifiedKey(mod, End).AsEvent(), n, false
			case 2:
				return Insert.AsEvent(), n, false
			case 3:
				return modifiedKey(mod, Delete).AsEvent(), n, false
			case 5:
				return modifiedKey(mod, PageUp).AsEvent(), n, false
			case 6:
				return modifiedKey(mod, PageDown).AsEvent(), n, false
			case 11:
				return F1.AsEvent(), n, false
			case 12:
				return F2.AsEvent(), n, false
			case 13:
				return F3.AsEvent(), n, false
			case 14:
				return F4.AsEvent(), n, false
			case 15:
				return F5.AsEvent(), n, false
			case 17:
				return F6.AsEvent(), n, false
			case 18:
				return F7.AsEvent(), n, false
			case 19:
				return F8.AsEvent(), n, false
			case 20:
				return F9.AsEvent(), n, false
			case 21:
				return F10.AsEvent(), n, false
			case 23:
				return F11.AsEvent(), n, false
			case 24:
				return F12.AsEvent(), n, false
			case 200:
				return BracketedPasteBegin.AsEvent(), n, false
			case 201:
				return BracketedPasteEnd.AsEvent(), n, false
			}
		}
		return Event{Type: Invalid}, n, false
	}
	// Alt + key
	switch c {
	case 127:
		return AltBackspace.AsEvent(), 2, false
	case 8:
		return CtrlAltBackspace.AsEvent(), 2, false
	case 13:
		return AltEnter.AsEvent(), 2, false
	case ' ':
		return AltSpace.AsEvent(), 2, false
	case 0x1b:
		// ESC ESC
		return Esc.AsEvent(), 1, false
	}
	if c >= 1 && c <= 26 {
		return CtrlAltKeyEvent(rune('a' + c - 1)), 2, false
	}
	if c < 0x80 {
		return AltKeyEvent(rune(c)), 2, false
	}
	rest := data[1:]
	if !utf8.FullRune(rest) {
		return Event{Type: Invalid}, 0, true
	}
	r, sz := utf8.DecodeRune(rest)
	return AltKeyEvent(r), 1 + sz, false
}

func mouseEvent(b int, x int, y int, down bool) Event {
	mod := b&4 != 0 || b&8 != 0 || b&16 != 0
	base := b &^ (4 | 8 | 16)
	me := &MouseEvent{Y: y, X: x, Mod: mod, Down: down}
	switch {
	case base == 64:
		me.S = 1
		if mod {
			return Event{SScrollUp, 0, me}
		}
		return Event{ScrollUp, 0, me}
	case base == 65:
		me.S = -1
		if mod {
			return Event{SScrollDown, 0, me}
		}
		return Event{ScrollDown, 0, me}
	case base == 0:
		me.Left = true
		return Event{Mouse, 0, me}
	case base == 2:
		me.Left = false
		return Event{Mouse, 0, me}
	case base == 32 || base == 34 || base == 35:
		// drag/motion
		me.Left = base == 32
		return Event{Mouse, 0, me}
	}
	return Event{Type: Invalid}
}
EOF
echo ok

