// itemStore holds items read so far
type itemStore struct {
	mu      sync.Mutex
	items   []*Item
	header  []string
	done    bool
	rev     int
	notify  chan struct{}
	builder *itemBuilder
}

func newItemStore(opts *Options) *itemStore {
	return &itemStore{notify: make(chan struct{}, 1), builder: newItemBuilder(opts)}
}

func (s *itemStore) signal() {
	select {
	case s.notify <- struct{}{}:
	default:
	}
}

func (s *itemStore) snapshot() ([]*Item, []string, bool, int) {
	s.mu.Lock()
	defer s.mu.Unlock()
	return s.items, s.header, s.done, s.rev
}

func (s *itemStore) reset() {
	s.mu.Lock()
	s.items = nil
	s.header = nil
	s.done = false
	s.rev++
	s.builder = newItemBuilder(s.builder.opts)
	s.mu.Unlock()
}

// parallel matching
func parallelMatch(pattern *Pattern, items []*Item) []Result {
	n := len(items)
	if n < 10000 {
		results := []Result{}
		for _, item := range items {
			if res, _, _ := pattern.MatchItem(item, true); res != nil {
				results = append(results, *res)
			}
		}
		return results
	}
	workers := runtime.NumCPU()
	if workers > 8 {
		workers = 8
	}
	chunk := (n + workers - 1) / workers
	parts := make([][]Result, workers)
	var wg sync.WaitGroup
	for w := 0; w < workers; w++ {
		start := w * chunk
		end := min(n, start+chunk)
		if start >= end {
			continue
		}
		wg.Add(1)
		go func(w, start, end int) {
			defer wg.Done()
			local := []Result{}
			for _, item := range items[start:end] {
				if res, _, _ := pattern.MatchItem(item, true); res != nil {
					local = append(local, *res)
				}
			}
			parts[w] = local
		}(w, start, end)
	}
	wg.Wait()
	total := 0
	for _, p := range parts {
		total += len(p)
	}
	results := make([]Result, 0, total)
	for _, p := range parts {
		results = append(results, p...)
	}
	return results
}
