package main

import (
	"os"
	"os/signal"
	"strings"
	"syscall"
	"time"
	"unicode"
)

type selectedItem struct {
	order int
	item  *Item
}

type Terminal struct {
	opts         *Options
	screen       *Screen
	store        *itemStore
	theme        *ColorTheme
	input        []rune
	cx           int
	yanked       []rune
	prompt       string
