}

type rect struct {
	top, left, width, height int
}

func newTerminal(opts *Options, store *itemStore) *Terminal {
	t := &Terminal{opts: opts, store: store}
	t.input = []rune(opts.Query)
	t.cx = len(t.input)
	t.prompt = opts.Prompt
	t.layout = opts.Layout
	t.infoStyle = opts.InfoStyle
	t.infoPrefix = opts.InfoPrefix
	t.selected = make(map[*Item]selectedItem)
	t.multi = opts.Multi
	t.sort = opts.Sort > 0
	t.keymap = defaultKeymap(opts)
	t.expect = opts.Expect
	t.header0 = opts.Header
	t.footer = opts.Footer
	t.nth = opts.Nth
	t.disabled = opts.Phony
	t.inputHidden = opts.Inputless
	t.hscroll = opts.Hscroll
	t.wrap = opts.Wrap
	t.borderLabel = opts.BorderLabel.label
	t.previewLabel = opts.PreviewLabel.label
	t.listLabel = opts.ListLabel.label
	t.inputLabel = opts.InputLabel.label
	t.headerLabel = opts.HeaderLabel.label
	t.footerLabel = opts.FooterLabel.label
	t.ghost = opts.Ghost
	t.previewOpts = opts.Preview
	t.history = opts.History
	t.track = opts.Track
	t.cursorLine = opts.CursorLine
	t.scrollOff = opts.ScrollOff
	t.gap = opts.Gap
	t.unbound = make(map[Event]bool)
	t.infoCommand = opts.InfoCommand
	t.reading = true
	if opts.Unicode {
		t.spinner = []string{"⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"}
	} else {
		t.spinner = []string{"-", "\\", "|", "/", "-", "\\", "|", "/"}
	}
	// signs
	if opts.Pointer != nil {
		t.pointer = *opts.Pointer
	} else if opts.Unicode {
		t.pointer = "▌"
	} else {
		t.pointer = ">"
	}
	if opts.Marker != nil {
		t.marker = *opts.Marker
	} else if opts.Unicode {
		t.marker = "┃"
	} else {
		t.marker = ">"
	}
	if opts.Gutter != nil {
		t.gutter = *opts.Gutter
	} else if opts.Unicode {
		t.gutter = "▌"
	} else {
		t.gutter = " "
	}
	t.pointerLen = stringWidth(t.pointer)
	t.markerLen = stringWidth(t.marker)
	t.pointerEmpty = strings.Repeat(" ", t.pointerLen)
	t.markerEmpty = strings.Repeat(" ", t.markerLen)
	if opts.Separator != nil {
		t.separator = *opts.Separator
	} else if opts.Unicode {
		t.separator = "─"
	} else {
		t.separator = "-"
	}
	if opts.Scrollbar != nil {
		sb := splitGraphemes(*opts.Scrollbar)
		if len(sb) > 0 {
			t.scrollbar = sb[0]
			t.previewScrollbar = sb[0]
			if len(sb) > 1 {
				t.previewScrollbar = sb[1]
			}
		}
	} else if opts.Unicode {
		t.scrollbar = "│"
		t.previewScrollbar = "│"
	} else {
		t.scrollbar = "|"
		t.previewScrollbar = "|"
	}
	if opts.Ellipsis != nil {
		t.ellipsis = *opts.Ellipsis
	} else {
		t.ellipsis = "··"
	}
	if t.history != nil {
		t.history.override(string(t.input))
	}
	t.theme = resolveTheme(opts)
	return t
}

func resolveTheme(opts *Options) *ColorTheme {
	var base *ColorTheme
	term := os.Getenv("TERM")
	colorterm := os.Getenv("COLORTERM")
	if os.Getenv("NO_COLOR") != "" {
		base = NoColorTheme()
	} else if strings.Contains(term, "256") || colorterm == "truecolor" || colorterm == "24bit" {
		base = dupeTheme(Dark256)
	} else {
		base = dupeTheme(Default16)
	}
	theme := base
	for _, spec := range opts.ThemeSpecs {
		if strings.HasPrefix(spec, "\x00") {
			continue
		}
		if spec == "" {
			continue
		}
		theme, _ = applyColorSpec(theme, spec)
	}
	if opts.Black {
		theme.Bg = ColorAttr{colBlack, theme.Bg.Attr}
	}
	return theme
}

func defaultKeymap(opts *Options) *keymapT {
	km := newKeymap()
	add := func(e EventType, a string) {
		km.set(e.AsEvent(), []*action{{t: a}})
	}
	addR := func(r rune, a string) {
		_ = r
	}
	_ = addR
	add(Invalid, "invalid")
	add(CtrlA, "beginning-of-line")
	add(CtrlB, "backward-char")
	add(CtrlC, "abort")
	add(CtrlG, "abort")
	add(CtrlQ, "abort")
	add(Esc, "abort")
	add(CtrlD, "delete-char/eof")
	add(CtrlE, "end-of-line")
	add(CtrlF, "forward-char")
	add(CtrlH, "backward-delete-char")
	add(CtrlBackspace, "backward-delete-char")
	add(Backspace, "backward-delete-char")
	add(Tab, "toggle-down")
	add(ShiftTab, "toggle-up")
	add(CtrlJ, "down")
	add(CtrlK, "up")
	add(CtrlL, "clear-screen")
	add(Enter, "accept")
	add(CtrlN, "down-match")
	add(CtrlP, "up-match")
	add(AltDown, "down-match")
	add(AltUp, "up-match")
	add(CtrlU, "unix-line-discard")
	add(CtrlW, "unix-word-rubout")
	add(CtrlY, "yank")
	add(AltBackspace, "backward-kill-word")
	add(AltKey, "")
	km.m[AltKeyEvent('b')] = []*action{{t: "backward-word"}}
	km.m[AltKeyEvent('f')] = []*action{{t: "forward-word"}}
	km.m[AltKeyEvent('d')] = []*action{{t: "kill-word"}}
	km.m[AltKeyEvent('/')] = []*action{{t: "toggle-wrap"}}
	add(CtrlSlash, "toggle-wrap")
	add(ShiftLeft, "backward-word")
	add(ShiftRight, "forward-word")
	add(Up, "up")
	add(Down, "down")
	add(Left, "backward-char")
	add(Right, "forward-char")
	add(Home, "beginning-of-line")
	add(End, "end-of-line")
	add(Delete, "delete-char")
	add(PageUp, "page-up")
	add(PageDown, "page-down")
	add(ShiftUp, "preview-up")
	add(ShiftDown, "preview-down")
	add(Mouse, "mouse")
	add(DoubleClick, "accept")
	add(LeftClick, "ignore")
	add(RightClick, "toggle")
	add(SLeftClick, "toggle")
	add(SRightClick, "toggle")
	add(ScrollUp, "scroll-up")
	add(ScrollDown, "scroll-down")
	add(SScrollUp, "toggle-up")
	add(SScrollDown, "toggle-down")
	add(PreviewScrollUp, "preview-up")
	add(PreviewScrollDown, "preview-down")
	if opts.History != nil {
		add(CtrlP, "prev-history")
		add(CtrlN, "next-history")
	}
	// user bindings
	for _, e := range opts.Keymap.order {
		km.set(e, opts.Keymap.m[e])
	}
	delete(km.m, AltKey.AsEvent())
	return km
}

func (t *Terminal) heightFn(termH int) int {
	opts := t.opts
	h := opts.Height
	var height int
	if h.percent {
		height = int(float64(termH) * h.size / 100.0)
	} else {
		height = int(h.size)
	}
	if h.inverse {
		height = termH - height
	}
	if h.percent && !h.inverse || h.percent {
		minH := t.minHeight()
		if height < minH {
			height = minH
		}
	}
	if h.auto {
		ah := t.adaptiveHeight(termH)
		if ah < height {
			height = ah
		}
	}
	if height > termH {
		height = termH
	}
	if height < 1 {
		height = 1
	}
	return height
}

func (t *Terminal) minHeight() int {
	opts := t.opts
	if !opts.MinHeightAuto {
		return opts.MinHeight
	}
	n := opts.MinHeight
	if n < 0 {
		n = 10
	}
	// add non-list rows
	return n + t.nonListRows()
}

func (t *Terminal) nonListRows() int {
	rows := 0
	if !t.inputHidden {
		rows++
		if t.infoStyle == infoDefault || t.infoStyle == infoRight || (t.infoStyle == infoHidden || t.infoStyle == infoInlineRight) && t.separator != "" {
			rows++
		}
	}
	rows += len(t.header0)
	if t.opts.HeaderLines > 0 {
		rows += t.opts.HeaderLines
	}
	rows += t.borderRows()
	return rows
}

func (t *Terminal) borderRows() int {
	n := 0
	s := t.opts.BorderShape
	if s.HasTop() {
		n++
	}
	if s.HasBottom() {
		n++
	}
	return n
}

func (t *Terminal) adaptiveHeight(termH int) int {
	items, header, _, _ := t.store.snapshot()
	_ = header
	n := len(items)
	rows := n
	if !t.opts.Height.auto {
		return termH
	}
	if t.lastPattern != nil && !t.lastPattern.IsEmpty() {
		rows = len(t.results)
	}
	rows = n
	extra := t.nonListRows()
	m := t.opts.Margin
	p := t.opts.Padding
	extra += int(m[0].size) + int(m[2].size) + int(p[0].size) + int(p[2].size)
	if t.previewVisible() && (t.previewOpts.position == posUp || t.previewOpts.position == posDown) {
		// preview size
		if !t.previewOpts.size.percent {
			extra += int(t.previewOpts.size.size) + 2
		}
	}
	return rows + extra
}

func (t *Terminal) previewVisible() bool {
	return t.hasPreviewCommand() && !t.previewOpts.hidden && t.previewOpts.size.size > 0
}

func (t *Terminal) hasPreviewCommand() bool {
	return t.activePreviewCmd != "" || t.opts.Preview.command != ""
}

func (t *Terminal) previewCommand() string {
	if t.activePreviewCmd != "" {
		return t.activePreviewCmd
	}
	return t.opts.Preview.command
}

func (t *Terminal) currentItem() *Item {
	if t.cy >= 0 && t.cy < len(t.results) {
		return t.results[t.cy].item
	}
	return nil
}

func (t *Terminal) buildPattern() *Pattern {
	q := t.input
	if t.disabled {
		q = []rune{}
	}
	return BuildPattern(t.opts.Fuzzy, t.opts.FuzzyAlgo, t.opts.Extended, t.opts.Case, t.opts.Normalize,
		!hasEndCriterion(t.opts), true, true, t.nth, t.opts.Delimiter, t.nthRev, q)
}

// search runs matching and updates results
func (t *Terminal) search() {
	items, header, done, rev := t.store.snapshot()
	t.headerLines = header
	t.reading = !done
	pattern := t.buildPattern()
	t.lastPattern = pattern
	t.storeRev = rev
	t.total = len(items)
	var results []Result
	if pattern.IsEmpty() {
		results = make([]Result, len(items))
		for i, item := range items {
			results[i] = Result{item: item}
		}
		if t.opts.Tac {
			reverseResults(results)
		}
	} else {
		results = parallelMatch(pattern, items)
		if t.sort && pattern.sortable {
			sortResults(results, t.opts.Tac)
		} else if t.opts.Tac {
			reverseResults(results)
		}
	}
	prevItem := t.currentItem()
	t.results = results
	t.matchCount = len(results)
	if (t.track != trackDisabled || t.trackItem != nil) && prevItem != nil {
		target := prevItem
		if t.trackItem != nil {
			target = t.trackItem
		}
		found := false
		for i, r := range results {
			if r.item == target {
				t.cy = i
				found = true
				break
			}
		}
		if !found && t.track == trackCurrent {
			t.track = trackDisabled
		}
	}
	t.constrain()
}

func (t *Terminal) constrain() {
	count := len(t.results)
	if t.cy >= count {
		t.cy = count - 1
	}
	if t.cy < 0 {
		t.cy = 0
	}
	height := t.maxItems()
	if height <= 0 {
		t.offset = 0
		return
	}
	if t.offset > t.cy {
		t.offset = t.cy
	}
	if t.cy-t.offset >= height {
		t.offset = t.cy - height + 1
	}
	// scroll-off
	so := min(t.scrollOff, (height-1)/2)
	if so > 0 {
		if t.cy-t.offset < so {
			t.offset = max(0, t.cy-so)
		}
		if t.offset+height-1-t.cy < so {
			t.offset = min(count-height, t.cy+so-height+1)
		}
	}
	if t.offset > count-height {
		t.offset = max(0, count-height)
	}
	if t.offset < 0 {
		t.offset = 0
	}
}

func (t *Terminal) maxItems() int {
	h := t.listHeight
	if t.gap > 0 {
		return (h + t.gap) / (1 + t.gap)
	}
	return h
}

func runInteractive(opts *Options) int {
	store := newItemStore(opts)
	t := newTerminal(opts, store)
	return t.run()
}

func (t *Terminal) startReader() {
	opts := t.opts
	store := t.store
	go func() {
		delim := byte('\n')
		if opts.ReadZero {
			delim = 0
		}
		lastSignal := time.Now()
		add := func(line []byte) {
			cp := make([]byte, len(line))
			copy(cp, line)
			store.mu.Lock()
			if item := store.builder.build(cp); item != nil {
				store.items = append(store.items, item)
				if opts.Tail > 0 && len(store.items) > opts.Tail {
					store.items = store.items[len(store.items)-opts.Tail:]
				}
			}
			store.header = store.builder.header
			store.rev++
			store.mu.Unlock()
			if time.Since(lastSignal) > 20*time.Millisecond {
				store.signal()
				lastSignal = time.Now()
			}
		}
		if isTerminal(os.Stdin) {
			readFromDefaultSource(opts, add)
		} else {
			readLines(os.Stdin, delim, add)
		}
		store.mu.Lock()
		store.done = true
		store.rev++
		store.mu.Unlock()
		store.signal()
	}()
}

// waitForInput blocks until all input is read (used for --sync, -1, -0)
func (t *Terminal) waitForInput() {
	for {
		_, _, done, _ := t.store.snapshot()
		if done {
			return
		}
		<-t.store.notify
	}
}

func (t *Terminal) run() int {
	opts := t.opts
	t.startReader()

	// --select-1 / --exit-0 need the full result before starting the finder
	if opts.Select1 || opts.Exit0 || opts.Sync {
		t.waitForInput()
		t.listHeight = 1 << 20
		t.search()
		if opts.Select1 && len(t.results) == 1 {
			t.output = t.collectOutput(false)
			return t.finish(exitOk, false)
		}
		if opts.Exit0 && len(t.results) == 0 {
			t.output = t.collectOutput(true)
			return t.finish(exitNoMatch, false)
		}
	}

	screen, err := newScreen(opts)
	if err != nil {
		errorExit("Failed to open tty: " + err.Error())
	}
	t.screen = screen
	fullscreen := opts.Height.size == 0 && !opts.Height.auto || opts.Height.percent && opts.Height.size >= 100 && !opts.Height.auto
	if opts.Height.size == 0 && !opts.Height.auto && !opts.Height.inverse {
		fullscreen = true
	}
	if opts.Height.inverse {
		fullscreen = false
	}
	if err := screen.init(fullscreen, t.heightFn); err != nil {
		errorExit(err.Error())
	}
	t.resizeCh = make(chan os.Signal, 1)
	signal.Notify(t.resizeCh, syscall.SIGWINCH)
	t.sigCh = make(chan os.Signal, 1)
	signal.Notify(t.sigCh, syscall.SIGINT, syscall.SIGTERM, syscall.SIGHUP)

	t.layoutAndSearch()
	t.triggerEvent(Start.AsEvent())
	t.afterAction()
	t.render()

	ticker := time.NewTicker(100 * time.Millisecond)
	defer ticker.Stop()
	escTimer := (<-chan time.Time)(nil)
	for !t.quit {
		select {
		case data, ok := <-screen.keyCh:
			if !ok {
				t.quit = true
				t.exitCode = exitError
				break
			}
			screen.pending = append(screen.pending, data...)
			escTimer = t.processKeys(false)
		case <-escTimer:
			escTimer = nil
			t.processKeys(true)
		case <-t.store.notify:
			t.onNewData()
		case <-t.resizeCh:
			screen.resize(t.heightFn)
			t.layoutAndSearch()
			t.triggerEvent(Resize.AsEvent())
			t.afterAction()
		case <-ticker.C:
			if t.reading {
				t.spinIdx++
			}
		case <-t.previewNotify():
			t.onPreviewUpdate()
		case <-t.sigCh:
			t.quit = true
			t.exitCode = exitInterrupt
		}
		if len(screen.pending) > 0 && escTimer == nil {
			escTimer = t.processKeys(false)
		}
		if !t.quit {
			t.render()
		}
	}
	return t.finish(t.exitCode, true)
}

func (t *Terminal) onNewData() {
	_, _, done, rev := t.store.snapshot()
	if rev == t.storeRev && !done {
		return
	}
	wasReading := t.reading
	t.search()
	t.afterSearch()
	if wasReading && done && !t.loadFired {
		t.loadFired = true
		t.triggerEvent(Load.AsEvent())
	}
	t.afterAction()
}

func (t *Terminal) afterSearch() {
	t.triggerEvent(EvResult.AsEvent())
	if len(t.results) == 1 {
		t.triggerEvent(One.AsEvent())
	} else if len(t.results) == 0 {
		t.triggerEvent(Zero.AsEvent())
	}
}

func (t *Terminal) layoutAndSearch() {
	t.computeLayout()
	t.search()
	t.afterSearch()
}

func (t *Terminal) processKeys(timeout bool) <-chan time.Time {
	s := t.screen
	for len(s.pending) > 0 && !t.quit {
		ev, n, more := parseKey(s.pending)
		if more && !timeout {
			if n == 0 || s.pending[0] == 0x1b {
				return time.After(50 * time.Millisecond)
			}
		}
		if n == 0 {
			n = len(s.pending)
		}
		s.pending = s.pending[n:]
		timeout = false
		if ev.Type == BracketedPasteBegin {
			// read until end
			end := strings.Index(string(s.pending), "\x1b[201~")
			if end < 0 {
				// wait for more
				s.pending = append([]byte("\x1b[200~"), s.pending...)
				return time.After(200 * time.Millisecond)
			}
			text := string(s.pending[:end])
			s.pending = s.pending[end+6:]
			text = strings.ReplaceAll(text, "\r", "")
			text = strings.ReplaceAll(text, "\n", " ")
			for _, r := range text {
				if unicode.IsGraphic(r) {
					t.insertRune(r)
				}
			}
			t.onQueryMaybeChanged()
			continue
		}
		t.handleEvent(ev)
	}
	return nil
}

func (t *Terminal) insertRune(r rune) {
	t.input = append(t.input[:t.cx], append([]rune{r}, t.input[t.cx:]...)...)
	t.cx++
}
EOF
