func newTerminal(opts *Options, store *itemStore) *Terminal {
	t := &Terminal{opts: opts, store: store}
	t.input = []rune(opts.Query)
	t.cx = len(t.input)
	t.prompt = opts.Prompt
	t.layout = opts.Layout
	t.infoStyle = opts.InfoStyle
	t.infoPrefix = opts.InfoPrefix
	t.selected = make(map[*Item]selectedItem)
	t.multi = opts.Multi
	t.sort = opts.Sort > 0
	t.keymap = defaultKeymap(opts)
	t.expect = opts.Expect
	t.header0 = opts.Header
	t.footer = opts.Footer
	t.nth = opts.Nth
	t.disabled = opts.Phony
	t.inputHidden = opts.Inputless
	t.hscroll = opts.Hscroll
	t.wrap = opts.Wrap
	t.borderLabel = opts.BorderLabel.label
	t.previewLabel = opts.PreviewLabel.label
	t.listLabel = opts.ListLabel.label
	t.inputLabel = opts.InputLabel.label
	t.headerLabel = opts.HeaderLabel.label
	t.footerLabel = opts.FooterLabel.label
	t.ghost = opts.Ghost
	t.previewOpts = opts.Preview
	t.history = opts.History
	t.track = opts.Track
	t.cursorLine = opts.CursorLine
	t.scrollOff = opts.ScrollOff
	t.gap = opts.Gap
	t.unbound = make(map[Event]bool)
	t.infoCommand = opts.InfoCommand
	t.reading = true
	if opts.Unicode {
		t.spinner = []string{"⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"}
	} else {
		t.spinner = []string{"-", "\\", "|", "/", "-", "\\", "|", "/"}
	}
	// signs
	if opts.Pointer != nil {
		t.pointer = *opts.Pointer
	} else if opts.Unicode {
		t.pointer = "▌"
	} else {
		t.pointer = ">"
	}
	if opts.Marker != nil {
		t.marker = *opts.Marker
	} else if opts.Unicode {
		t.marker = "┃"
	} else {
		t.marker = ">"
	}
	if opts.Gutter != nil {
		t.gutter = *opts.Gutter
	} else if opts.Unicode {
		t.gutter = "▌"
	} else {
		t.gutter = " "
	}
	t.pointerLen = stringWidth(t.pointer)
	t.markerLen = stringWidth(t.marker)
	t.pointerEmpty = strings.Repeat(" ", t.pointerLen)
	t.markerEmpty = strings.Repeat(" ", t.markerLen)
	if opts.Separator != nil {
		t.separator = *opts.Separator
	} else if opts.Unicode {
		t.separator = "─"
	} else {
		t.separator = "-"
	}
	if opts.Scrollbar != nil {
		sb := splitGraphemes(*opts.Scrollbar)
		if len(sb) > 0 {
			t.scrollbar = sb[0]
			t.previewScrollbar = sb[0]
			if len(sb) > 1 {
				t.previewScrollbar = sb[1]
			}
		}
	} else if opts.Unicode {
		t.scrollbar = "│"
		t.previewScrollbar = "│"
	} else {
		t.scrollbar = "|"
		t.previewScrollbar = "|"
	}
	if opts.Ellipsis != nil {
		t.ellipsis = *opts.Ellipsis
	} else {
		t.ellipsis = "··"
	}
	if t.history != nil {
		t.history.override(string(t.input))
	}
	t.theme = resolveTheme(opts)
	return t
}

func resolveTheme(opts *Options) *ColorTheme {
	var base *ColorTheme
	term := os.Getenv("TERM")
	colorterm := os.Getenv("COLORTERM")
	if os.Getenv("NO_COLOR") != "" {
		base = NoColorTheme()
	} else if strings.Contains(term, "256") || colorterm == "truecolor" || colorterm == "24bit" {
		base = dupeTheme(Dark256)
	} else {
		base = dupeTheme(Default16)
	}
	theme := base
	for _, spec := range opts.ThemeSpecs {
		if strings.HasPrefix(spec, "\x00") {
			continue
		}
		if spec == "" {
			continue
		}
		theme, _ = applyColorSpec(theme, spec)
	}
	if opts.Black {
		theme.Bg = ColorAttr{colBlack, theme.Bg.Attr}
	}
	return theme
}

func defaultKeymap(opts *Options) *keymapT {
	km := newKeymap()
	add := func(e EventType, a string) {
		km.set(e.AsEvent(), []*action{{t: a}})
	}
	addR := func(r rune, a string) {
		_ = r
	}
	_ = addR
	add(Invalid, "invalid")
	add(CtrlA, "beginning-of-line")
	add(CtrlB, "backward-char")
	add(CtrlC, "abort")
	add(CtrlG, "abort")
