			trimmed += string(char)
		}
	}
	matchWithoutFlags := "{" + trimmed
	return false, matchWithoutFlags, flags
}

func quoteShell(s string) string {
	return "'" + strings.ReplaceAll(s, "'", "'\\''") + "'"
}

func hasPlusFlag(template string) bool {
	for _, match := range placeholderRegex.FindAllString(template, -1) {
		escaped, _, flags := parsePlaceholder(match)
		if !escaped && (flags.plus || flags.asterisk) {
			return true
		}
	}
	return false
}

type replaceContext struct {
	query    string
	current  *Item
	selected []*Item
	all      []*Item
	tempFiles *[]string
	prompt   string
	action   string
}

func (t *Terminal) replacePlaceholder(template string, forcePlus bool) (string, []string) {
	ctx := replaceContext{query: string(t.input), current: t.currentItem(), prompt: t.prompt, action: t.lastAction}
	sels := t.sortedSelection()
	for _, s := range sels {
		ctx.selected = append(ctx.selected, s.item)
	}
	tempFiles := []string{}
	ctx.tempFiles = &tempFiles
	needAll := strings.Contains(template, "{*")
	if needAll {
		for _, r := range t.results {
			ctx.all = append(ctx.all, r.item)
		}
	}
	return t.replace(template, ctx, forcePlus), tempFiles
}

func (t *Terminal) itemText(item *Item) string {
	return item.AsString(t.opts.Ansi)
}

func (t *Terminal) replace(template string, ctx replaceContext, forcePlus bool) string {
	delimiter := t.opts.Delimiter
	return placeholderRegex.ReplaceAllStringFunc(template, func(match string) string {
		escaped, match, flags := parsePlaceholder(match)
		if escaped {
			return match
		}
		switch match {
		case "{fzf:query}":
			return quoteShell(ctx.query)
		case "{fzf:action}":
			return ctx.action
		case "{fzf:prompt}":
			return quoteShell(ctx.prompt)
		}
		quote := func(s string) string {
			if flags.raw {
				return s
			}
			return quoteShell(s)
		}
		if strings.HasPrefix(match, "{q") {
			q := ctx.query
			if strings.HasPrefix(match, "{q:") {
				expr := match[3 : len(match)-1]
				preserve := false
				if strings.HasPrefix(expr, "s") {
					preserve = true
					expr = expr[1:]
				}
				ranges, err := splitNth(expr)
				if err == nil {
					tokens := Tokenize(q, delimiter)
					q = joinTokens(Transform(tokens, ranges))
					if !preserve {
						q = strings.TrimSpace(q)
					}
				}
			}
			return quote(q)
		}
		var items []*Item
		if flags.asterisk {
			items = ctx.all
		} else if (flags.plus || forcePlus) && len(ctx.selected) > 0 {
			items = ctx.selected
		} else if ctx.current != nil {
			items = []*Item{ctx.current}
		}
		if len(items) == 0 && !flags.file {
			return "''"
		}
		inner := match[1 : len(match)-1]
		var replacements []string
		for _, item := range items {
			var s string
			if flags.number {
				s = strconv.Itoa(int(item.index))
			} else if inner == "" {
				s = t.itemText(item)
			} else {
				ranges, err := splitNth(inner)
				if err != nil {
					s = ""
				} else {
					tokens := Tokenize(t.itemText(item), delimiter)
					trans := Transform(tokens, ranges)
					parts := make([]string, len(trans))
					for i, tok := range trans {
						p := tok.text.ToString()
						if !flags.preserveSpace {
							p = strings.TrimFunc(p, unicode.IsSpace)
						}
						parts[i] = p
					}
					s = strings.Join(parts, " ")
				}
			}
			if flags.file {
				replacements = append(replacements, s)
			} else if flags.number && !flags.raw {
				replacements = append(replacements, s)
			} else {
				replacements = append(replacements, quote(s))
			}
		}
		if flags.file {
			f, err := os.CreateTemp("", "fzf-preview-*")
			if err != nil {
				return "''"
			}
			sep := "\n"
			if t.opts.PrintZero {
				sep = "\x00"
			}
			f.WriteString(strings.Join(replacements, sep))
			if len(replacements) > 0 {
				f.WriteString(sep)
			}
			f.Close()
			*ctx.tempFiles = append(*ctx.tempFiles, f.Name())
			return f.Name()
		}
		return strings.Join(replacements, " ")
	})
}
