	case "toggle-wrap", "toggle-wrap-word":
		t.wrap = !t.wrap
	case "toggle-hscroll":
		t.hscroll = !t.hscroll
	case "toggle-header":
		t.headerHidden = !t.headerHidden
		t.computeLayout()
	case "show-header":
		t.headerHidden = false
		t.computeLayout()
	case "hide-header":
		t.headerHidden = true
		t.computeLayout()
	case "toggle-input":
		t.inputHidden = !t.inputHidden
		t.computeLayout()
	case "show-input":
		t.inputHidden = false
