		t.vmove(1, false)
	case "scroll-down":
		t.vmove(-1, false)
	case "toggle-footer", "show-footer", "hide-footer":
	}
}

func strLinesOrEmpty(s string) []string {
	if s == "" {
		return []string{}
	}
	return strLines(s)
}

func (t *Terminal) setPointer(p string) {
	t.pointer = p
	t.pointerLen = stringWidth(p)
	t.pointerEmpty = strings.Repeat(" ", t.pointerLen)
}

func (t *Terminal) offsetBy(n int) {
	if t.layout != layoutDefault {
		n = -n
	}
	t.offset += n
	t.constrainOffsetOnly()
	// keep cursor within view
	h := t.maxItems()
	if t.cy < t.offset {
		t.cy = t.offset
	} else if t.cy >= t.offset+h {
		t.cy = t.offset + h - 1
	}
}

func (t *Terminal) constrainOffsetOnly() {
	h := t.maxItems()
	count := len(t.results)
	if t.offset > count-h {
		t.offset = count - h
	}
	if t.offset < 0 {
		t.offset = 0
	}
}

func (t *Terminal) exclude(multi bool) {
	items := []*Item{}
	if multi && len(t.selected) > 0 {
		for _, s := range t.selected {
			items = append(items, s.item)
		}
		t.selected = make(map[*Item]selectedItem)
	} else if cur := t.currentItem(); cur != nil {
		items = append(items, cur)
		delete(t.selected, cur)
	}
	if len(items) == 0 {
		return
	}
	ex := make(map[*Item]bool)
	for _, it := range items {
		ex[it] = true
	}
	t.store.mu.Lock()
	kept := t.store.items[:0:0]
	for _, it := range t.store.items {
		if !ex[it] {
			kept = append(kept, it)
		}
	}
	t.store.items = kept
	t.store.rev++
	t.store.mu.Unlock()
	t.search()
}

func (t *Terminal) accept(force bool) {
	if len(t.results) == 0 && len(t.selected) == 0 {
		t.output = t.collectOutputWithKey("", true)
		t.quit = true
		t.exitCode = exitNoMatch
		return
	}
	t.output = t.collectOutputWithKey("", false)
	t.quit = true
	t.exitCode = exitOk
}

func (t *Terminal) changeNth(spec string) {
	opts := strings.Split(spec, "|")
	first := opts[0]
	if len(opts) > 1 {
		// rotate: find current, use next
		cur := nthString(t.nth)
		next := first
		for i, o := range opts {
			if o == cur && i+1 < len(opts) {
				next = opts[i+1]
			}
		}
		first = next
	}
	if first == "" {
		t.nth = t.opts.Nth
	} else if ranges, err := splitNth(first); err == nil {
		t.nth = ranges
	}
	t.nthRev++
	t.search()
}

func nthString(r []Range) string {
	parts := []string{}
	for _, x := range r {
		parts = append(parts, rangeString(x))
	}
	return strings.Join(parts, ",")
}

func rangeString(r Range) string {
	if r.begin == r.end {
		if r.begin == rangeEllipsis {
			return ".."
		}
		return strconv.Itoa(r.begin)
	}
	b, e := "", ""
	if r.begin != rangeEllipsis {
		b = strconv.Itoa(r.begin)
	}
	if r.end != rangeEllipsis {
		e = strconv.Itoa(r.end)
	}
	return b + ".." + e
}

func (t *Terminal) changePreviewWindow(spec string) {
	specs := strings.Split(spec, "|")
	// rotate through
	if t.pwIndex >= len(specs) {
		t.pwIndex = 0
	}
	s := specs[t.pwIndex]
	t.pwIndex = (t.pwIndex + 1) % len(specs)
	opts := t.opts.Preview
	opts.command = t.previewOpts.command
	if err := parsePreviewWindowImpl(&opts, s); err == nil {
		wasHidden := t.previewOpts.hidden
		t.previewOpts = opts
		t.computeLayout()
		if wasHidden && !opts.hidden {
			t.refreshPreview(true)
		}
	}
}

func (t *Terminal) applyTransform(out string, ev Event) {
	out = strings.TrimRight(out, "\n")
	if out == "" {
		return
	}
	km := newKeymap()
	if err := parseKeymap(km, "x:"+out); err != nil {
		return
	}
	acts, _ := km.get(KeyEvent('x'))
	t.doActions(acts, ev)
}

func (t *Terminal) exportEnv(cmd *exec.Cmd) {
	env := os.Environ()
	add := func(k, v string) {
		env = append(env, k+"="+v)
	}
	add("FZF_QUERY", string(t.input))
	add("FZF_ACTION", t.lastAction)
	add("FZF_KEY", t.lastKey)
	add("FZF_PROMPT", t.prompt)
	add("FZF_GHOST", t.ghost)
	add("FZF_POINTER", t.pointer)
	add("FZF_TOTAL_COUNT", strconv.Itoa(t.total))
	add("FZF_MATCH_COUNT", strconv.Itoa(len(t.results)))
	add("FZF_SELECT_COUNT", strconv.Itoa(len(t.selected)))
	add("FZF_POS", strconv.Itoa(min(len(t.results), t.cy+1)))
	add("FZF_LINES", strconv.Itoa(t.areaHeight))
	add("FZF_COLUMNS", strconv.Itoa(t.areaWidth))
	add("FZF_BORDER_LABEL", t.borderLabel)
	add("FZF_PREVIEW_LABEL", t.previewLabel)
	add("FZF_LIST_LABEL", t.listLabel)
	add("FZF_INPUT_LABEL", t.inputLabel)
	add("FZF_HEADER_LABEL", t.headerLabel)
	add("FZF_NTH", nthString(t.nth))
	state := "enabled"
	if t.inputHidden {
		state = "hidden"
	} else if t.disabled {
		state = "disabled"
	}
	add("FZF_INPUT_STATE", state)
	dir := "up"
	if t.layout != layoutDefault {
		dir = "down"
	}
	add("FZF_DIRECTION", dir)
	if t.previewer != nil || t.previewVisible() {
		pr := t.previewRect
		add("FZF_PREVIEW_LINES", strconv.Itoa(pr.height))
		add("FZF_PREVIEW_COLUMNS", strconv.Itoa(pr.width))
		add("FZF_PREVIEW_TOP", strconv.Itoa(pr.top))
		add("FZF_PREVIEW_LEFT", strconv.Itoa(pr.left))
		add("LINES", strconv.Itoa(pr.height))
		add("COLUMNS", strconv.Itoa(pr.width))
	}
	if t.listenPort > 0 {
		add("FZF_PORT", strconv.Itoa(t.listenPort))
	}
	if t.listenSock != "" {
		add("FZF_SOCK", t.listenSock)
	}
	cmd.Env = env
}

func (t *Terminal) captureOutput(template string) string {
	command, temps := t.replacePlaceholder(template, false)
	defer removeFiles(temps)
	cmd := shellCommand(t.opts, command)
	t.exportEnv(cmd)
	cmd.Stdin = nil
	out, _ := cmd.Output()
	return string(out)
}

func (t *Terminal) captureLine(template string) string {
	out := t.captureOutput(template)
	return strings.TrimRight(strings.SplitN(out, "\n", 2)[0], "\r")
}

func removeFiles(files []string) {
	for _, f := range files {
		os.Remove(f)
	}
}

func (t *Terminal) executeCommand(template string, silent bool, forcePlus bool) {
	command, temps := t.replacePlaceholder(template, forcePlus)
	defer removeFiles(temps)
	cmd := shellCommand(t.opts, command)
	t.exportEnv(cmd)
	if silent {
		cmd.Stdin = nil
		cmd.Run()
		return
	}
	tty, _ := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if tty != nil {
		cmd.Stdin = tty
		cmd.Stdout = tty
		cmd.Stderr = os.Stderr
	}
	t.screen.pause(true)
	cmd.Run()
	if tty != nil {
		tty.Close()
	}
	t.screen.resume(true, t.heightFn)
	t.computeLayout()
}

func (t *Terminal) become(template string) {
	command, _ := t.replacePlaceholder(template, false)
	if t.screen != nil {
		t.screen.close(true)
	}
	shell := os.Getenv("SHELL")
	if shell == "" {
		shell = "sh"
	}
	args := []string{shell, "-c", command}
	if t.opts.WithShell != "" {
		if words, err := parseShellWords(t.opts.WithShell); err == nil && len(words) > 0 {
			args = append(words, command)
		}
	}
	path, err := exec.LookPath(args[0])
	if err != nil {
		os.Exit(exitBecome + 1)
	}
	cmd := exec.Command(path)
	t.exportEnv(cmd)
	err = syscall.Exec(path, args, cmd.Env)
	if err != nil {
		os.Exit(exitBecome)
	}
}

func (t *Terminal) reload(template string, sync bool) {
	command, temps := t.replacePlaceholder(template, false)
	store := t.store
	store.reset()
	t.reading = true
	t.loadFired = false
	opts := t.opts
	run := func() {
		defer removeFiles(temps)
		cmd := shellCommand(opts, command)
		t.exportEnv(cmd)
		out, err := cmd.StdoutPipe()
		if err == nil && cmd.Start() == nil {
			delim := byte('\n')
			if opts.ReadZero {
				delim = 0
			}
			readLines(out, delim, func(line []byte) {
				cp := make([]byte, len(line))
				copy(cp, line)
				store.mu.Lock()
				if item := store.builder.build(cp); item != nil {
					store.items = append(store.items, item)
				}
				store.header = store.builder.header
				store.rev++
				store.mu.Unlock()
				store.signal()
			})
			cmd.Wait()
		}
		store.mu.Lock()
		store.done = true
		store.rev++
		store.mu.Unlock()
		store.signal()
	}
	if sync {
		run()
		t.search()
	} else {
		go run()
	}
}
EOF
echo ok"}

actions.command:
cd /workspace && cat > doactions.go <<'EOF'
package main

import (
	"os"
	"os/exec"
	"strconv"
	"strings"
	"syscall"
	"unicode"
)

func (t *Terminal) doActions(acts []*action, ev Event) {
	for _, a := range acts {
		if t.quit {
			return
		}
		t.doAction(a, ev)
	}
}

func isWordRune(r rune) bool {
	return unicode.IsLetter(r) || unicode.IsNumber(r)
}

func (t *Terminal) findLastWordBoundary(filepath bool) int {
	cx := t.cx
	for cx > 0 && !t.isWordChar(t.input[cx-1], filepath) {
		cx--
	}
	for cx > 0 && t.isWordChar(t.input[cx-1], filepath) {
		cx--
	}
	return cx
}

func (t *Terminal) isWordChar(r rune, filepath bool) bool {
	if filepath {
		return r != '/' && !unicode.IsSpace(r)
	}
	return isWordRune(r)
}

func (t *Terminal) findNextWordBoundary(filepath bool) int {
	cx := t.cx
	n := len(t.input)
	for cx < n && !t.isWordChar(t.input[cx], filepath) {
		cx++
	}
	for cx < n && t.isWordChar(t.input[cx], filepath) {
		cx++
	}
	return cx
}

func (t *Terminal) vmove(o int, allowCycle bool) {
	if t.layout != layoutDefault {
		o *= -1
	}
	dest := t.cy + o
	if t.opts.Cycle && allowCycle {
		max := len(t.results) - 1
		if dest > max {
			if t.cy == max {
				dest = 0
			}
		} else if dest < 0 {
			if t.cy == 0 {
				dest = max
			}
		}
	}
	t.vset(dest)
}

func (t *Terminal) vset(o int) bool {
	t.cy = o
	if t.cy >= len(t.results) {
		t.cy = len(t.results) - 1
	}
	if t.cy < 0 {
		t.cy = 0
	}
	t.constrain()
	return t.cy == o
}

func (t *Terminal) doAction(a *action, ev Event) {
	t.lastAction = a.t
	switch a.t {
	case "ignore", "invalid", "":
	case "put":
		if a.a != "" {
			for _, r := range a.a {
				t.insertRune(r)
			}
		} else if ev.Type == Rune {
			t.insertRune(ev.Char)
		}
	case "beginning-of-line":
		t.cx = 0
	case "end-of-line":
		t.cx = len(t.input)
	case "backward-char":
		if t.cx > 0 {
			t.cx--
		}
	case "forward-char":
		if t.cx < len(t.input) {
			t.cx++
		}
	case "backward-delete-char":
		if t.cx > 0 {
			t.input = append(t.input[:t.cx-1], t.input[t.cx:]...)
			t.cx--
		} else if len(t.input) == 0 {
			t.triggerEvent(BackwardEOF.AsEvent())
		}
	case "backward-delete-char/eof":
		if len(t.input) == 0 {
			t.quit = true
			t.exitCode = exitInterrupt
		} else if t.cx > 0 {
			t.input = append(t.input[:t.cx-1], t.input[t.cx:]...)
			t.cx--
		}
	case "delete-char":
		if t.cx < len(t.input) {
			t.input = append(t.input[:t.cx], t.input[t.cx+1:]...)
		}
	case "delete-char/eof":
		if len(t.input) == 0 {
			t.quit = true
			t.exitCode = exitInterrupt
		} else if t.cx < len(t.input) {
			t.input = append(t.input[:t.cx], t.input[t.cx+1:]...)
		}
	case "unix-line-discard":
		if t.cx > 0 {
			t.yanked = append([]rune{}, t.input[:t.cx]...)
			t.input = t.input[t.cx:]
			t.cx = 0
		}
	case "kill-line":
		if t.cx < len(t.input) {
			t.yanked = append([]rune{}, t.input[t.cx:]...)
			t.input = t.input[:t.cx]
		}
	case "unix-word-rubout":
		if t.cx > 0 {
			pcx := t.cx
			for t.cx > 0 && unicode.IsSpace(t.input[t.cx-1]) {
				t.cx--
			}
			for t.cx > 0 && !unicode.IsSpace(t.input[t.cx-1]) {
				if t.opts.FileWord && t.input[t.cx-1] == '/' && t.cx != pcx {
					break
				}
				t.cx--
			}
			t.yanked = append([]rune{}, t.input[t.cx:pcx]...)
			t.input = append(t.input[:t.cx], t.input[pcx:]...)
		}
	case "backward-kill-word", "backward-kill-subword":
		if t.cx > 0 {
			ncx := t.findLastWordBoundary(t.opts.FileWord)
			t.yanked = append([]rune{}, t.input[ncx:t.cx]...)
			t.input = append(t.input[:ncx], t.input[t.cx:]...)
			t.cx = ncx
		}
	case "kill-word", "kill-subword":
		ncx := t.findNextWordBoundary(t.opts.FileWord)
		if ncx > t.cx {
			t.yanked = append([]rune{}, t.input[t.cx:ncx]...)
			t.input = append(t.input[:t.cx], t.input[ncx:]...)
		}
	case "backward-word", "backward-subword":
		t.cx = t.findLastWordBoundary(t.opts.FileWord)
	case "forward-word", "forward-subword":
		t.cx = t.findNextWordBoundary(t.opts.FileWord)
	case "yank":
		if len(t.yanked) > 0 {
			suffix := append([]rune{}, t.input[t.cx:]...)
			t.input = append(append(t.input[:t.cx], t.yanked...), suffix...)
			t.cx += len(t.yanked)
		}
	case "clear-query":
		t.input = []rune{}
		t.cx = 0
	case "cancel":
		if len(t.input) > 0 {
			t.yanked = append([]rune{}, t.input...)
			t.input = []rune{}
			t.cx = 0
		} else {
			t.quit = true
			t.exitCode = exitInterrupt
		}
	case "abort":
		t.quit = true
		t.exitCode = exitInterrupt
	case "close":
		if t.previewVisible() {
			t.previewOpts.hidden = true
			t.computeLayout()
		} else {
			t.quit = true
			t.exitCode = exitInterrupt
		}
	case "accept":
		t.accept(false)
	case "accept-non-empty":
		if len(t.selected) > 0 || len(t.results) > 0 {
			t.accept(false)
		}
	case "accept-or-print-query":
		if len(t.results) == 0 && len(t.selected) == 0 {
			t.output = []string{}
			if t.opts.PrintQuery {
				t.output = append(t.output, string(t.input))
			}
			if len(t.opts.Expect) > 0 {
				t.output = append(t.output, "")
			}
			t.output = append(t.output, t.printQueue...)
			if !t.opts.PrintQuery {
				t.output = append(t.output, string(t.input))
			}
			t.quit = true
			t.exitCode = exitOk
		} else {
			t.accept(false)
		}
	case "print-query":
		t.output = []string{string(t.input)}
		t.quit = true
		t.exitCode = exitOk
	case "print":
		t.printQueue = append(t.printQueue, a.a)
	case "up":
		t.vmove(1, true)
	case "down":
		t.vmove(-1, true)
	case "up-match":
		t.vmove(1, true)
	case "down-match":
		t.vmove(-1, true)
	case "page-up":
		t.vmove(t.maxItems()-1, false)
	case "page-down":
		t.vmove(-(t.maxItems() - 1), false)
	case "half-page-up":
		t.vmove(max(1, t.maxItems()/2), false)
	case "half-page-down":
		t.vmove(-max(1, t.maxItems()/2), false)
	case "first", "best":
		t.vset(0)
	case "last":
		t.vset(len(t.results) - 1)
	case "pos":
		if n, err := strconv.Atoi(a.a); err == nil {
			if n > 0 {
				t.vset(n - 1)
			} else if n < 0 {
				t.vset(len(t.results) + n)
			}
		}
	case "offset-up":
		t.offsetBy(1)
	case "offset-down":
		t.offsetBy(-1)
	case "offset-middle":
		h := t.maxItems()
		t.offset = max(0, t.cy-h/2)
		t.constrainOffsetOnly()
	case "toggle":
		if t.multi > 0 && len(t.results) > 0 {
			t.toggleItem(t.currentItem())
			t.triggerEvent(Multi.AsEvent())
		}
	case "toggle-down":
		if t.multi > 0 && len(t.results) > 0 {
			if t.toggleItem(t.currentItem()) {
				t.vmove(-1, true)
			}
			t.triggerEvent(Multi.AsEvent())
		}
	case "toggle-up":
		if t.multi > 0 && len(t.results) > 0 {
			if t.toggleItem(t.currentItem()) {
				t.vmove(1, true)
			}
			t.triggerEvent(Multi.AsEvent())
		}
	case "toggle-in":
		if t.layout != layoutDefault {
			t.doAction(&action{t: "toggle-up"}, ev)
		} else {
			t.doAction(&action{t: "toggle-down"}, ev)
		}
	case "toggle-out":
		if t.layout != layoutDefault {
			t.doAction(&action{t: "toggle-down"}, ev)
		} else {
			t.doAction(&action{t: "toggle-up"}, ev)
		}
	case "select":
		if t.multi > 0 && len(t.results) > 0 {
			t.selectItem(t.currentItem())
			t.triggerEvent(Multi.AsEvent())
		}
	case "deselect":
		if t.multi > 0 && len(t.results) > 0 {
			t.deselectItem(t.currentItem())
			t.triggerEvent(Multi.AsEvent())
		}
	case "select-all":
		if t.multi > 0 {
			for _, r := range t.results {
				if !t.selectItem(r.item) {
					break
				}
			}
			t.triggerEvent(Multi.AsEvent())
		}
	case "deselect-all":
		if t.multi > 0 {
			for _, r := range t.results {
				t.deselectItem(r.item)
			}
			t.triggerEvent(Multi.AsEvent())
		}
	case "toggle-all":
		if t.multi > 0 {
			for _, r := range t.results {
				t.toggleItem(r.item)
			}
			t.triggerEvent(Multi.AsEvent())
		}
	case "clear-multi":
		t.selected = make(map[*Item]selectedItem)
		t.triggerEvent(Multi.AsEvent())
	case "change-multi":
		if a.a == "" {
			t.multi = maxMulti
		} else if n, err := strconv.Atoi(a.a); err == nil && n >= 0 {
			t.multi = n
			if n == 0 {
				t.selected = make(map[*Item]selectedItem)
			}
		}
	case "toggle-sort":
		t.sort = !t.sort
		t.toggleSort = true
		t.search()
	case "toggle-search":
		t.disabled = !t.disabled
		t.search()
	case "enable-search":
		if t.disabled {
			t.disabled = false
			t.search()
		}
	case "disable-search":
		if !t.disabled {
			t.disabled = true
			t.search()
		}
	case "change-query":
		t.input = []rune(a.a)
		t.cx = len(t.input)
	case "transform-query", "bg-transform-query":
		out := t.captureLine(a.a)
		t.input = []rune(out)
		t.cx = len(t.input)
	case "search":
		saved := t.input
		t.input = []rune(a.a)
		t.search()
		t.input = saved
	case "transform-search", "bg-transform-search":
		out := t.captureLine(a.a)
		saved := t.input
		t.input = []rune(out)
		t.search()
		t.input = saved
	case "replace-query":
		if cur := t.currentItem(); cur != nil {
			t.input = []rune(cur.text.ToString())
			t.cx = len(t.input)
		}
	case "change-prompt":
		t.prompt = a.a
	case "transform-prompt", "bg-transform-prompt":
		t.prompt = t.captureLine(a.a)
	case "change-pointer":
		t.setPointer(a.a)
	case "transform-pointer", "bg-transform-pointer":
		t.setPointer(t.captureLine(a.a))
	case "change-ghost":
		t.ghost = a.a
	case "transform-ghost", "bg-transform-ghost":
		t.ghost = t.captureLine(a.a)
	case "change-header":
		t.header0 = strLinesOrEmpty(a.a)
		t.computeLayout()
	case "transform-header", "bg-transform-header":
		t.header0 = strLinesOrEmpty(t.captureOutput(a.a))
		t.computeLayout()
	case "change-footer":
		t.footer = strLinesOrEmpty(a.a)
		t.computeLayout()
	case "transform-footer", "bg-transform-footer":
		t.footer = strLinesOrEmpty(t.captureOutput(a.a))
		t.computeLayout()
	case "change-border-label":
		t.borderLabel = a.a
	case "transform-border-label", "bg-transform-border-label":
		t.borderLabel = t.captureLine(a.a)
	case "change-preview-label":
		t.previewLabel = a.a
	case "transform-preview-label", "bg-transform-preview-label":
		t.previewLabel = t.captureLine(a.a)
	case "change-list-label":
		t.listLabel = a.a
	case "transform-list-label", "bg-transform-list-label":
		t.listLabel = t.captureLine(a.a)
	case "change-input-label":
		t.inputLabel = a.a
	case "transform-input-label", "bg-transform-input-label":
		t.inputLabel = t.captureLine(a.a)
	case "change-header-label":
		t.headerLabel = a.a
	case "transform-header-label", "bg-transform-header-label":
		t.headerLabel = t.captureLine(a.a)
	case "change-footer-label":
		t.footerLabel = a.a
	case "transform-footer-label", "bg-transform-footer-label":
		t.footerLabel = t.captureLine(a.a)
	case "change-nth":
		t.changeNth(a.a)
	case "transform-nth", "bg-transform-nth":
		t.changeNth(t.captureLine(a.a))
	case "transform", "bg-transform":
		out := t.captureOutput(a.a)
		t.applyTransform(out, ev)
	case "execute", "execute-multi":
		t.executeCommand(a.a, false, a.t == "execute-multi")
	case "execute-silent":
		t.executeCommand(a.a, true, false)
	case "become":
		t.become(a.a)
	case "reload", "reload-sync":
		t.reload(a.a, a.t == "reload-sync")
	case "unbind":
		if chords, err := parseKeyChordsImpl(a.a, ""); err == nil {
			for _, c := range chords {
				t.unbound[c.event.Comparable()] = true
			}
		}
	case "rebind":
		if chords, err := parseKeyChordsImpl(a.a, ""); err == nil {
			for _, c := range chords {
				delete(t.unbound, c.event.Comparable())
			}
		}
	case "toggle-bind":
		if chords, err := parseKeyChordsImpl(a.a, ""); err == nil {
			for _, c := range chords {
				e := c.event.Comparable()
				if t.unbound[e] {
					delete(t.unbound, e)
				} else {
					t.unbound[e] = true
				}
			}
		}
	case "trigger":
		if chords, err := parseKeyChordsImpl(a.a, ""); err == nil {
			for _, c := range chords {
				if acts, ok := t.keymap.get(c.event); ok && !t.unbound[c.event.Comparable()] {
					t.doActions(acts, c.event)
				} else if c.event.Type == Rune {
					t.insertRune(c.event.Char)
				}
			}
		}
	case "toggle-preview":
		if t.hasPreviewCommand() {
			t.previewOpts.hidden = !t.previewOpts.hidden
			t.computeLayout()
			if t.previewVisible() {
				t.refreshPreview(true)
			}
		}
	case "show-preview":
		if t.previewOpts.hidden {
			t.previewOpts.hidden = false
			t.computeLayout()
			t.refreshPreview(true)
		}
	case "hide-preview":
		if !t.previewOpts.hidden {
			t.previewOpts.hidden = true
			t.computeLayout()
		}
	case "toggle-preview-wrap":
		t.previewOpts.wrap = !t.previewOpts.wrap
	case "preview":
		t.activePreviewCmd = a.a
		if t.previewOpts.hidden {
			t.previewOpts.hidden = false
		}
		t.computeLayout()
		t.refreshPreview(true)
	case "change-preview":
		t.activePreviewCmd = a.a
		t.refreshPreview(true)
	case "refresh-preview":
		t.refreshPreview(true)
	case "change-preview-window":
		t.changePreviewWindow(a.a)
	case "preview-up":
		t.previewScroll(-1)
	case "preview-down":
		t.previewScroll(1)
	case "preview-page-up":
		t.previewScroll(-max(1, t.previewHeight()-1))
	case "preview-page-down":
		t.previewScroll(max(1, t.previewHeight()-1))
	case "preview-half-page-up":
		t.previewScroll(-max(1, t.previewHeight()/2))
	case "preview-half-page-down":
		t.previewScroll(max(1, t.previewHeight()/2))
	case "preview-top":
		if t.previewer != nil {
			t.previewer.offset = 0
		}
	case "preview-bottom":
		if t.previewer != nil {
			t.previewer.offset = max(0, len(t.previewer.lines)-t.previewHeight())
		}
	case "toggle-wrap", "toggle-wrap-word":
		t.wrap = !t.wrap
	case "toggle-hscroll":
		t.hscroll = !t.hscroll
	case "toggle-header":
		t.headerHidden = !t.headerHidden
		t.computeLayout()
	case "show-header":
		t.headerHidden = false
		t.computeLayout()
	case "hide-header":
		t.headerHidden = true
		t.computeLayout()
	case "toggle-input":
		t.inputHidden = !t.inputHidden
		t.computeLayout()
	case "show-input":
		t.inputHidden = false
		t.computeLayout()
	case "hide-input":
		t.inputHidden = true
		t.computeLayout()
	case "toggle-track":
		if t.track == trackEnabled {
			t.track = trackDisabled
		} else {
			t.track = trackEnabled
		}
	case "track-current", "toggle-track-current":
		if a.t == "toggle-track-current" && t.trackItem != nil {
			t.trackItem = nil
		} else {
			t.trackItem = t.currentItem()
		}
	case "untrack-current":
		t.trackItem = nil
	case "clear-screen":
		t.screen.invalidate()
		t.screen.write("\x1b[2J")
	case "bell":
		t.screen.write("\a")
	case "jump", "jump-accept":
		t.jumping = 1
		if a.t == "jump-accept" {
			t.jumping = 2
		}
	case "prev-history":
		if t.history != nil {
			t.history.override(string(t.input))
			t.input = []rune(t.history.previous())
			t.cx = len(t.input)
		}
	case "next-history":
		if t.history != nil {
			t.history.override(string(t.input))
			t.input = []rune(t.history.next())
			t.cx = len(t.input)
		}
	case "up-selected", "down-selected":
		dir := 1
		if a.t == "down-selected" {
			dir = -1
		}
		if t.layout != layoutDefault {
			dir = -dir
		}
		for i := t.cy + dir; i >= 0 && i < len(t.results); i += dir {
			if t.isSelected(t.results[i].item) {
				t.vset(i)
				break
			}
		}
	case "exclude", "exclude-multi":
		t.exclude(a.t == "exclude-multi")
	case "toggle-raw", "enable-raw", "disable-raw", "toggle-multi-line", "bg-cancel":
	case "scroll-up":
		t.vmove(1, false)
	case "scroll-down":
		t.vmove(-1, false)
	case "toggle-footer", "show-footer", "hide-footer":
	}
}

func strLinesOrEmpty(s string) []string {
	if s == "" {
		return []string{}
	}
	return strLines(s)
}

func (t *Terminal) setPointer(p string) {
	t.pointer = p
	t.pointerLen = stringWidth(p)
	t.pointerEmpty = strings.Repeat(" ", t.pointerLen)
}

func (t *Terminal) offsetBy(n int) {
	if t.layout != layoutDefault {
		n = -n
	}
	t.offset += n
	t.constrainOffsetOnly()
	// keep cursor within view
	h := t.maxItems()
	if t.cy < t.offset {
		t.cy = t.offset
	} else if t.cy >= t.offset+h {
		t.cy = t.offset + h - 1
	}
}

func (t *Terminal) constrainOffsetOnly() {
	h := t.maxItems()
	count := len(t.results)
	if t.offset > count-h {
		t.offset = count - h
	}
	if t.offset < 0 {
		t.offset = 0
	}
}

func (t *Terminal) exclude(multi bool) {
	items := []*Item{}
	if multi && len(t.selected) > 0 {
		for _, s := range t.selected {
			items = append(items, s.item)
		}
		t.selected = make(map[*Item]selectedItem)
	} else if cur := t.currentItem(); cur != nil {
		items = append(items, cur)
		delete(t.selected, cur)
	}
	if len(items) == 0 {
		return
	}
	ex := make(map[*Item]bool)
	for _, it := range items {
		ex[it] = true
	}
	t.store.mu.Lock()
	kept := t.store.items[:0:0]
	for _, it := range t.store.items {
		if !ex[it] {
			kept = append(kept, it)
		}
	}
	t.store.items = kept
	t.store.rev++
	t.store.mu.Unlock()
	t.search()
}

func (t *Terminal) accept(force bool) {
	if len(t.results) == 0 && len(t.selected) == 0 {
		t.output = t.collectOutputWithKey("", true)
		t.quit = true
		t.exitCode = exitNoMatch
		return
	}
	t.output = t.collectOutputWithKey("", false)
	t.quit = true
	t.exitCode = exitOk
}

func (t *Terminal) changeNth(spec string) {
	opts := strings.Split(spec, "|")
	first := opts[0]
	if len(opts) > 1 {
		// rotate: find current, use next
		cur := nthString(t.nth)
		next := first
		for i, o := range opts {
			if o == cur && i+1 < len(opts) {
				next = opts[i+1]
			}
		}
		first = next
	}
	if first == "" {
		t.nth = t.opts.Nth
	} else if ranges, err := splitNth(first); err == nil {
		t.nth = ranges
	}
	t.nthRev++
	t.search()
}

func nthString(r []Range) string {
	parts := []string{}
	for _, x := range r {
		parts = append(parts, rangeString(x))
	}
	return strings.Join(parts, ",")
}

func rangeString(r Range) string {
	if r.begin == r.end {
		if r.begin == rangeEllipsis {
			return ".."
		}
		return strconv.Itoa(r.begin)
	}
	b, e := "", ""
	if r.begin != rangeEllipsis {
		b = strconv.Itoa(r.begin)
	}
	if r.end != rangeEllipsis {
		e = strconv.Itoa(r.end)
	}
	return b + ".." + e
}

func (t *Terminal) changePreviewWindow(spec string) {
	specs := strings.Split(spec, "|")
	// rotate through
	if t.pwIndex >= len(specs) {
		t.pwIndex = 0
	}
	s := specs[t.pwIndex]
	t.pwIndex = (t.pwIndex + 1) % len(specs)
	opts := t.opts.Preview
	opts.command = t.previewOpts.command
	if err := parsePreviewWindowImpl(&opts, s); err == nil {
		wasHidden := t.previewOpts.hidden
		t.previewOpts = opts
		t.computeLayout()
		if wasHidden && !opts.hidden {
			t.refreshPreview(true)
		}
	}
}

func (t *Terminal) applyTransform(out string, ev Event) {
	out = strings.TrimRight(out, "\n")
	if out == "" {
		return
	}
	km := newKeymap()
	if err := parseKeymap(km, "x:"+out); err != nil {
		return
	}
	acts, _ := km.get(KeyEvent('x'))
	t.doActions(acts, ev)
}

func (t *Terminal) exportEnv(cmd *exec.Cmd) {
	env := os.Environ()
	add := func(k, v string) {
		env = append(env, k+"="+v)
	}
	add("FZF_QUERY", string(t.input))
	add("FZF_ACTION", t.lastAction)
	add("FZF_KEY", t.lastKey)
	add("FZF_PROMPT", t.prompt)
	add("FZF_GHOST", t.ghost)
	add("FZF_POINTER", t.pointer)
	add("FZF_TOTAL_COUNT", strconv.Itoa(t.total))
	add("FZF_MATCH_COUNT", strconv.Itoa(len(t.results)))
	add("FZF_SELECT_COUNT", strconv.Itoa(len(t.selected)))
	add("FZF_POS", strconv.Itoa(min(len(t.results), t.cy+1)))
	add("FZF_LINES", strconv.Itoa(t.areaHeight))
	add("FZF_COLUMNS", strconv.Itoa(t.areaWidth))
	add("FZF_BORDER_LABEL", t.borderLabel)
	add("FZF_PREVIEW_LABEL", t.previewLabel)
	add("FZF_LIST_LABEL", t.listLabel)
	add("FZF_INPUT_LABEL", t.inputLabel)
	add("FZF_HEADER_LABEL", t.headerLabel)
	add("FZF_NTH", nthString(t.nth))
	state := "enabled"
	if t.inputHidden {
		state = "hidden"
	} else if t.disabled {
		state = "disabled"
	}
	add("FZF_INPUT_STATE", state)
	dir := "up"
	if t.layout != layoutDefault {
		dir = "down"
	}
	add("FZF_DIRECTION", dir)
	if t.previewer != nil || t.previewVisible() {
		pr := t.previewRect
		add("FZF_PREVIEW_LINES", strconv.Itoa(pr.height))
		add("FZF_PREVIEW_COLUMNS", strconv.Itoa(pr.width))
		add("FZF_PREVIEW_TOP", strconv.Itoa(pr.top))
		add("FZF_PREVIEW_LEFT", strconv.Itoa(pr.left))
		add("LINES", strconv.Itoa(pr.height))
		add("COLUMNS", strconv.Itoa(pr.width))
	}
	if t.listenPort > 0 {
		add("FZF_PORT", strconv.Itoa(t.listenPort))
	}
	if t.listenSock != "" {
		add("FZF_SOCK", t.listenSock)
	}
	cmd.Env = env
}

func (t *Terminal) captureOutput(template string) string {
	command, temps := t.replacePlaceholder(template, false)
	defer removeFiles(temps)
	cmd := shellCommand(t.opts, command)
	t.exportEnv(cmd)
	cmd.Stdin = nil
	out, _ := cmd.Output()
	return string(out)
}

func (t *Terminal) captureLine(template string) string {
	out := t.captureOutput(template)
	return strings.TrimRight(strings.SplitN(out, "\n", 2)[0], "\r")
}

func removeFiles(files []string) {
	for _, f := range files {
		os.Remove(f)
	}
}

func (t *Terminal) executeCommand(template string, silent bool, forcePlus bool) {
	command, temps := t.replacePlaceholder(template, forcePlus)
	defer removeFiles(temps)
	cmd := shellCommand(t.opts, command)
	t.exportEnv(cmd)
	if silent {
		cmd.Stdin = nil
		cmd.Run()
		return
	}
	tty, _ := os.OpenFile("/dev/tty", os.O_RDWR, 0)
	if tty != nil {
		cmd.Stdin = tty
		cmd.Stdout = tty
		cmd.Stderr = os.Stderr
	}
	t.screen.pause(true)
	cmd.Run()
	if tty != nil {
		tty.Close()
	}
	t.screen.resume(true, t.heightFn)
	t.computeLayout()
}

func (t *Terminal) become(template string) {
	command, _ := t.replacePlaceholder(template, false)
	if t.screen != nil {
		t.screen.close(true)
	}
	shell := os.Getenv("SHELL")
	if shell == "" {
		shell = "sh"
	}
	args := []string{shell, "-c", command}
	if t.opts.WithShell != "" {
		if words, err := parseShellWords(t.opts.WithShell); err == nil && len(words) > 0 {
			args = append(words, command)
		}
	}
	path, err := exec.LookPath(args[0])
	if err != nil {
		os.Exit(exitBecome + 1)
	}
	cmd := exec.Command(path)
	t.exportEnv(cmd)
	err = syscall.Exec(path, args, cmd.Env)
	if err != nil {
		os.Exit(exitBecome)
	}
}

func (t *Terminal) reload(template string, sync bool) {
	command, temps := t.replacePlaceholder(template, false)
	store := t.store
	store.reset()
	t.reading = true
	t.loadFired = false
	opts := t.opts
	run := func() {
		defer removeFiles(temps)
		cmd := shellCommand(opts, command)
		t.exportEnv(cmd)
		out, err := cmd.StdoutPipe()
		if err == nil && cmd.Start() == nil {
			delim := byte('\n')
			if opts.ReadZero {
				delim = 0
			}
			readLines(out, delim, func(line []byte) {
				cp := make([]byte, len(line))
				copy(cp, line)
				store.mu.Lock()
				if item := store.builder.build(cp); item != nil {
					store.items = append(store.items, item)
				}
				store.header = store.builder.header
				store.rev++
				store.mu.Unlock()
				store.signal()
			})
			cmd.Wait()
		}
		store.mu.Lock()
		store.done = true
		store.rev++
		store.mu.Unlock()
		store.signal()
	}
	if sync {
		run()
		t.search()
	} else {
		go run()
	}
}
