	case BorderBold:
		return borderChars{"━", "━", "┃", "┃", "┏", "┓", "┗", "┛"}
	case BorderDouble:
		return borderChars{"═", "═", "║", "║", "╔", "╗", "╚", "╝"}
	case BorderBlock:
		return borderChars{"▀", "▄", "▌", "▐", "▛", "▜", "▙", "▟"}
	case BorderThinBlock:
		return borderChars{"▔", "▁", "▏", "▕", "🭽", "🭾", "🭼", "🭿"}
	}
	return borderChars{"─", "─", "│", "│", "╭", "╮", "╰", "╯"}
}

func sizeOf(spec sizeSpec, total int) int {
	if spec.percent {
		return int(float64(total) * spec.size / 100.0)
	}
	return int(spec.size)
}

func shrink(r rect, top, right, bottom, left int) rect {
	r.top += top
	r.left += left
	r.width -= left + right
	r.height -= top + bottom
	if r.width < 0 {
		r.width = 0
	}
	if r.height < 0 {
		r.height = 0
	}
	return r
}

func (t *Terminal) effectiveBorder() BorderShape {
	s := t.opts.BorderShape
	if s == BorderUndefined {
		return BorderNone
	}
	if s == BorderLine {
		if t.screen != nil && !t.screen.fullscreen {
			return BorderTop
		}
		return BorderNone
	}
	return s
}

func (t *Terminal) previewBorderShape() BorderShape {
	s := t.previewOpts.border
	if s == BorderUndefined {
		return BorderRounded
	}
	return s
}

// computeLayout computes the geometry of all sections
func (t *Terminal) computeLayout() {
	if t.screen == nil {
		return
	}
	W, H := t.screen.width, t.screen.height
	m := t.opts.Margin
	mt := sizeOf(m[0], H)
	mr := sizeOf(m[1], W)
	mb := sizeOf(m[2], H)
	ml := sizeOf(m[3], W)
	area := rect{mt, ml, W - ml - mr, H - mt - mb}
	if area.width < 0 {
		area.width = 0
	}
	if area.height < 0 {
		area.height = 0
	}
	t.borderRect = area
	shape := t.effectiveBorder()
	t.mainBorder = shape
	inner := area
	if shape.HasTop() {
		inner = shrink(inner, 1, 0, 0, 0)
	}
	if shape.HasBottom() {
		inner = shrink(inner, 0, 0, 1, 0)
	}
	if shape.HasLeft() {
		inner = shrink(inner, 0, 0, 0, 1)
	}
	if shape.HasRight() {
		inner = shrink(inner, 0, 1, 0, 0)
	}
	p := t.opts.Padding
	pt := sizeOf(p[0], inner.height)
	pr := sizeOf(p[1], inner.width)
	pb := sizeOf(p[2], inner.height)
	pl := sizeOf(p[3], inner.width)
	if p[0].percent {
		pt = sizeOf(p[0], H)
	}
	if p[2].percent {
		pb = sizeOf(p[2], H)
	}
	if p[1].percent {
		pr = sizeOf(p[1], W)
	}
	if p[3].percent {
		pl = sizeOf(p[3], W)
	}
	inner = shrink(inner, pt, pr, pb, pl)
	if shape.HasLeft() {
		inner = shrink(inner, 0, 0, 0, 1)
	}
	t.scrollbarOutside = false
	if shape.HasRight() {
		inner = shrink(inner, 0, 1, 0, 0)
		t.scrollbarOutside = true
	}
	t.areaWidth = inner.width
	t.areaHeight = inner.height
	t.contentRect = inner

	main := inner
	t.previewOn = false
	if t.previewVisible() {
		po := t.previewOpts
		if po.alternative != nil {
			// threshold check
			var dim int
			if po.position == posUp || po.position == posDown {
				dim = inner.height
			} else {
				dim = inner.width
			}
			_ = dim
			if t.previewThresholdMet(inner) {
				alt := *po.alternative
				alt.command = po.command
				po = alt
			}
		}
		if !po.hidden && po.size.size > 0 || po.size.percent && po.size.size > 0 {
			t.layoutPreview(&main, po)
		}
	}
	t.mainRect = main

	// rows within main
	rows := main.height
	t.promptRow, t.infoRow = -1, -1
	t.inlineInfo = false
	used := 0
	hasInput := !t.inputHidden
	hasInfoLine := false
	if hasInput {
		used++
		switch t.infoStyle {
		case infoDefault, infoRight:
			hasInfoLine = true
		case infoHidden, infoInlineRight:
			hasInfoLine = t.separator != ""
		case infoInline:
			t.inlineInfo = true
		}
		if hasInfoLine {
			used++
		}
	}
	nHeader0 := 0
	nHeaderLines := 0
	if !t.headerHidden {
		nHeader0 = len(t.header0)
		nHeaderLines = t.opts.HeaderLines
		if t.headerLines != nil && len(t.headerLines) < nHeaderLines {
			nHeaderLines = len(t.headerLines)
		}
	}
	nFooter := 0
	if len(t.footer) > 0 {
		nFooter = len(t.footer) + 1
	}
	used += nHeader0 + nHeaderLines + nFooter
	listH := rows - used
	if listH < 0 {
		listH = 0
	}
	t.listHeight = listH
	top := main.top
	bottom := main.top + main.height - 1
	t.header0Rows = make([]int, nHeader0)
	t.headerLineRows = make([]int, nHeaderLines)
	t.footerRows = make([]int, len(t.footer))
	t.footerLineRow = -1
	switch t.layout {
	case layoutDefault:
		y := bottom
		if t.opts.HeaderFirst {
			for i := nHeader0 - 1; i >= 0; i-- {
				t.header0Rows[i] = y
				y--
			}
		}
		if hasInput {
			t.promptRow = y
			y--
			if hasInfoLine {
				t.infoRow = y
				y--
			}
		}
		if !t.opts.HeaderFirst {
			for i := nHeader0 - 1; i >= 0; i-- {
				t.header0Rows[i] = y
				y--
			}
		}
		for i := 0; i < nHeaderLines; i++ {
			t.headerLineRows[i] = y
			y--
		}
