		fy := top
		for i := 0; i < len(t.footer); i++ {
			t.footerRows[i] = fy
			fy++
		}
		if nFooter > 0 {
			t.footerLineRow = fy
		}
	case layoutReverse:
		y := top
		if t.opts.HeaderFirst {
			for i := 0; i < nHeader0; i++ {
				t.header0Rows[i] = y
				y++
			}
		}
		if hasInput {
			t.promptRow = y
			y++
			if hasInfoLine {
				t.infoRow = y
				y++
			}
		}
		if !t.opts.HeaderFirst {
			for i := 0; i < nHeader0; i++ {
				t.header0Rows[i] = y
				y++
			}
		}
		for i := 0; i < nHeaderLines; i++ {
			t.headerLineRows[i] = y
			y++
		}
		t.listTop = y
		t.listBottom = y + listH - 1
		fy := bottom
		for i := len(t.footer) - 1; i >= 0; i-- {
			t.footerRows[i] = fy
			fy--
		}
		if nFooter > 0 {
			t.footerLineRow = fy
		}
	case layoutReverseList:
		y := bottom
		if t.opts.HeaderFirst {
			for i := nHeader0 - 1; i >= 0; i-- {
				t.header0Rows[i] = y
				y--
			}
		}
		if hasInput {
			t.promptRow = y
			y--
			if hasInfoLine {
				t.infoRow = y
				y--
			}
		}
		if !t.opts.HeaderFirst {
			for i := nHeader0 - 1; i >= 0; i-- {
				t.header0Rows[i] = y
				y--
			}
		}
		yt := top
		for i := 0; i < len(t.footer); i++ {
			t.footerRows[i] = yt
			yt++
		}
		if nFooter > 0 {
			t.footerLineRow = yt
			yt++
		}
		for i := 0; i < nHeaderLines; i++ {
			t.headerLineRows[i] = yt
			yt++
		}
		t.listTop = yt
		t.listBottom = yt + listH - 1
	}
	if t.layout == layoutDefault && nFooter > 0 {
		// list is below the footer
	}
