func (t *Terminal) previewThresholdMet(inner rect) bool {
	po := t.previewOpts
	if po.alternative == nil {
		return false
	}
	var size int
	if po.position == posUp || po.position == posDown {
		size = t.previewSizeFor(po, inner.height, true)
	} else {
		size = t.previewSizeFor(po, inner.width, false)
	}
	return size < po.threshold
}

func previewBorderExtra(shape BorderShape, vertical bool) (int, int) {
	// returns (before, after) extra size on the split axis
	if vertical {
		// up/down: rows
		b, a := 0, 0
		if shape.HasTop() {
			b = 1
		}
		if shape.HasBottom() {
			a = 1
		}
		if shape == BorderLine {
			return 1, 0
		}
		return b, a
	}
	b, a := 0, 0
	if shape.HasLeft() {
		b = 2
	}
	if shape.HasRight() {
		a = 2
	}
	if shape == BorderLine {
		return 2, 0
	}
	return b, a
}

func (t *Terminal) previewSizeFor(po previewOpts, total int, vertical bool) int {
	if po.size.percent {
		return int(math.Floor(float64(total) * po.size.size / 100.0))
	}
	shape := po.border
	if shape == BorderUndefined {
		shape = BorderRounded
	}
	b, a := previewBorderExtra(shape, vertical)
	return int(po.size.size) + b + a
}

func (t *Terminal) layoutPreview(main *rect, po previewOpts) {
	shape := po.border
	if shape == BorderUndefined {
		shape = BorderRounded
	}
	vertical := po.position == posUp || po.position == posDown
	var total int
	if vertical {
		total = main.height
	} else {
		total = main.width
	}
	size := t.previewSizeFor(po, total, vertical)
	if size > total-1 {
		size = total - 1
	}
	if size < 0 {
		size = 0
	}
	var pr rect
	switch po.position {
	case posUp:
		pr = rect{main.top, main.left, main.width, size}
		main.top += size
		main.height -= size
	case posDown:
		pr = rect{main.top + main.height - size, main.left, main.width, size}
		main.height -= size
	case posLeft:
		pr = rect{main.top, main.left, size, main.height}
		main.left += size
		main.width -= size
	default:
		pr = rect{main.top, main.left + main.width - size, size, main.height}
		main.width -= size
	}
	t.previewOn = true
	t.previewShape = shape
	t.previewBorderRect = pr
	// line border: the line is drawn adjacent to the list
	if shape == BorderLine {
		switch po.position {
		case posUp:
			shape = BorderBottom
		case posDown:
			shape = BorderTop
		case posLeft:
			shape = BorderRight
		default:
			shape = BorderLeft
		}
		t.previewShape = shape
	}
	content := pr
	if shape.HasTop() {
		content = shrink(content, 1, 0, 0, 0)
	}
	if shape.HasBottom() {
		content = shrink(content, 0, 0, 1, 0)
	}
	if shape.HasLeft() {
		content = shrink(content, 0, 0, 0, 2)
	}
	if shape.HasRight() {
		content = shrink(content, 0, 2, 0, 0)
	}
	t.previewRect = content
	t.previewPos = po.position
	t.previewInfo = po.info
}
