func pick(c ColorAttr, fallbacks ...ColorAttr) ColorAttr {
	res := c
	for _, f := range fallbacks {
		if res.Color == colUndefined {
			res.Color = f.Color
		}
		if res.Attr == tAttrUndefined {
			res.Attr = f.Attr
		}
	}
	if res.Color == colUndefined {
		res.Color = colDefault
	}
	if res.Attr == tAttrUndefined {
		res.Attr = 0
	}
	return res
}

func cleanAttr(a tAttr) tAttr {
	return a &^ (tAttrUndefined | tAttrRegular | tAttrStrip)
}

func (t *Terminal) buildPalette() palette {
	th := t.theme
	p := palette{}
	undef := ColorAttr{colUndefined, tAttrUndefined}
	bg := pick(th.ListBg, th.Bg).Color
	darkBg := pick(th.DarkBg).Color
	p.bg = bg
	p.darkBg = darkBg
	bold := tAttr(0)
	if t.opts.Bold {
		bold = tAttrBold
	}
	mk := func(c ColorAttr, b tColor, extra tAttr) style {
		return style{c.Color, b, cleanAttr(c.Attr) | extra}
	}
	fg := pick(th.ListFg, th.Fg)
	p.normal = mk(fg, bg, 0)
	cur := pick(th.Current, fg)
	p.current = mk(cur, darkBg, bold)
	match := pick(th.Match)
	p.match = mk(match, bg, 0)
	p.currentMatch = mk(pick(th.CurrentMatch, match), darkBg, bold)
	p.cursor = mk(pick(th.Cursor), darkBg, bold)
	gutterC := th.Gutter
	if gutterC.Color == colUndefined {
		gutterC = ColorAttr{darkBg, tAttrUndefined}
	}
	p.gutter = mk(pick(gutterC), bg, 0)
	p.marker = mk(pick(th.Marker), bg, 0)
	p.currentMarker = mk(pick(th.Marker), darkBg, 0)
	selFg := pick(th.SelectedFg, fg)
	selBg := pick(th.SelectedBg, ColorAttr{bg, tAttrUndefined}).Color
	p.selected = mk(selFg, selBg, 0)
	p.selectedMatch = mk(pick(th.SelectedMatch, match), selBg, 0)
	inputBg := pick(th.InputBg, ColorAttr{bg, tAttrUndefined}).Color
	p.prompt = mk(pick(th.Prompt), inputBg, bold)
	p.query = mk(pick(th.Input, fg), inputBg, bold)
	p.ghost = mk(pick(th.Ghost, ColorAttr{colUndefined, tAttrDim}), inputBg, 0)
	p.disabled = mk(pick(th.Disabled, th.Input, fg), inputBg, bold)
	p.info = mk(pick(th.Info), bg, 0)
	p.spinner = mk(pick(th.Spinner), bg, bold)
	border := pick(th.Border)
	listBorder := pick(th.ListBorder, border)
	p.separator = mk(pick(th.Separator, listBorder), bg, 0)
	p.scrollbar = mk(pick(th.Scrollbar, listBorder), bg, 0)
	p.header = mk(pick(th.Header), pick(th.HeaderBg, ColorAttr{bg, tAttrUndefined}).Color, 0)
	p.footer = mk(pick(th.Footer, th.Header), pick(th.FooterBg, ColorAttr{bg, tAttrUndefined}).Color, 0)
	mainBg := pick(th.Bg).Color
	p.border = mk(border, mainBg, 0)
	p.label = mk(pick(th.BorderLabel), mainBg, 0)
	p.listBorder = mk(listBorder, bg, 0)
	p.listLabel = mk(pick(th.ListLabel, th.BorderLabel), bg, 0)
	prevBg := pick(th.PreviewBg, th.Bg).Color
	p.preview = mk(pick(th.PreviewFg, th.Fg), prevBg, 0)
	pb := pick(th.PreviewBorder, border)
	p.previewBorder = mk(pb, prevBg, 0)
	p.previewLabel = mk(pick(th.PreviewLabel, th.BorderLabel), prevBg, 0)
	p.previewScrollbar = mk(pick(th.PreviewScrollbar, pb), prevBg, 0)
	p.nomatch = mk(pick(th.Nomatch, ColorAttr{colUndefined, tAttrDim}), bg, 0)
	return p
}

// putString writes a string at (y, x) clipped at maxX (exclusive). Returns new x.
func (t *Terminal) putString(y, x, maxX int, str string, st style) int {
	s := t.screen
	for _, g := range splitGraphemes(str) {
		w := graphemeWidth(g)
		if g == "\t" {
			g = " "
			w = 1
		}
		if w == 0 {
			r, _ := utf8.DecodeRuneInString(g)
			if r < 0x20 || r == 0x7f {
				continue
			}
			continue
		}
		if x+w > maxX {
			break
		}
		s.setCell(y, x, g, w, st.fg, st.bg, st.attr)
		x += w
	}
	return x
}

func (t *Terminal) fillRow(y, x, maxX int, st style) {
	for ; x < maxX; x++ {
		t.screen.setCell(y, x, " ", 1, st.fg, st.bg, st.attr)
	}
}

func (t *Terminal) fillRect(r rect, st style) {
	for y := r.top; y < r.top+r.height; y++ {
		t.fillRow(y, r.left, r.left+r.width, st)
	}
}

func (t *Terminal) drawBorder(r rect, shape BorderShape, st style) {
	if r.width <= 0 || r.height <= 0 || !shape.Visible() {
		return
	}
	bc := getBorderChars(shape, t.opts.Unicode)
	s := t.screen
	top, bottom := r.top, r.top+r.height-1
	left, right := r.left, r.left+r.width-1
	hasT, hasB, hasL, hasR := shape.HasTop(), shape.HasBottom(), shape.HasLeft(), shape.HasRight()
	hw := stringWidth(bc.top)
	if hasT {
		for x := left; x <= right; x += hw {
			s.setCell(top, x, bc.top, hw, st.fg, st.bg, st.attr)
		}
	}
	if hasB {
		for x := left; x <= right; x += hw {
			s.setCell(bottom, x, bc.bottom, hw, st.fg, st.bg, st.attr)
		}
	}
	if hasL {
		for y := top; y <= bottom; y++ {
			s.setCell(y, left, bc.left, 1, st.fg, st.bg, st.attr)
		}
	}
	if hasR {
		for y := top; y <= bottom; y++ {
			s.setCell(y, right, bc.right, 1, st.fg, st.bg, st.attr)
		}
	}
	if hasT && hasL {
		s.setCell(top, left, bc.topLeft, 1, st.fg, st.bg, st.attr)
	}
	if hasT && hasR {
		s.setCell(top, right, bc.topRight, 1, st.fg, st.bg, st.attr)
	}
	if hasB && hasL {
		s.setCell(bottom, left, bc.bottomLeft, 1, st.fg, st.bg, st.attr)
	}
	if hasB && hasR {
		s.setCell(bottom, right, bc.bottomRight, 1, st.fg, st.bg, st.attr)
	}
}

func (t *Terminal) drawLabel(r rect, shape BorderShape, label string, lo labelOpts, st style) {
	if label == "" || r.width <= 0 || r.height <= 0 {
		return
	}
	switch shape {
	case BorderHorizontal, BorderTop, BorderBottom, BorderRounded, BorderSharp, BorderBold, BorderBlock, BorderThinBlock, BorderDouble:
	default:
		return
	}
	text, offsets, _ := extractColor(label, nil, nil)
	length := stringWidth(text)
	var col int
	if lo.column == 0 {
		col = max(0, (r.width-length)/2)
	} else if lo.column < 0 {
		col = max(0, r.width+lo.column+1-length)
	} else {
		col = min(lo.column-1, r.width-length)
	}
	if col < 0 {
		col = 0
	}
	row := r.top
	if shape == BorderBottom || lo.bottom {
		row = r.top + r.height - 1
	}
	t.putAnsiText(row, r.left+col, r.left+r.width, text, offsets, st)
}

// putAnsiText prints text with ansi color offsets on top of the base style
func (t *Terminal) putAnsiText(y, x, maxX int, text string, offsets *[]ansiOffset, base style) int {
	if offsets == nil {
		return t.putString(y, x, maxX, text, base)
	}
	runes := []rune(text)
	idx := 0
	for _, off := range *offsets {
		b, e := int(off.offset[0]), int(off.offset[1])
		if b > idx {
			x = t.putString(y, x, maxX, string(runes[idx:min(b, len(runes))]), base)
		}
		st := mergeAnsi(base, off.color)
		if e > len(runes) {
			e = len(runes)
		}
		if b < e {
			x = t.putString(y, x, maxX, string(runes[b:e]), st)
		}
		idx = e
	}
	if idx < len(runes) {
		x = t.putString(y, x, maxX, string(runes[idx:]), base)
	}
	return x
}

func mergeAnsi(base style, a ansiState) style {
	st := base
	if a.fg != -1 {
		st.fg = a.fg
	}
	if a.bg != -1 {
		st.bg = a.bg
	}
	st.attr = base.attr | a.attr
	return st
}

func (t *Terminal) render() {
	if t.screen == nil {
		return
	}
	s := t.screen
	t.computeLayout()
	p := t.buildPalette()
	t.pal = p
	s.clearCells()
	bgStyle := style{colDefault, p.bg, 0}
	mainBg := style{colDefault, p.border.bg, 0}
	if mainBg.bg != colDefault {
		t.fillRect(rect{0, 0, s.width, s.height}, mainBg)
	}
	if p.bg != colDefault {
		t.fillRect(t.mainRect, bgStyle)
	}
	// border
	t.drawBorder(t.borderRect, t.mainBorder, p.border)
	t.drawLabel(t.borderRect, t.mainBorder, t.borderLabel, t.opts.BorderLabel, p.label)

	t.renderList(p)
	t.renderHeaders(p)
	t.renderFooter(p)
	t.renderInfoAndPrompt(p)
	if t.previewOn {
		t.renderPreview(p)
	}
	s.flush()
}

func (t *Terminal) renderFooter(p palette) {
	m := t.mainRect
	for i, line := range t.footer {
		y := t.footerRows[i]
		text, offsets, _ := extractColor(line, nil, nil)
		t.putAnsiText(y, m.left+2, m.left+m.width, expandTabs(text, t.opts.Tabstop), offsets, p.footer)
	}
	if t.footerLineRow >= 0 {
		w := m.width
		if t.scrollbarOutside {
			w++
		}
		bc := "─"
		if !t.opts.Unicode {
			bc = "-"
		}
		for x := m.left; x < m.left+w; x++ {
			t.screen.setCell(t.footerLineRow, x, bc, 1, p.border.fg, p.border.bg, p.border.attr)
		}
	}
}

func expandTabs(s string, tabstop int) string {
	if !strings.Contains(s, "\t") {
		return s
	}
	var sb strings.Builder
	col := 0
	for _, g := range splitGraphemes(s) {
		if g == "\t" {
			n := tabstop - col%tabstop
			sb.WriteString(strings.Repeat(" ", n))
			col += n
			continue
		}
		sb.WriteString(g)
		col += graphemeWidth(g)
	}
	return sb.String()
}

func (t *Terminal) renderHeaders(p palette) {
	m := t.mainRect
	maxX := m.left + m.width
	if !t.scrollbarOutside {
		maxX--
	}
	for i, line := range t.header0 {
		if i >= len(t.header0Rows) {
			break
		}
		y := t.header0Rows[i]
		text, offsets, _ := extractColor(line, nil, nil)
		text = expandTabs(text, t.opts.Tabstop)
		t.putAnsiText(y, m.left+t.pointerLen+t.markerLen, maxX, text, offsets, p.header)
	}
	for i := range t.headerLineRows {
		if i >= len(t.headerLines) {
			break
		}
		y := t.headerLineRows[i]
		line := t.headerLines[i]
		var text string
		var offsets *[]ansiOffset
		if t.opts.Ansi {
			text, offsets, _ = extractColor(line, nil, nil)
		} else {
			text = line
		}
		text = expandTabs(text, t.opts.Tabstop)
		t.putAnsiText(y, m.left+t.pointerLen+t.markerLen, maxX, text, offsets, p.header)
	}
}

func (t *Terminal) listRowY(i int) int {
	// i: index from offset (0-based)
	if t.layout == layoutDefault {
		return t.listBottom - i*(1+t.gap)
	}
	return t.listTop + i*(1+t.gap)
}

func (t *Terminal) renderList(p palette) {
	m := t.mainRect
	count := len(t.results)
	maxItems := t.maxItems()
	textMaxX := m.left + m.width
	showScrollbar := t.scrollbar != "" && count > maxItems && maxItems > 0
	if !t.scrollbarOutside && t.scrollbar != "" {
		textMaxX--
	}
	for i := 0; i < maxItems; i++ {
		idx := t.offset + i
		if idx >= count {
			break
		}
		y := t.listRowY(i)
		if y < t.listTop || y > t.listBottom {
			break
		}
		t.renderItem(y, m.left, textMaxX, t.results[idx], idx == t.cy, p)
	}
	if showScrollbar {
		barLen, barStart := t.scrollbarGeometry(count, maxItems)
		x := m.left + m.width - 1
		if t.scrollbarOutside {
			x = m.left + m.width
		}
		for i := 0; i < t.listHeight; i++ {
			if i >= barStart && i < barStart+barLen {
				var y int
				if t.layout == layoutDefault {
					y = t.listBottom - i
				} else {
					y = t.listTop + i
				}
				t.screen.setCell(y, x, t.scrollbar, 1, p.scrollbar.fg, p.scrollbar.bg, p.scrollbar.attr)
			}
		}
	}
}

func (t *Terminal) scrollbarGeometry(total, height int) (int, int) {
	barLength := max(1, height*height/total)
	maxOffset := total - height
	barStart := 0
	if maxOffset > 0 {
		barStart = int(float64(height-barLength) * float64(t.offset) / float64(maxOffset))
		barStart = min(height-barLength, barStart)
	}
	_ = strconv.Itoa
	return barLength, barStart
}

func (t *Terminal) renderItem(y, left, maxX int, r Result, current bool, p palette) {
	item := r.item
	selected := t.isSelected(item)
	x := left
	if current {
		x = t.putString(y, x, x+t.pointerLen, padRight(t.pointer, t.pointerLen), p.cursor)
		if selected {
			x = t.putString(y, x, x+t.markerLen, padRight(t.marker, t.markerLen), p.currentMarker)
		} else {
			x = t.putString(y, x, x+t.markerLen, t.markerEmpty, style{p.current.fg, p.darkBg, 0})
		}
	} else {
		g := t.gutter
		gw := stringWidth(g)
		x = t.putString(y, x, x+gw, g, p.gutter)
		if t.pointerLen > gw {
			x = t.putString(y, x, left+t.pointerLen, strings.Repeat(" ", t.pointerLen-gw), style{colDefault, p.bg, 0})
		}
		x = left + t.pointerLen
		if selected {
			x = t.putString(y, x, x+t.markerLen, padRight(t.marker, t.markerLen), p.marker)
		} else {
			x = t.putString(y, x, x+t.markerLen, t.markerEmpty, style{colDefault, p.bg, 0})
		}
	}
	base := p.normal
	hl := p.match
	if current {
		base = p.current
		hl = p.currentMatch
	} else if selected {
		base = p.selected
		hl = p.selectedMatch
	}
	end := t.printHighlighted(y, x, maxX, item, base, hl, current)
	if current && t.cursorLine {
		t.fillRow(y, end, maxX, style{base.fg, p.darkBg, 0})
	}
}

func padRight(s string, w int) string {
	sw := stringWidth(s)
	if sw < w {
		return s + strings.Repeat(" ", w-sw)
	}
	return s
}

type charStyle struct {
	r  rune
	st style
}

// printHighlighted renders the item text with match highlights; returns end x
func (t *Terminal) printHighlighted(y, x, maxX int, item *Item, base, hl style, current bool) int {
	runes := item.text.ToRunes()
	// compute match positions
	var posSet map[int]bool
	if t.lastPattern != nil && !t.lastPattern.IsEmpty() {
		_, _, pos := t.lastPattern.MatchItem(item, true)
		if pos != nil {
			posSet = make(map[int]bool, len(*pos))
			for _, p := range *pos {
				posSet[p] = true
			}
		}
	}
	// colors per rune
	styles := make([]style, len(runes))
	for i := range styles {
		styles[i] = base
	}
	if item.colors != nil {
		for _, off := range *item.colors {
			b, e := int(off.offset[0]), int(off.offset[1])
			for i := b; i < e && i < len(runes); i++ {
				st := base
				if current {
					st = mergeAnsiCurrent(base, off.color)
				} else {
					st = mergeAnsi(base, off.color)
				}
				styles[i] = st
			}
		}
	}
	maxe := 0
	for i := range runes {
		if posSet[i] {
			if item.colors != nil {
				styles[i] = style{hl.fg, styles[i].bg, styles[i].attr | hl.attr}
			} else {
				styles[i] = hl
			}
			if i+1 > maxe {
				maxe = i + 1
			}
		}
	}
	// expand tabs into display cells
	type cellT struct {
		g  string
		w  int
		st style
		ri int
	}
	cells := []cellT{}
	col := 0
	gs := splitGraphemesRunes(runes)
	ri := 0
	for _, g := range gs {
		n := utf8.RuneCountInString(g)
		st := styles[min(ri, len(styles)-1)]
		if g == "\t" {
			w := t.opts.Tabstop - col%t.opts.Tabstop
			for k := 0; k < w; k++ {
				cells = append(cells, cellT{" ", 1, st, ri})
			}
			col += w
		} else {
			w := graphemeWidth(g)
			r0, _ := utf8.DecodeRuneInString(g)
			if r0 < 0x20 || r0 == 0x7f {
				// control characters
				g = "?"
				w = 1
				if r0 == '\n' {
					g = " "
				}
			}
			if w > 0 {
				cells = append(cells, cellT{g, w, st, ri})
				col += w
			}
		}
		ri += n
	}
	avail := maxX - x
	if avail <= 0 {
		return x
	}
	totalW := 0
	for _, c := range cells {
		totalW += c.w
	}
	ell := t.ellipsis
	ellW := stringWidth(ell)
	start, end := 0, len(cells)
	leftEll, rightEll := false, false
	widthOf := func(a, b int) int {
		w := 0
		for i := a; i < b; i++ {
			w += cells[i].w
		}
		return w
	}
	if totalW > avail {
		// maxe in cell index
		maxeCell := 0
		if maxe > 0 {
			for i, c := range cells {
				if c.ri < maxe {
					maxeCell = i + 1
				}
			}
		}
		if t.hscroll && maxe > 0 {
			maxeCell = min(len(cells), maxeCell+t.opts.HscrollOff)
		}
		if !t.hscroll || maxe == 0 && !t.opts.KeepRight {
			// trim right
			w := 0
			end = 0
			for end < len(cells) && w+cells[end].w <= avail-ellW {
				w += cells[end].w
				end++
			}
			rightEll = true
		} else if t.opts.KeepRight && maxe == 0 {
			w := 0
			start = len(cells)
			for start > 0 && w+cells[start-1].w <= avail-ellW {
				w += cells[start-1].w
				start--
			}
			leftEll = true
		} else if widthOf(0, maxeCell) <= avail-ellW {
			w := 0
			end = 0
			for end < len(cells) && w+cells[end].w <= avail-ellW {
				w += cells[end].w
				end++
			}
			rightEll = true
		} else {
			if widthOf(maxeCell, len(cells)) > ellW {
				end = maxeCell
				rightEll = true
			}
			target := avail - ellW
			if rightEll {
				target -= ellW
			}
			w := 0
			start = end
			for start > 0 && w+cells[start-1].w <= target {
				w += cells[start-1].w
				start--
			}
			leftEll = true
		}
	}
	s := t.screen
	if leftEll {
		st := base
		if start < len(cells) {
			st = style{base.fg, cells[start].st.bg, base.attr}
		}
		x = t.putString(y, x, maxX, ell, st)
	}
	for i := start; i < end; i++ {
		c := cells[i]
		if x+c.w > maxX {
			break
		}
		s.setCell(y, x, c.g, c.w, c.st.fg, c.st.bg, c.st.attr)
		x += c.w
	}
	if rightEll {
		st := base
		if end > 0 && end <= len(cells) {
			st = style{base.fg, cells[end-1].st.bg, base.attr}
		}
		x = t.putString(y, x, maxX, ell, st)
	}
	return x
}

func mergeAnsiCurrent(base style, a ansiState) style {
	st := base
	if a.fg != -1 {
		st.fg = a.fg
	}
	if a.bg != -1 {
		st.bg = a.bg
	}
	st.attr = base.attr | a.attr
	return st
}

func splitGraphemesRunes(runes []rune) []string {
	return splitGraphemes(string(runes))
}

func (t *Terminal) infoText() string {
	output := strconv.Itoa(len(t.results)) + "/" + strconv.Itoa(t.total)
	if t.toggleSort {
		if t.sort {
			output += " +S"
		} else {
			output += " -S"
		}
	}
	if t.multi > 0 {
		if t.multi == maxMulti {
			output += " (" + strconv.Itoa(len(t.selected)) + ")"
		} else {
			output += " (" + strconv.Itoa(len(t.selected)) + "/" + strconv.Itoa(t.multi) + ")"
		}
	}
	return output
}

func (t *Terminal) promptParts() (string, string) {
	trimmed := strings.TrimRight(t.prompt, " ")
	return trimmed, t.prompt[len(trimmed):]
}

func (t *Terminal) renderInfoAndPrompt(p palette) {
	m := t.mainRect
	s := t.screen
	maxX := m.left + m.width
	sepMaxX := maxX
	if !t.scrollbarOutside {
		sepMaxX--
	}
	// prompt
	if t.promptRow >= 0 {
		y := t.promptRow
		x := m.left
		ptext, poff, _ := extractColor(t.prompt, nil, nil)
		trimmed := strings.TrimRight(ptext, " ")
		if poff != nil {
			x = t.putAnsiText(y, x, maxX, ptext, poff, p.prompt)
		} else {
			x = t.putString(y, x, maxX, trimmed, p.prompt)
			x = t.putString(y, x, maxX, ptext[len(trimmed):], style{p.prompt.fg, p.prompt.bg, p.prompt.attr &^ tAttrBold})
		}
		promptEnd := x
		qst := p.query
		if t.disabled {
			qst = p.disabled
		}
		qstr := string(t.input)
		// handle horizontal scroll of query
		avail := maxX - promptEnd
		before := string(t.input[:t.cx])
		bw := stringWidth(before)
		qrunes := t.input
		qstart := 0
		if bw >= avail && avail > 0 {
			// scroll so that the cursor is visible
			w := 0
			qstart = t.cx
			for qstart > 0 && w+runeWidth(qrunes[qstart-1]) < avail {
				w += runeWidth(qrunes[qstart-1])
				qstart--
			}
			qstr = string(qrunes[qstart:])
			before = string(qrunes[qstart:t.cx])
		}
		if len(t.input) == 0 && t.ghost != "" {
			t.putString(y, x, maxX, t.ghost, p.ghost)
		} else {
			x = t.putString(y, x, maxX, qstr, qst)
		}
		s.cursorY = y
		s.cursorX = min(promptEnd+stringWidth(before), maxX-1)
		s.showCursor = true
		queryEnd := promptEnd + stringWidth(qstr)
		if len(t.input) == 0 {
			queryEnd = promptEnd
		}
		if t.inlineInfo {
			ix := queryEnd + 1
			prefix := t.infoPrefix
			if prefix == "" {
				prefix = defaultInfoPrefix
			}
			if ix < maxX {
				ix = t.putString(y, ix, maxX, prefix, p.prompt.withAttr(0).withFg(p.info.fg))
				ix = t.putString(y, ix, maxX, t.infoText(), p.info)
				if t.reading {
					ix = t.putString(y, ix, maxX, " "+t.spinner[t.spinIdx%len(t.spinner)], p.spinner)
				}
				if t.separator != "" && ix < sepMaxX {
					ix = t.putString(y, ix, sepMaxX, " ", p.separator)
					t.drawSeparator(y, ix, sepMaxX, p)
				}
			}
		} else if t.infoStyle == infoInlineRight {
			info := t.infoPrefix + t.infoText()
			if t.reading {
				info = t.spinner[t.spinIdx%len(t.spinner)] + " " + info
			}
			iw := stringWidth(info)
			ix := sepMaxX - iw
			if ix > queryEnd {
				pre := t.infoPrefix
				ix = t.putString(y, ix, sepMaxX, pre, p.info)
				t.putString(y, ix, sepMaxX, t.infoText(), p.info)
			}
		}
	}
	if t.infoRow >= 0 {
		y := t.infoRow
		x := m.left
		switch t.infoStyle {
		case infoDefault:
			if t.reading {
				t.putString(y, x, maxX, t.spinner[t.spinIdx%len(t.spinner)], p.spinner)
			}
			x += 2
			x = t.putString(y, x, sepMaxX, t.infoText(), p.info)
			if t.separator != "" && x < sepMaxX {
				x = t.putString(y, x, sepMaxX, " ", p.separator)
				t.drawSeparator(y, x, sepMaxX, p)
			}
		case infoRight:
			info := t.infoText()
			iw := stringWidth(info)
			// separator then space then info
			sepEnd := sepMaxX - iw - 1
			if t.reading {
				sepEnd -= 2
			}
			if t.separator != "" {
				t.drawSeparator(y, x, sepEnd, p)
			}
			ix := sepEnd + 1
			if t.reading {
				ix = t.putString(y, ix, sepMaxX, t.spinner[t.spinIdx%len(t.spinner)]+" ", p.spinner)
			}
			t.putString(y, ix, sepMaxX, info, p.info)
		default:
			t.drawSeparator(y, x, sepMaxX, p)
		}
	}
}

func (st style) withAttr(a tAttr) style {
	st.attr = a
	return st
}

func (st style) withFg(c tColor) style {
	st.fg = c
	return st
}

func (t *Terminal) drawSeparator(y, x, maxX int, p palette) {
	if t.separator == "" {
		return
	}
	text, offsets, _ := extractColor(t.separator, nil, nil)
	sw := stringWidth(text)
	if sw == 0 {
		return
	}
	for x < maxX {
		nx := t.putAnsiText(y, x, maxX, text, offsets, p.separator)
		if nx == x {
			break
		}
		x = nx
	}
}
EOF
echo ok"}

