	for i := 0; i < offset && i < total; i++ {
		_, _, state = extractColor(lines[i], state, nil)
	}
	headerLines := t.previewOpts.headerLines
	y := r.top
	drawLine := func(line string) {
		text, offsets, newState := extractColor(line, state, nil)
		state = newState
		text = expandTabs(text, t.opts.Tabstop)
		t.putAnsiText(y, r.left, r.left+r.width, text, offsets, p.preview)
		y++
	}
