			}
		}
		if t.previewScrollbar != "" {
			x := r.left + r.width
			if !shape.HasRight() {
				x = r.left + r.width - 1
			}
			barLen := max(1, viewH*viewH/total)
			maxOffset := total - viewH
			barStart := 0
			if maxOffset > 0 {
				barStart = min(viewH-barLen, int(float64(viewH-barLen)*float64(offset)/float64(maxOffset)))
			}
