func (t *Terminal) putWrapped(y *int, r rect, text string, offsets *[]ansiOffset, base style) {
	runes := []rune(text)
	styles := make([]style, len(runes))
	for i := range styles {
		styles[i] = base
	}
	if offsets != nil {
		for _, off := range *offsets {
			for i := int(off.offset[0]); i < int(off.offset[1]) && i < len(runes); i++ {
				styles[i] = mergeAnsi(base, off.color)
			}
		}
	}
	x := r.left
	if len(runes) == 0 {
		*y++
		return
	}
	for i, ru := range runes {
		w := runeWidth(ru)
		if x+w > r.left+r.width {
			*y++
			x = r.left
			if *y >= r.top+r.height {
				return
			}
		}
		if w > 0 {
			t.screen.setCell(*y, x, string(ru), w, styles[i].fg, styles[i].bg, styles[i].attr)
			x += w
		}
