// stubs for mouse and jump
func (t *Terminal) handleMouse(ev Event) {
	me := ev.Mouse
	if me == nil || !me.Down {
		return
	}
	y := me.Y
	if t.previewOn {
		pr := t.previewBorderRect
		if me.X >= pr.left && me.X < pr.left+pr.width && y >= pr.top && y < pr.top+pr.height {
			return
		}
	}
	if y >= t.listTop && y <= t.listBottom {
		var i int
		if t.layout == layoutDefault {
			i = t.listBottom - y
		} else {
			i = y - t.listTop
		}
		if t.gap > 0 {
			if i%(1+t.gap) != 0 {
				return
			}
			i /= 1 + t.gap
		}
		idx := t.offset + i
		if idx < len(t.results) {
			if me.Left {
				now := time.Now()
				if idx == t.lastClickIdx && now.Sub(t.lastClickTime) < 500*time.Millisecond {
					t.lastClickIdx = -1
					t.cy = idx
					t.handleEvent(DoubleClick.AsEvent())
					return
				}
				t.lastClickIdx = idx
				t.lastClickTime = now
				t.cy = idx
				t.constrain()
			} else {
				t.cy = idx
				t.handleEvent(RightClick.AsEvent())
			}
		}
	}
