func (t *Terminal) handleJump(ev Event) {
	mode := t.jumping
	t.jumping = 0
	if ev.Type != Rune {
		t.triggerEvent(JumpCancel.AsEvent())
		return
	}
	idx := strings.IndexRune(t.opts.JumpLabels, ev.Char)
	if idx < 0 || t.offset+idx >= len(t.results) || idx >= t.maxItems() {
		t.triggerEvent(JumpCancel.AsEvent())
		return
	}
	t.cy = t.offset + idx
	t.constrain()
	if mode == 2 {
		t.accept(false)
		return
	}
	t.triggerEvent(Jump.AsEvent())
}
