	cur := t.currentItem()
	// skip when there's no match unless the template has {q} or {+}
	if cur == nil && !strings.Contains(template, "{q") && !hasPlusFlag(template) && !strings.Contains(template, "{*") {
		if t.previewer != nil {
			t.previewer.kill()
		}
