func (t *Terminal) evalPreviewScroll() int {
	spec := t.previewOpts.scroll
	if spec == "" {
		return 0
	}
	// +SCROLL[OFFSETS][/DENOM]
	base := 0
	rest := spec
	if strings.HasPrefix(rest, "+{") {
		end := strings.Index(rest, "}")
		expr := rest[2:end]
		rest = rest[end+1:]
		if expr == "n" {
			if cur := t.currentItem(); cur != nil {
				base = int(cur.index)
			}
		} else if cur := t.currentItem(); cur != nil {
			n, _ := strconv.Atoi(expr)
			tokens := Tokenize(t.itemText(cur), t.opts.Delimiter)
			trans := Transform(tokens, []Range{newRange(n, n)})
			if len(trans) > 0 {
				v := strings.TrimSpace(trans[0].text.ToString())
				num := ""
				for _, c := range v {
					if c >= '0' && c <= '9' || c == '-' && num == "" {
						num += string(c)
					} else {
						break
					}
				}
				base, _ = strconv.Atoi(num)
			}
		}
	} else if strings.HasPrefix(rest, "+") {
		i := 1
		for i < len(rest) && rest[i] >= '0' && rest[i] <= '9' {
			i++
		}
		base, _ = strconv.Atoi(rest[1:i])
		rest = rest[i:]
	}
	denom := 0
	if idx := strings.Index(rest, "/"); idx >= 0 {
		d := rest[idx+1:]
		denom, _ = strconv.Atoi(d)
		if idx > 0 && rest[idx-1] == '-' {
			denom = -denom
			rest = rest[:idx-1]
		} else {
			rest = rest[:idx]
		}
	}
	// offsets
	for len(rest) > 0 {
		sign := 1
		if rest[0] == '-' {
			sign = -1
		}
		i := 1
		for i < len(rest) && rest[i] >= '0' && rest[i] <= '9' {
			i++
		}
		n, _ := strconv.Atoi(rest[1:i])
		base += sign * n
		rest = rest[i:]
	}
	offset := base - 1
	if denom != 0 {
		h := t.previewHeight() - t.previewOpts.headerLines
		offset -= h / denom
		_ = h
	}
	if offset < 0 {
		offset = 0
	}
	return offset
}

