func resolveLineShape(shape BorderShape, pos windowPosition) BorderShape {
	if shape == BorderLine {
		switch pos {
		case posUp:
			return BorderBottom
		case posDown:
			return BorderTop
		case posLeft:
			return BorderRight
		default:
			return BorderLeft
		}
	}
	return shape
}

func (t *Terminal) previewSizeFor(po previewOpts, total int, vertical bool) int {
	if po.size.percent {
