	if !t.scrollbarOutside && t.scrollbar != "" {
		w--
	}
	return w
}

// itemLines splits the item into display lines (for multi-line items)
func (t *Terminal) itemLineCount(item *Item) int {
	n := 1
	if t.opts.MultiLine && t.opts.ReadZero {
		l := item.text.Length()
		for i := 0; i < l; i++ {
			if item.text.Get(i) == '\\n' {
				n++
			}
		}
	}
	if t.wrap {
		total := 0
		avail := t.textAvail()
		signW := stringWidth(t.wrapSign())
		for _, line := range t.splitItemLines(item) {
			total += wrapCount(line, avail, signW, t.opts.Tabstop)
		}
		return max(1, total)
	}
	return n
}

func (t *Terminal) wrapSign() string {
	if t.opts.WrapSign != nil {
		return *t.opts.WrapSign
	}
	if t.opts.Unicode {
		return "↳ "
	}
	return "> "
}

func wrapCount(line []rune, avail int, signW int, tabstop int) int {
	if avail <= 0 {
		return 1
	}
	rows := 1
	w := 0
	limit := avail
	for _, r := range line {
		cw := runeWidth(r)
		if r == '\\t' {
			cw = tabstop - w%tabstop
		}
		if w+cw > limit {
			rows++
			w = 0
			limit = avail - signW
			if limit <= 0 {
				limit = 1
			}
		}
		w += cw
	}
	return rows
}

func (t *Terminal) splitItemLines(item *Item) [][]rune {
	runes := item.text.ToRunes()
	if !(t.opts.MultiLine && t.opts.ReadZero) {
		return [][]rune{runes}
	}
	lines := [][]rune{}
	start := 0
	for i, r := range runes {
		if r == '\\n' {
			lines = append(lines, runes[start:i])
			start = i + 1
		}
	}
	lines = append(lines, runes[start:])
	return lines
}

func (t *Terminal) renderList(p palette) {
	m := t.mainRect
	count := len(t.results)
	textMaxX := m.left + m.width
	if !t.scrollbarOutside && t.scrollbar != "" {
		textMaxX--
	}
	rowsLeft := t.listHeight
	y := t.listBottom
	dir := -1
	if t.layout != layoutDefault {
		y = t.listTop
		dir = 1
	}
	totalRows := 0
	variable := t.variableHeights()
	for idx := t.offset; idx < count && rowsLeft > 0; idx++ {
		r := t.results[idx]
		h := 1
		if variable {
			h = t.itemLineCount(r.item)
		}
		// rows of this block
		blockRows := make([]int, h)
		if dir < 0 {
			for k := 0; k < h; k++ {
				blockRows[k] = y - (h - 1) + k
			}
		} else {
			for k := 0; k < h; k++ {
				blockRows[k] = y + k
			}
		}
		t.renderItemBlock(blockRows, m.left, textMaxX, r, idx == t.cy, p)
		used := min(h, rowsLeft)
		rowsLeft -= used
		y += dir * h
		// gap
		for g := 0; g < t.gap && rowsLeft > 0; g++ {
			t.renderGapRow(y, m.left, textMaxX, g == 0, p)
			y += dir
			rowsLeft--
		}
	}
	_ = totalRows
	t.renderScrollbar(p, count)
}

func (t *Terminal) renderGapRow(y, left, maxX int, first bool, p palette) {
	if y < t.listTop || y > t.listBottom {
		return
	}
	g := t.gutter
	t.putString(y, left, left+stringWidth(g), g, p.gutter)
	if !first {
		return
	}
	line := ""
	if t.opts.GapLine == nil {
		if t.opts.Unicode {
			line = "┈"
		} else {
			line = "-"
		}
	} else if *t.opts.GapLine == "\\x00default" {
		if t.opts.Unicode {
			line = "┈"
		} else {
			line = "-"
		}
	} else {
		line = *t.opts.GapLine
	}
	if line == "" {
		return
	}
	x := left + t.pointerLen + t.markerLen
	text, offsets, _ := extractColor(line, nil, nil)
	if stringWidth(text) == 0 {
		return
	}
	for x < maxX {
		nx := t.putAnsiText(y, x, maxX, text, offsets, p.separator)
		if nx == x {
			break
		}
		x = nx
	}
}

func (t *Terminal) renderScrollbar(p palette, count int) {
	m := t.mainRect
	if t.scrollbar == "" || t.listHeight <= 0 {
		return
	}
	var total, viewH, off int
	if t.variableHeights() || t.gap > 0 {
		viewH = t.listHeight
		total = 0
		off = 0
		for i, r := range t.results {
			h := 1
			if t.variableHeights() {
				h = t.itemLineCount(r.item)
			}
			if i < t.offset {
				off += h + t.gap
			}
			total += h + t.gap
		}
		if total > 0 {
			total -= t.gap
		}
	} else {
		viewH = t.maxItems()
		total = count
		off = t.offset
	}
	if total <= viewH {
		return
	}
	barLen := max(1, viewH*viewH/total)
	maxOffset := total - viewH
	barStart := 0
	if maxOffset > 0 {
		barStart = min(viewH-barLen, int(float64(viewH-barLen)*float64(off)/float64(maxOffset)))
	}
	x := m.left + m.width - 1
	if t.scrollbarOutside {
		x = m.left + m.width
	}
	for i := barStart; i < barStart+barLen && i < t.listHeight; i++ {
		var y int
		if t.layout == layoutDefault {
			y = t.listBottom - i
		} else {
			y = t.listTop + i
		}
		t.screen.setCell(y, x, t.scrollbar, 1, p.scrollbar.fg, p.scrollbar.bg, p.scrollbar.attr)
	}
}

func (t *Terminal) scrollbarGeometry(total, height int) (int, int) {
	barLength := max(1, height*height/total)
	maxOffset := total - height
	barStart := 0
	if maxOffset > 0 {
		barStart = int(float64(height-barLength) * float64(t.offset) / float64(maxOffset))
		barStart = min(height-barLength, barStart)
	}
	_ = strconv.Itoa
	return barLength, barStart
}

func (t *Terminal) renderItemBlock(rows []int, left, maxX int, r Result, current bool, p palette) {
	item := r.item
	selected := t.isSelected(item)
	h := len(rows)
	// gutter/pointer/marker on each row
	for k, y := range rows {
		if y < t.listTop || y > t.listBottom {
			continue
		}
		x := left
		jumpIdx := -1
		if t.jumping > 0 && k == 0 {
			jumpIdx = t.rowIndexOf(item)
		}
		if jumpIdx >= 0 && jumpIdx < len(t.opts.JumpLabels) {
			label := string(t.opts.JumpLabels[jumpIdx])
			t.putString(y, x, x+t.pointerLen, padRight(label, t.pointerLen), p.cursor)
		} else if current {
			t.putString(y, x, x+t.pointerLen, padRight(t.pointer, t.pointerLen), p.cursor)
		} else {
			g := t.gutter
			gw := stringWidth(g)
			t.putString(y, x, x+gw, g, p.gutter)
			if t.pointerLen > gw {
				t.putString(y, x+gw, left+t.pointerLen, strings.Repeat(" ", t.pointerLen-gw), style{colDefault, p.bg, 0})
			}
		}
		x = left + t.pointerLen
		mst := p.marker
		est := style{colDefault, p.bg, 0}
		if current {
			mst = p.currentMarker
			est = style{p.normal.fg, p.darkBg, 0}
		}
		if selected {
			mk := t.marker
			if h > 1 {
				mm := t.markerMulti()
				if k == 0 {
					mk = mm[0]
				} else if k == h-1 {
					mk = mm[2]
				} else {
					mk = mm[1]
				}
			}
			t.putString(y, x, x+t.markerLen, padRight(mk, t.markerLen), mst)
		} else {
			t.putString(y, x, x+t.markerLen, t.markerEmpty, est)
		}
	}
	textX := left + t.pointerLen + t.markerLen
	base := p.normal
	hl := p.match
	if current {
		base = p.current
		hl = p.currentMatch
	} else if selected {
		base = p.selected
		hl = p.selectedMatch
	}
	if h == 1 && !t.wrap {
		y := rows[0]
		end := t.printHighlighted(y, textX, maxX, item, base, hl, current)
		if current && t.cursorLine {
			t.fillRow(y, end, maxX, style{base.fg, p.darkBg, 0})
		}
		return
	}
	t.printBlock(rows, textX, maxX, item, base, hl, current, p)
}

func (t *Terminal) markerMulti() [3]string {
	if t.opts.MarkerMulti != nil {
		return *t.opts.MarkerMulti
	}
	if t.opts.Unicode {
		return [3]string{"╻", "┃", "╹"}
	}
	return [3]string{".", "|", "'"}
}

// printBlock renders a multi-row (multi-line or wrapped) item
func (t *Terminal) printBlock(rows []int, x0, maxX int, item *Item, base, hl style, current bool, p palette) {
	styles, runes := t.itemStyles(item, base, hl, current)
	lines := t.splitItemLines(item)
	k := 0
	ri := 0
	sign := t.wrapSign()
	signW := stringWidth(sign)
	for li, line := range lines {
		_ = li
		x := x0
		col := 0
		if k >= len(rows) {
			break
		}
		y := rows[k]
		for _, r := range line {
			st := styles[min(ri, len(styles)-1)]
			ri++
			w := runeWidth(r)
			if r == '\\t' {
				w = t.opts.Tabstop - col%t.opts.Tabstop
			}
			if r < 0x20 && r != '\\t' {
				continue
			}
			if x+w > maxX {
				if !t.wrap {
					continue
				}
				if current && t.cursorLine {
					t.fillRow(y, x, maxX, style{base.fg, p.darkBg, 0})
				}
				k++
				if k >= len(rows) {
					break
				}
				y = rows[k]
				x = x0
				col = 0
				sst := style{base.fg, base.bg, base.attr | tAttrDim}
				x = t.putString(y, x, maxX, sign, sst)
				_ = signW
			}
			if y >= t.listTop && y <= t.listBottom {
				if r == '\\t' {
					for i := 0; i < w; i++ {
						t.screen.setCell(y, x+i, " ", 1, st.fg, st.bg, st.attr)
					}
				} else if w > 0 {
					t.screen.setCell(y, x, string(r), w, st.fg, st.bg, st.attr)
				}
			}
			x += w
			col += w
		}
		if current && t.cursorLine && k < len(rows) {
			t.fillRow(rows[k], x, maxX, style{base.fg, p.darkBg, 0})
		}
		ri++ // newline
		k++
	}
	_ = runes
}

func (t *Terminal) itemStyles(item *Item, base, hl style, current bool) ([]style, []rune) {
	runes := item.text.ToRunes()
	var posSet map[int]bool
	if t.lastPattern != nil && !t.lastPattern.IsEmpty() {
		_, _, pos := t.lastPattern.MatchItem(item, true)
		if pos != nil {
			posSet = make(map[int]bool, len(*pos))
			for _, p := range *pos {
				posSet[p] = true
			}
		}
	}
	styles := make([]style, len(runes)+1)
	for i := range styles {
		styles[i] = base
	}
	if item.colors != nil {
		for _, off := range *item.colors {
			b, e := int(off.offset[0]), int(off.offset[1])
			for i := b; i < e && i < len(runes); i++ {
				styles[i] = mergeAnsi(base, off.color)
			}
		}
	}
	for i := range runes {
		if posSet[i] {
			if item.colors != nil {
				styles[i] = style{hl.fg, styles[i].bg, styles[i].attr | hl.attr}
			} else {
				styles[i] = hl
			}
		}
	}
	return styles, runes
}

