output.arguments:
{"command":"cd /workspace && cat > tmux.go <<'EOF'
package main

import (
	"fmt"
	"io"
	"os"
	"os/exec"
	"sort"
	"strconv"
	"strings"
	"syscall"
)

func sizeArg(s sizeSpec) string {
	if s.percent {
		return strconv.Itoa(int(s.size)) + "%"
	}
	return strconv.Itoa(int(s.size))
}

func runTmuxProxy(opts *Options, args []string) int {
	t := opts.Tmux
	cwd, _ := os.Getwd()
	popupArgs := []string{"display-popup", "-E", "-d", cwd}
	if !t.border {
		popupArgs = append(popupArgs, "-B")
	}
	switch t.position {
	case posUp:
		popupArgs = append(popupArgs, "-xC", "-y0")
	case posDown:
		popupArgs = append(popupArgs, "-xC", "-y9999")
	case posLeft:
		popupArgs = append(popupArgs, "-x0", "-yC")
	case posRight:
		popupArgs = append(popupArgs, "-xR", "-yC")
	default:
		popupArgs = append(popupArgs, "-xC", "-yC")
	}
	popupArgs = append(popupArgs, "-w"+sizeArg(t.width), "-h"+sizeArg(t.height))

	script, err := os.CreateTemp("", "fzf-temp-*")
	if err != nil {
		errorExit(err.Error())
	}
	scriptPath := script.Name()
	defer os.Remove(scriptPath)
	defer os.Remove(scriptPath + ".exit")

	exe, _ := os.Executable()
	var sb strings.Builder
	sb.WriteString("FZF_DEFAULT_COMMAND=\nFZF_DEFAULT_OPTS=\nFZF_DEFAULT_OPTS_FILE=\n")
	env := os.Environ()
	sort.SliceStable(env, func(i, j int) bool { return false })
	for _, kv := range env {
		idx := strings.Index(kv, "=")
		if idx <= 0 {
			continue
		}
		k := kv[:idx]
		if k == "FZF_DEFAULT_COMMAND" || k == "FZF_DEFAULT_OPTS" || k == "FZF_DEFAULT_OPTS_FILE" {
			continue
		}
		valid := true
		for _, c := range k {
			if !(c == '_' || c >= 'a' && c <= 'z' || c >= 'A' && c <= 'Z' || c >= '0' && c <= '9') {
				valid = false
				break
			}
		}
		if !valid {
			continue
		}
		sb.WriteString("export " + k + "=" + quoteShell(kv[idx+1:]) + "\n")
	}
	cmdParts := []string{quoteShell(exe), quoteShell("--bind=ctrl-z:ignore")}
	for _, a := range args {
		cmdParts = append(cmdParts, quoteShell(a))
	}
	if !t.border && opts.BorderShape == BorderUndefined {
		cmdParts = append(cmdParts, quoteShell("--border=rounded"))
	}
	inPath := ""
	outPath := fmt.Sprintf("/tmp/fzf-proxy-output-%d", os.Getpid())
	syscall.Mkfifo(outPath, 0600)
	defer os.Remove(outPath)
	stdinIsTTY := isTerminal(os.Stdin)
	cmdParts = append(cmdParts, "--no-tmux", "--no-height", "--no-force-tty-in", "--proxy-script", "\"$0\"")
	if !stdinIsTTY {
		inPath = fmt.Sprintf("/tmp/fzf-proxy-input-%d", os.Getpid())
		syscall.Mkfifo(inPath, 0600)
		defer os.Remove(inPath)
		cmdParts = append(cmdParts, "<", "\""+inPath+"\"")
	}
	cmdParts = append(cmdParts, ">", "\""+outPath+"\"")
	sb.WriteString(strings.Join(cmdParts, " ") + "\n")
	script.WriteString(sb.String())
	script.Close()

	popupArgs = append(popupArgs, "sh", scriptPath)
	cmd := exec.Command("tmux", popupArgs...)
	cmd.Stderr = os.Stderr
	cmd.Stdout = os.Stdout
	done := make(chan struct{})
	outDone := make(chan struct{})
	if inPath != "" {
		go func() {
			f, err := os.OpenFile(inPath, os.O_WRONLY, 0)
			if err == nil {
				io.Copy(f, os.Stdin)
				f.Close()
			}
		}()
	}
	go func() {
		defer close(outDone)
		f, err := os.OpenFile(outPath, os.O_RDONLY, 0)
		if err == nil {
			io.Copy(os.Stdout, f)
			f.Close()
		}
	}()
	err = cmd.Run()
	close(done)
	code := 0
	if err != nil {
		if ee, ok := err.(*exec.ExitError); ok {
			code = ee.ExitCode()
		} else {
			code = exitError
		}
		// unblock fifo readers/writers
		if f, e := os.OpenFile(outPath, os.O_WRONLY|syscall.O_NONBLOCK, 0); e == nil {
			f.Close()
		}
		return code
	}
	// wait for output
	if f, e := os.OpenFile(outPath, os.O_WRONLY|syscall.O_NONBLOCK, 0); e == nil {
		f.Close()
	}
	<-outDone
	if data, e := os.ReadFile(scriptPath + ".exit"); e == nil {
		if n, e := strconv.Atoi(strings.TrimSpace(string(data))); e == nil {
			code = n
		}
	}
	return code
}
EOF
