	go func() {
		for {
			conn, err := ln.Accept()
			if err != nil {
				return
			}
			go t.handleConn(conn)
		}
	}()
	return nil
}

func httpResponse(status string, body string, contentType string) []byte {
	var b bytes.Buffer
	b.WriteString("HTTP/1.1 " + status + "\r\n")
	if contentType != "" {
		b.WriteString("Content-Type: " + contentType + "\r\n")
	}
	if body != "" {
		b.WriteString("Content-Length: " + strconv.Itoa(len(body)) + "\r\n")
	}
	b.WriteString("\r\n")
	b.WriteString(body)
	return b.Bytes()
}

func (t *Terminal) handleConn(conn net.Conn) {
	defer conn.Close()
	conn.SetDeadline(time.Now().Add(10 * time.Second))
	reader := bufio.NewReader(conn)
	line, err := reader.ReadString('\n')
	if err != nil {
		return
	}
	parts := strings.Fields(strings.TrimSpace(line))
	if len(parts) < 2 {
		conn.Write(httpResponse("400 Bad Request", "invalid request method\n", ""))
		return
	}
	method, path := parts[0], parts[1]
	headers := map[string]string{}
	for {
		h, err := reader.ReadString('\n')
		if err != nil {
			return
		}
		h = strings.TrimRight(h, "\r\n")
		if h == "" {
			break
		}
		if idx := strings.Index(h, ":"); idx > 0 {
			headers[strings.ToLower(strings.TrimSpace(h[:idx]))] = strings.TrimSpace(h[idx+1:])
		}
	}
	if key := os.Getenv("FZF_API_KEY"); key != "" {
		if headers["x-api-key"] != key {
			conn.Write(httpResponse("401 Unauthorized", "invalid api key\n", ""))
			return
		}
	}
	switch {
	case method == "GET" && (path == "/" || strings.HasPrefix(path, "/?")):
		limit, offset := 100, 0
		if idx := strings.Index(path, "?"); idx >= 0 {
			for _, kv := range strings.Split(path[idx+1:], "&") {
				p := strings.SplitN(kv, "=", 2)
				if len(p) != 2 {
					continue
				}
				n, err := strconv.Atoi(p[1])
				if err != nil {
					continue
				}
				switch p[0] {
				case "limit":
					limit = n
				case "offset":
					offset = n
				}
			}
		}
		req := &serverRequest{getState: true, limit: limit, offset: offset, response: make(chan []byte, 1)}
		t.serverCh <- req
		select {
		case body := <-req.response:
			conn.Write(httpResponse("200 OK", string(body), "application/json"))
		case <-time.After(5 * time.Second):
		}
	case method == "POST" && (path == "/" || strings.HasPrefix(path, "/?")):
		cl, ok := headers["content-length"]
		if !ok {
			conn.Write(httpResponse("400 Bad Request", "content-length header missing\n", ""))
			return
		}
		n, err := strconv.Atoi(cl)
		if err != nil || n < 0 {
			conn.Write(httpResponse("400 Bad Request", "invalid content length\n", ""))
			return
		}
		body := make([]byte, n)
		if _, err := io.ReadFull(reader, body); err != nil {
			return
		}
		acts, err := parseServerActions(string(body))
		if err != nil {
			conn.Write(httpResponse("400 Bad Request", err.Error()+"\n", ""))
			return
		}
		req := &serverRequest{actions: acts, response: make(chan []byte, 1)}
		t.serverCh <- req
		conn.Write([]byte("HTTP/1.1 200 OK\r\n\r\n"))
	default:
		conn.Write(httpResponse("400 Bad Request", "invalid request method\n", ""))
	}
}

func parseServerActions(body string) ([]*action, error) {
	body = strings.TrimSpace(body)
	if body == "" {
		return nil, errors.New("no action specified")
	}
	masked := maskActionContents(":" + body)[1:]
	masked = strings.ReplaceAll(masked, string([]rune{escapedColon}), ":")
	masked = strings.ReplaceAll(masked, string([]rune{escapedComma}), ",")
	masked = strings.ReplaceAll(masked, string([]rune{escapedPlus}), "+")
	return parseActionList(masked, body, nil, false, "")
}

func (t *Terminal) handleServerRequest(req *serverRequest) {
	if req.getState {
		state := jsonState{
			Reading:    t.reading,
			Progress:   100,
			Query:      string(t.input),
			Position:   t.cy,
			Sort:       t.sort,
			TotalCount: t.total,
			MatchCount: len(t.results),
			Matches:    []jsonItem{},
			Selected:   []jsonItem{},
		}
		if cur := t.currentItem(); cur != nil {
			state.Current = &jsonItem{cur.index, t.itemText(cur)}
		}
		for i := req.offset; i < len(t.results) && i < req.offset+req.limit; i++ {
			it := t.results[i].item
			state.Matches = append(state.Matches, jsonItem{it.index, t.itemText(it)})
		}
		sels := t.sortedSelection()
		for i := req.offset; i < len(sels) && i < req.offset+req.limit; i++ {
			it := sels[i].item
			state.Selected = append(state.Selected, jsonItem{it.index, t.itemText(it)})
		}
		var buf bytes.Buffer
		enc := json.NewEncoder(&buf)
		enc.Encode(state)
		req.response <- buf.Bytes()
		return
	}
	t.doActions(req.actions, Event{Type: Invalid})
	t.onQueryMaybeChanged()
	t.afterAction()
	_ = fmt.Sprint
}
